#!/usr/bin/env python3
# AI-hint: Runtime and unit gates in one module: container names, privileged Quadlets, service URLs, daemon governor coverage, firstboot degrade-open, firstboot provisioners, artifact verification and resolver twin equivalence. The subcommand selects the gate.
# AI-doc: usr/share/doc/mios/manual/tools.md
# AI-related: tools/verify-images.py, usr/lib/mios/mios_toml.py, usr/lib/mios/userenv.sh
"""Runtime, unit and resolver gates. One module, one subcommand per gate."""
from __future__ import annotations

import sys


"""Gate: every Quadlet declares a ContainerName that matches its unit."""

import glob
import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover -- py<3.11
    import tomli as tomllib  # type: ignore

cn_TOML = "usr/share/mios/mios.toml"
cn_QUADLET_GLOB = "usr/share/containers/systemd/*.container"

def cn_expected_name(unit: str) -> str:
    """A template unit has no single container: it names the instantiated form."""
    if unit.endswith("@"):
        return unit[:-1] + "-%i"
    return unit

def cn_ssot_containers(root: str) -> tuple:
    """({unit: ContainerName}, {unit: enabled}) from the SSOT. A container gated
    off in [quadlets.enable] renders no unit, which is not drift -- but it still
    has to name itself correctly for the day it is switched on."""
    path = os.path.join(root, cn_TOML)
    if not os.path.isfile(path):
        return {}, {}
    with open(path, "rb") as fh:
        data = tomllib.load(fh) or {}
    enabled = (data.get("quadlets") or {}).get("enable") or {}
    out = {}
    for name, block in (data.get("containers") or {}).items():
        if isinstance(block, dict) and isinstance(block.get("Container"), dict):
            out[str(name)] = str(block["Container"].get("ContainerName") or "")
    return out, {k: v is not False for k, v in enabled.items()}

def cn_rendered_containers(root: str) -> dict:
    out = {}
    for g in (cn_QUADLET_GLOB, "usr/share/containers/systemd/users/*.container"):
        for path in sorted(glob.glob(os.path.join(root, g))):
            unit = os.path.basename(path)[: -len(".container")]
            text = open(path, encoding="utf-8", errors="replace").read()
            m = re.search(r"^ContainerName=(.*)$", text, re.M)
            out[unit] = (m.group(1).strip() if m else "")
    return out

def cn_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT", ".")
    ssot, enabled = cn_ssot_containers(root)
    rendered = cn_rendered_containers(root)
    if not ssot:
        print(f"no [containers.*.Container] blocks found under {root}")
        return 1
    if not rendered:
        print(f"no rendered .container files found under {root}")
        return 1

    problems = []
    for unit in sorted(ssot):
        want = cn_expected_name(unit)
        got = ssot[unit]
        if not got:
            problems.append(
                f"{unit}: no ContainerName in the SSOT -- Quadlet would name it "
                f"'systemd-{unit}', which no `systemctl` name matches")
        elif got != want:
            problems.append(f"{unit}: SSOT ContainerName is {got!r}, expected {want!r}")
    for unit in sorted(rendered):
        want = cn_expected_name(unit)
        got = rendered[unit]
        if not got:
            problems.append(f"{unit}.container: rendered unit declares no ContainerName")
        elif got != want:
            problems.append(
                f"{unit}.container: rendered ContainerName is {got!r}, expected {want!r}")
    for unit in sorted(set(ssot) - set(rendered)):
        if enabled.get(unit, True):
            problems.append(
                f"{unit}: enabled in the SSOT but no rendered .container -- regenerate")

    if problems:
        for p in problems:
            print(p)
        return 1
    off = sum(1 for u in ssot if not enabled.get(u, True))
    print(f"every Quadlet names its own container "
          f"(ssot={len(ssot)} rendered={len(rendered)} gated-off={off})")
    return 0

"""Gate: Privileged Quadlets register is minimal, ratcheted, and every entry justified."""

import os
import re
import sys

try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

pq_MIOS_TOML_RELATIVE = "usr/share/mios/mios.toml"

def pq_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT", os.environ.get("MIOS_TOML_ROOT", "."))
    path = os.path.join(root, pq_MIOS_TOML_RELATIVE)
    if not os.path.isfile(path):
        print(f"VIOLATION: {pq_MIOS_TOML_RELATIVE} not found under {root}")
        return 1

    with open(path, "r", encoding="utf-8", errors="replace") as f:
        content = f.read()

    # Extract [security.privileged_quadlets] block and check lines
    lines = content.splitlines()
    in_block = False
    in_root_array = False

    max_privileged_root = None
    root_entries = []

    for line in lines:
        line_clean = line.strip()
        if line_clean == "[security.privileged_quadlets]":
            in_block = True
            continue
        elif in_block and line_clean.startswith("["):
            in_block = False
            in_root_array = False

        if in_block:
            if line_clean.startswith("max_privileged_root"):
                parts = line_clean.split("=")
                if len(parts) == 2:
                    try:
                        max_privileged_root = int(parts[1].strip())
                    except ValueError:
                        pass
            elif line_clean.startswith("root = ["):
                in_root_array = True
                continue

            if in_root_array:
                if line_clean.startswith("]"):
                    in_root_array = False
                elif line_clean:
                    # e.g., "mios-ceph.container", # comment
                    m = re.search(r'"([^"]+\.container)"\s*,?\s*(#.*)?', line_clean)
                    if m:
                        unit_name = m.group(1)
                        comment = m.group(2)
                        root_entries.append((unit_name, comment))

    problems = []

    if max_privileged_root is None:
        problems.append("VIOLATION: [security.privileged_quadlets].max_privileged_root is not declared")
    else:
        actual_count = len(root_entries)
        if actual_count > max_privileged_root:
            problems.append(
                f"VIOLATION: privileged root count ({actual_count}) exceeds max_privileged_root ceiling ({max_privileged_root})"
            )

    for unit, comment in root_entries:
        if not comment or len(comment.strip("# ").strip()) < 5:
            problems.append(
                f"VIOLATION: privileged Quadlet '{unit}' lacks required capability justification comment"
            )

    if problems:
        for p in problems:
            print(p)
        return 1

    print(
        f"Privileged Quadlets register minimal & justified (entries={len(root_entries)}, max_ceiling={max_privileged_root})"
    )
    return 0

"""Gate: one canonical address per service, or a registered reason there is none."""

import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover -- py<3.11
    import tomli as tomllib  # type: ignore

su_TOML = "usr/share/mios/mios.toml"
# The canonical, path-derived name of [ports].<key>. The retired MIOS_PORT_<KEY>
# spelling is only an input alias now, so a [urls] entry templated with it does
# not count as the port's canonical address.
su__PORT_VAR = re.compile(r"\$\{MIOS_PORTS_([A-Z0-9_]+)\}")

def su_port_keys(data: dict) -> set:
    """Numeric [ports] keys. stack_id is an offset, not a port."""
    ports = (data.get("ports") or {})
    return {k for k, v in ports.items() if isinstance(v, int) and k != "stack_id"}

def su_covered_ports(data: dict) -> set:
    """Port keys templated by at least one [urls] string."""
    out = set()
    for value in (data.get("urls") or {}).values():
        if not isinstance(value, str):
            continue
        for m in su__PORT_VAR.finditer(value):
            out.add(m.group(1).lower())
    return out

def su_register(data: dict) -> list:
    """The shrink-only non-addressable register, in declaration order."""
    reg = (data.get("urls") or {}).get("non_addressable") or []
    return [str(x).strip() for x in reg if str(x).strip()]

def su_classify(data: dict) -> list:
    """Return the violations; empty means every port has exactly one answer."""
    viol = []
    keys = su_port_keys(data)
    if not keys:
        return ["[ports] declares no numeric port -- the gate would pass "
                "vacuously over an empty set"]

    covered = su_covered_ports(data) & keys
    reg = su_register(data)
    reg_set = set(reg)

    if len(reg) != len(reg_set):
        dupes = sorted({k for k in reg if reg.count(k) > 1})
        viol.append("[urls].non_addressable lists a key twice: %s" % ", ".join(dupes))

    for k in sorted(reg_set - keys):
        viol.append("[urls].non_addressable names '%s', which is not a [ports] key "
                    "-- a register entry must name a port that exists" % k)

    for k in sorted(covered & reg_set):
        viol.append("port '%s' has a [urls] entry AND sits in non_addressable -- "
                    "two answers is the drift this gate exists to prevent" % k)

    for k in sorted(keys - covered - reg_set):
        viol.append("port '%s' has no canonical [urls] address and is not in "
                    "[urls].non_addressable -- state how it is addressed" % k)

    return viol

def su_browser_openable(data: dict) -> list:
    """[urls] is what a person clicks, so every value must use a scheme a
    browser opens. A postgresql:// DSN there made the table mean two things."""
    viol = []
    for key, value in sorted((data.get("urls") or {}).items()):
        if not isinstance(value, str):
            continue
        if "://" not in value:
            viol.append("[urls].%s is not a URL: %r" % (key, value))
        elif value.split("://", 1)[0] not in ("http", "https"):
            viol.append("[urls].%s uses the %s scheme -- [urls] is the "
                        "browser-openable surface, so an inter-service address "
                        "belongs on the key its consumers already resolve"
                        % (key, value.split("://", 1)[0]))
    return viol

def su_bare_port_addresses(data: dict) -> list:
    """A localhost URL with a BARE port cannot be offloaded: there is no key for
    an /etc/mios overlay to move, so the address is pinned to this machine."""
    ports = {v: k for k, v in (data.get("ports") or {}).items()
             if isinstance(v, int)}
    url = re.compile(r"(?:https?|ws|postgresql)://(?:localhost|127\.0\.0\.1)[:/]?(\d+)")
    # Rendered unit/container bodies carry ${VAR:-N} defaults by design; the
    # operator-tunable sections are what an overlay has to be able to move.
    skip = ("units.", "containers.", "comment")
    viol = []

    def walk(node, path):
        if isinstance(node, dict):
            for k, v in node.items():
                walk(v, path + [str(k)])
        elif isinstance(node, list):
            for i, v in enumerate(node):
                walk(v, path + ["[%d]" % i])
        elif isinstance(node, str):
            dotted = ".".join(path)
            if any(sk in dotted for sk in skip):
                return
            for m in url.finditer(node):
                num = int(m.group(1))
                if num in ports:
                    viol.append("%s hardcodes :%d instead of "
                                "${MIOS_PORTS_%s} -- an /etc/mios overlay cannot "
                                "move a baked port, so the service can never be "
                                "offloaded" % (dotted, num, ports[num].upper()))

    walk(data, [])
    return viol

def su_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or "."
    path = os.path.join(root, su_TOML)
    try:
        with open(path, "rb") as fh:
            data = tomllib.load(fh)
    except OSError as exc:
        print("check-service-urls: cannot read %s: %s" % (path, exc), file=sys.stderr)
        return 1

    viol = su_classify(data) + su_browser_openable(data) + su_bare_port_addresses(data)
    if viol:
        for v in viol:
            print("check_service_urls: %s" % v, file=sys.stderr)
        return 1

    keys, covered, reg = su_port_keys(data), su_covered_ports(data), su_register(data)
    print("[check-service-urls] %d port(s): %d addressed by [urls], %d registered "
          "non-addressable" % (len(keys), len(covered & keys), len(reg)))
    return 0

"""Fail if the daemon governor has a hole: an ungated loop, a dead knob, or a drifted fallback."""
import os
import re
import subprocess
import sys
import tomllib

dg_ROOT = os.environ.get("MIOS_ROOT", ".")
dg_DAEMON = os.path.join(dg_ROOT, "usr/libexec/mios/mios-daemon")
dg_SSOT = os.path.join(dg_ROOT, "usr/share/mios/mios.toml")
dg_CHAT = os.path.join(dg_ROOT, "usr/lib/mios/agent-pipe/mios_pipe/routing/chat.py")

# Loops that serve interactive requests rather than initiating autonomous work;
# gating these would throttle a human, which is the opposite of the intent.
dg_EXEMPT_LOOPS = {"daemon_agent_server_loop"}
# Knobs consumed outside the daemon (agent-pipe owns the budget plane).
dg_ELSEWHERE = {"conversation_token_ceil", "autonomous_token_ceil",
             "autonomous_max_inflight", "window_s"}

def dg_loops_missing_pressure_gate(src: str) -> list:
    lines = src.split("\n")
    starts = [(i, m.group(1)) for i, l in enumerate(lines)
              if (m := re.match(r"^def (\w+_loop)\(", l))]
    missing = []
    for idx, (i, name) in enumerate(starts):
        end = starts[idx + 1][0] if idx + 1 < len(starts) else len(lines)
        if name in dg_EXEMPT_LOOPS:
            continue
        if "_pressure_should_skip" not in "\n".join(lines[i:end]):
            missing.append(name)
    return missing

def dg__consumer_sources(root: str) -> list:
    """Code that may consume a knob: no test_* files, no comment lines -- a knob
    merely NAMED in a docstring or an AI-hint is not a consumer."""
    out = []
    for base in ("usr/libexec/mios", "usr/lib/mios"):
        for dirpath, _, names in os.walk(os.path.join(root, base)):
            if "__pycache__" in dirpath:
                continue
            for n in names:
                if n.startswith("test_") or not (n.endswith(".py") or n.startswith("mios-")):
                    continue
                try:
                    text = open(os.path.join(dirpath, n), encoding="utf-8",
                                errors="replace").read()
                except OSError:
                    continue
                code = "\n".join(l for l in text.split("\n")
                                 if not l.lstrip().startswith("#"))
                out.append(code)
    return out

def dg_dead_knobs(root: str, keys: list) -> list:
    sources = dg__consumer_sources(root)
    dead = []
    for key in keys:
        if key in dg_ELSEWHERE:
            continue
        if not any(f'"{key}"' in s or f"'{key}'" in s for s in sources):
            dead.append(key)
    return dead

def dg_drifted_fallbacks(ssot: dict) -> list:
    if not os.path.isfile(dg_CHAT):
        return []
    text = open(dg_CHAT, encoding="utf-8").read()
    out = []
    for key, want in ssot.get("budget", {}).items():
        m = re.search(rf'"{key}",\s*([0-9_]+)', text)
        if m and int(m.group(1).replace("_", "")) != int(want):
            out.append(f"{key}: fallback {m.group(1)} != SSOT {want}")
    return out

def dg_main() -> int:
    src = open(dg_DAEMON, encoding="utf-8").read()
    data = tomllib.load(open(dg_SSOT, "rb"))
    daemon_keys = [k for k, v in data.get("daemon", {}).items() if not isinstance(v, dict)]
    budget_keys = [k for k, v in data.get("budget", {}).items() if not isinstance(v, dict)]
    bad = []
    bad += [f"autonomous loop without the host-pressure gate: {n}"
            for n in dg_loops_missing_pressure_gate(src)]
    bad += [f"SSOT knob declared but never consumed: [daemon].{k}"
            for k in dg_dead_knobs(dg_ROOT, daemon_keys)]
    bad += [f"agent-pipe budget fallback drifted from the SSOT -- {d}"
            for d in dg_drifted_fallbacks(data)]
    if bad:
        print("\n".join(bad), file=sys.stderr)
        return 1
    total = len(re.findall(r"^def \w+_loop\(", src, re.M))
    print(f"daemon governor complete ({total - len(dg_EXEMPT_LOOPS)} autonomous loops gated, "
          f"{len(daemon_keys)} [daemon] + {len(budget_keys)} [budget] knobs consumed)")
    return 0

"""Gate: no firstboot script aborts on an egress failure (Law 12).

Each egress call reached with errexit active must carry a fallback.
The scoping rules are stated inline beside the patterns below.
"""

import glob
import os
import re
import sys

fdo_EGRESS = re.compile(
    r"\b(curl|wget|podman\s+pull|skopeo\s+copy|dnf\s+(install|upgrade)|"
    r"git\s+clone|bootc\s+(switch|upgrade)|pip\s+install|hf\s+download|"
    r"huggingface-cli\s+download|rpm-ostree|flatpak\s+install)\b")
# errexit does not fire on a condition or on the left of a && list.
fdo_GUARD = re.compile(
    r"\|\||^\s*(if|while|until|elif)\s|&&\s*(true|:|return|exit)|\|\|\s*(return|exit)")
# Column-0 only: an indented 'set +e' is inside a function or subshell
# and must not exempt later top-level lines.
fdo_SETE = re.compile(r"^set\s+-[a-zA-Z]*e|^set\s+-o\s+errexit")
# 'trap ... EXIT' is deliberately NOT an escape: it runs a handler, it does
# not stop errexit aborting an unguarded fetch.
fdo_SETPE = re.compile(r"^set\s+\+[a-zA-Z]*e|^set\s+\+o\s+errexit")
# A fetch named inside a log/echo string is documentation, not a call.
fdo_NARRATION = re.compile(r"^\s*(_?log\w*|echo|printf|cat|#)\b")

fdo_SCAN_GLOBS = ("usr/libexec/mios/*firstboot*", "automation/firstboot/*.sh")
fdo_SKIP_SUFFIXES = (".pyc", ".bak", ".keep", ".orig", ".rej")


def fdo_logical_lines(lines):
    """Join continuations and parenthesised runs into one logical line each.

    The guard usually lands after a continuation or a closing paren, so a
    physical scan reports guarded calls as unguarded.
    """
    out, buf, start, depth = [], "", None, 0
    for num, line in enumerate(lines, 1):
        if start is None:
            start = num
        stripped = line.rstrip()
        buf += stripped[:-1] if stripped.endswith("\\") else line
        depth = max(0, depth + line.count("(") - line.count(")"))
        if stripped.endswith("\\") or depth > 0:
            buf += " "
            continue
        out.append((start, buf))
        buf, start = "", None
    if buf:
        out.append((start or len(lines), buf))
    return out


def fdo_scan(path):
    try:
        with open(path, encoding="utf-8", errors="replace") as handle:
            lines = handle.read().split("\n")
    except OSError as exc:
        return [(0, "unreadable: %s" % exc)]
    errexit, bad = False, []
    for num, line in fdo_logical_lines(lines):
        if line.lstrip().startswith("#") or fdo_NARRATION.search(line):
            continue
        if fdo_SETE.search(line):
            errexit = True
        if fdo_SETPE.search(line):
            errexit = False
        if errexit and fdo_EGRESS.search(line) and not fdo_GUARD.search(line):
            bad.append((num, " ".join(line.split())[:100]))
    return bad


def fdo_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.getcwd()
    files = []
    for pattern in fdo_SCAN_GLOBS:
        files.extend(glob.glob(os.path.join(root, pattern)))
    files = sorted(f for f in files
                   if os.path.isfile(f) and not f.endswith(fdo_SKIP_SUFFIXES))

    if not files:
        # An empty scan set is never a pass: the globs are the gate's subject.
        print("no firstboot scripts matched %s -- the gate has no subject"
              % ", ".join(fdo_SCAN_GLOBS))
        return 1

    findings = []
    for path in files:
        rel = os.path.relpath(path, root).replace(os.sep, "/")
        for num, text in fdo_scan(path):
            findings.append(
                "%s:%d does not degrade open (Law 12): egress call runs under "
                "active set -e with no fallback -- %s" % (rel, num, text))

    if findings:
        for line in findings:
            print(line)
        return 1

    print("%d firstboot script(s) scanned; every egress call degrades open"
          % len(files))
    return 0

"""Gate: every first-boot provisioner triple (fetcher + unit + preset) is whole."""

import os
import re
import sys

# unit basename -> (libexec fetcher, /var dirs the fetcher writes into)
fp_PROVISIONERS = {
    "mios-models-firstboot.service": (
        "usr/libexec/mios/mios-models-firstboot",
        ("/var/lib/mios/llamacpp/models",),
    ),
}

fp_UNIT_DIR = "usr/lib/systemd/system"
fp_PRESET = "usr/lib/systemd/system-preset/90-mios.preset"
fp_TMPFILES_DIR = "usr/lib/tmpfiles.d"

def fp_tmpfiles_dirs(root: str) -> set:
    """Every directory path declared by a tmpfiles.d d/D/v/f line."""
    out = set()
    d = os.path.join(root, fp_TMPFILES_DIR)
    if not os.path.isdir(d):
        return out
    for fn in sorted(os.listdir(d)):
        if not fn.endswith(".conf"):
            continue
        with open(os.path.join(d, fn), encoding="utf-8", errors="replace") as fh:
            for line in fh:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                parts = line.split()
                if len(parts) >= 2 and parts[0] in ("d", "D", "v", "f", "F"):
                    out.add(parts[1])
    return out

def fp_unit_field(text: str, key: str):
    m = re.search(r"^%s\s*=\s*(.*)$" % re.escape(key), text, re.M)
    return m.group(1).strip() if m else None

def fp_check_one(root, unit_name, fetcher_rel, var_dirs, declared):
    bad = []
    unit_path = os.path.join(root, fp_UNIT_DIR, unit_name)
    fetcher_path = os.path.join(root, fetcher_rel)

    if not os.path.isfile(fetcher_path):
        bad.append(f"{unit_name}: fetcher {fetcher_rel} does not exist")
        return bad
    if not os.path.isfile(unit_path):
        bad.append(f"{unit_name}: unit file missing from {fp_UNIT_DIR}/")
        return bad

    unit = open(unit_path, encoding="utf-8", errors="replace").read()
    fetcher = open(fetcher_path, encoding="utf-8", errors="replace").read()

    execstart = fp_unit_field(unit, "ExecStart") or ""
    if "/" + fetcher_rel.split("usr/", 1)[-1] not in execstart.replace("/usr/", "/"):
        if os.path.basename(fetcher_rel) not in execstart:
            bad.append(f"{unit_name}: ExecStart does not run {fetcher_rel} "
                       f"(got {execstart!r})")

    cond = fp_unit_field(unit, "ConditionPathExists") or ""
    if not cond.startswith("!"):
        bad.append(f"{unit_name}: no ConditionPathExists=!<sentinel> gate "
                   f"(got {cond!r}) -- the oneshot would re-run every boot")
    else:
        sentinel = cond[1:].strip()
        if sentinel not in fetcher:
            bad.append(f"{unit_name}: gates on {sentinel} but the fetcher never "
                       f"names that path -- the sentinel is never written, so the "
                       f"unit runs forever")

    preset_path = os.path.join(root, fp_PRESET)
    if os.path.isfile(preset_path):
        preset = open(preset_path, encoding="utf-8", errors="replace").read()
        if not re.search(r"^enable\s+%s\s*$" % re.escape(unit_name), preset, re.M):
            bad.append(f"{unit_name}: not enabled in {fp_PRESET} -- installed but "
                       f"never started")
    else:
        bad.append(f"{fp_PRESET} is missing")

    for d in var_dirs:
        if d not in declared:
            bad.append(f"{unit_name}: writes {d}, which no tmpfiles.d file "
                       f"declares (Architectural Law 2: no mkdir in /var)")
    return bad

def fp_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or "."
    declared = fp_tmpfiles_dirs(root)
    bad = []
    for unit_name, (fetcher_rel, var_dirs) in sorted(fp_PROVISIONERS.items()):
        bad += fp_check_one(root, unit_name, fetcher_rel, var_dirs, declared)
    if bad:
        for line in bad:
            print(line)
        return 1
    print(f"first-boot provisioner triples are whole "
          f"(checked={len(fp_PROVISIONERS)} fetcher+unit+preset+tmpfiles)")
    return 0

"""Prove the artifact gate can fail.

`publish` depends on `verify-images` to establish that the artifacts it is
about to push are real. The version that shipped ended on a failure counter
that stays zero when the glob loop matches nothing, so an empty build tree
passed it. A gate that cannot fail is worth less than no gate, because the
pipeline is built as though it were checking something.

So this drives the real verifier three ways -- an empty tree, a complete set of
fixtures, and the same set with one artifact removed -- and fails unless the
verdicts come back reject, accept, reject-naming-the-missing-format. It also
holds the wiring in place: the recipe must delegate here, `publish` must depend
on it, and every format the `all` target builds must declare where its output
lands.
"""
import gzip
import io
import os
import re
import subprocess
import sys
import tarfile
import tempfile

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover - Python < 3.11
    import tomli as tomllib  # type: ignore

# One valid-enough artifact per format: the right leading bytes and enough of
# them to clear the size floor. Written as (relative path, builder key).
vi_FIXTURES = {
    "oci-archive":   ("oci-archive/mios-test.tar", "tar"),
    "raw":           ("raw/image/disk.raw", "raw"),
    "iso":           ("iso/bootiso/install.iso", "iso"),
    "usb-installer": ("usb-installer/install-usb.iso", "iso"),
    "qcow2":         ("qcow2/qcow2/disk.qcow2", "qcow2"),
    "vhdx":          ("vhdx/disk.vhdx", "vhdx"),
    "wsl2":          ("wsl2/mios-rootfs.tar.gz", "targz"),
}

def vi__write(path, blob):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "wb") as fh:
        fh.write(blob)

def vi__padded(size, *placed):
    """A buffer of `size` bytes with (offset, bytes) written into it."""
    buf = bytearray(b"\x00" * size)
    for offset, blob in placed:
        buf[offset:offset + len(blob)] = blob
    return bytes(buf)

def vi__build(kind, size):
    if kind == "iso":
        return vi__padded(size, (32769, b"CD001"))
    if kind == "qcow2":
        return vi__padded(size, (0, b"QFI\xfb"))
    if kind == "vhdx":
        return vi__padded(size, (0, b"vhdxfile"))
    if kind == "raw":
        return vi__padded(size, (510, b"\x55\xaa"), (512, b"EFI PART"))
    if kind in ("tar", "targz"):
        raw = io.BytesIO()
        with tarfile.open(fileobj=raw, mode="w") as tf:
            member = tarfile.TarInfo("rootfs/payload.bin")
            member.size = size
            tf.addfile(member, io.BytesIO(os.urandom(size)))
        if kind == "tar":
            return raw.getvalue()
        return gzip.compress(raw.getvalue(), 1)
    raise AssertionError(kind)

def vi_make_tree(outdir, size, skip=()):
    for name, (rel, kind) in sorted(vi_FIXTURES.items()):
        if name in skip:
            continue
        vi__write(os.path.join(outdir, *rel.split("/")), vi__build(kind, size))

def vi_run_verifier(root, outdir):
    proc = subprocess.run(
        [sys.executable, os.path.join(root, "tools", "verify-images.py"),
         "--root", root, "--output-dir", outdir],
        capture_output=True, text=True)
    return proc.returncode, (proc.stdout or "") + (proc.stderr or "")

def vi_structural(root, ssot, viol):
    jpath = os.path.join(root, "Justfile")
    if not os.path.isfile(jpath):
        viol.append("Justfile is missing, so nothing verifies anything")
        return
    with open(jpath, encoding="utf-8", errors="replace") as fh:
        just = fh.read()

    recipe = re.search(r"^verify-images:\n((?:[ \t]+[^\n]*\n|\n)*)", just, re.M)
    if not recipe:
        viol.append("the Justfile defines no verify-images recipe")
    elif "tools/verify-images.py" not in recipe.group(1):
        viol.append("the verify-images recipe no longer runs"
                    " tools/verify-images.py -- an inline glob loop is how this"
                    " gate came to pass over an empty tree")

    pub = re.search(r"^publish:([^\n]*)", just, re.M)
    if not pub:
        viol.append("the Justfile defines no publish recipe")
    elif "verify-images" not in pub.group(1).split():
        viol.append("publish no longer depends on verify-images, so the push is"
                    " guarded by nothing")

    formats = (ssot.get("deploy") or {}).get("formats") or {}
    by_target = {s.get("target"): n for n, s in formats.items()
                 if isinstance(s, dict)}
    built = re.search(r"^all:([^\n]*)", just, re.M)
    for target in (built.group(1).split() if built else []):
        if target == "build":
            continue
        name = by_target.get(target)
        if name is None:
            viol.append("the all target builds %r, which no [deploy.formats]"
                        " entry claims" % target)
            continue
        if not formats[name].get("artifacts"):
            viol.append("[deploy.formats.%s] declares no artifacts globs, so the"
                        " format the all target builds is one the verifier does"
                        " not require" % name)

def vi_behavioural(root, ssot, viol):
    floor = int(((ssot.get("deploy") or {})
                 .get("verify") or {}).get("min_bytes", 1048576))
    size = floor + 4096

    with tempfile.TemporaryDirectory(prefix="mios-verify-images-") as tmp:
        empty = os.path.join(tmp, "empty")
        os.makedirs(empty)
        rc, out = vi_run_verifier(root, empty)
        if rc == 0:
            viol.append("verify-images returned success over an empty build"
                        " tree -- this is the defect the gate exists to catch")
        for name in vi_FIXTURES:
            if name not in out:
                viol.append("verify-images did not name the missing format %r"
                            " when nothing was built" % name)

        full = os.path.join(tmp, "full")
        vi_make_tree(full, size)
        rc, out = vi_run_verifier(root, full)
        if rc != 0:
            viol.append("verify-images rejected a complete set of valid"
                        " artifacts (exit %d):\n%s" % (rc, out.strip()))

        for name in sorted(vi_FIXTURES):
            rel = vi_FIXTURES[name][0]
            path = os.path.join(full, *rel.split("/"))
            with open(path, "rb") as fh:
                blob = fh.read()
            os.remove(path)
            rc, out = vi_run_verifier(root, full)
            if rc == 0:
                viol.append("verify-images passed with the %s artifact deleted"
                            % name)
            elif name not in out:
                viol.append("verify-images failed with the %s artifact deleted"
                            " but did not name it" % name)
            vi__write(path, blob)

        corrupt = os.path.join(full, *vi_FIXTURES["qcow2"][0].split("/"))
        with open(corrupt, "rb") as fh:
            good = fh.read()
        vi__write(corrupt, b"\x00" * size)
        rc, _ = vi_run_verifier(root, full)
        if rc == 0:
            viol.append("verify-images passed a %d-byte run of zeroes named as a"
                        " qcow2 -- the header it prints is being compared"
                        " against nothing" % size)
        vi__write(corrupt, good)

def vi_main():
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or os.getcwd()
    with open(os.path.join(root, "usr/share/mios/mios.toml"), "rb") as fh:
        ssot = tomllib.load(fh)

    viol = []
    vi_structural(root, ssot, viol)
    if not os.path.isfile(os.path.join(root, "tools", "verify-images.py")):
        viol.append("tools/verify-images.py is absent, so the publish gate has"
                    " no implementation")
    else:
        vi_behavioural(root, ssot, viol)

    print("\n".join(viol))
    if viol:
        return 1
    print("[check-verify-images] an empty tree, a missing format and a corrupt"
          " artifact are each rejected by name", file=sys.stderr)
    return 0


import os
import sys
import re
import json
import subprocess
import shlex

def rt_main():
    root = os.environ.get("MIOS_DRIFT_ROOT")
    if not root:
        root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))

    os.environ["MIOS_VENDOR_TOML"] = os.path.join(root, "usr/share/mios/mios.toml").replace('\\', '/')
    os.environ["MIOS_HOST_TOML"] = os.path.join(root, "etc/mios/mios.toml").replace('\\', '/')
    os.environ["MIOS_USER_TOML"] = os.path.join(root, "nonexistent.toml").replace('\\', '/')
    os.environ["MIOS_VENDOR_TOML_D"] = os.path.join(root, "usr/lib/mios/mios.d").replace('\\', '/')
    os.environ["MIOS_HOST_TOML_D"] = os.path.join(root, "etc/mios/mios.d").replace('\\', '/')
    os.environ["MIOS_USER_TOML_D"] = os.path.join(root, "nonexistent_d").replace('\\', '/')

    lib_path = os.path.abspath(os.path.join(os.path.dirname(__file__), "../usr/lib/mios"))
    sys.path.insert(0, lib_path)
    if root:
        alt_path = os.path.join(root, "usr/lib/mios")
        if os.name == "nt" and alt_path.startswith("/mnt/c/"):
            alt_path = "C:/" + alt_path[7:]
        sys.path.insert(0, alt_path)
    try:
        import mios_toml
    except ImportError as e:
        print(f"Error: Could not import mios_toml: {e}", file=sys.stderr)
        sys.exit(1)

    env = os.environ.copy()

    _TIER_VARS = {
        "MIOS_ROOT", "MIOS_TOML", "MIOS_TOML_ROOT",
        "MIOS_VENDOR_TOML", "MIOS_VENDOR_TOML_D",
        "MIOS_HOST_TOML", "MIOS_HOST_TOML_D",
        "MIOS_USER_TOML", "MIOS_USER_TOML_D", "MIOS_PYTHON_BIN",
    }
    for _k in [k for k in env if k.startswith("MIOS_") and k not in _TIER_VARS]:
        env.pop(_k, None)

    env["MSYS_NO_PATHCONV"] = "1"
    env["PYTHONPATH"] = os.path.join(root, "usr/lib/mios").replace('\\', '/') + (os.pathsep + env["PYTHONPATH"] if "PYTHONPATH" in env else "")
    env.pop("MIOS_TOML_RESOLVED", None)

    bash_exe = "bash"
    if os.name == "nt":
        for path in [r"C:\Program Files\Git\bin\bash.exe", r"C:\Program Files\Git\usr\bin\bash.exe"]:
            if os.path.exists(path):
                bash_exe = path
                break

    py_exec = sys.executable.replace('\\', '/')
    if os.name == "nt" and py_exec[1:2] == ":":
        py_exec_msys = "/" + py_exec[0].lower() + py_exec[2:]
    else:
        py_exec_msys = py_exec
    env["MIOS_PYTHON_BIN"] = py_exec_msys

    userenv_script = os.path.join(root, 'usr/lib/mios/userenv.sh').replace('\\', '/')
    py_exec = sys.executable.replace('\\', '/')
    dump = f"source {shlex.quote(userenv_script)} && {shlex.quote(py_exec)} -c \"import os, json; print(json.dumps({{k: v for k, v in os.environ.items() if k.startswith('MIOS_')}}))\""

    def bash_exports(tier_env):
        cmd = [bash_exe, "-c", dump]
        try:
            out = subprocess.check_output(cmd, env=tier_env, stderr=subprocess.STDOUT).decode("utf-8")
            print(f"BASH OUTPUT: {out}", file=sys.stderr)
            got = json.loads(out)
            got.pop("MIOS_PYTHON_BIN", None)
            return got
        except subprocess.CalledProcessError as e:
            print("Error: userenv.sh execution failed:\n", e.output.decode("utf-8", errors="ignore"), file=sys.stderr)
            sys.exit(1)
        except json.JSONDecodeError as e:
            print(f"Error: Failed to parse env JSON: {e}\nOutput was:\n{out}", file=sys.stderr)
            sys.exit(1)

    # The reference is pure Python: with mios-resolver on PATH, mios_toml loads
    # its merged tree from the binary, and the gate would partly compare Rust
    # with itself.
    os.environ["MIOS_RESOLVER_NATIVE"] = "0"
    mios_toml.clear_cache()
    exports_map = mios_toml.emit_exports()
    pure_exports = dict(exports_map)

    ref_path = os.path.join(root, "usr/share/mios/referenced_names.txt")
    if os.path.isfile(ref_path):
        try:
            with open(ref_path, "r", encoding="utf-8") as f:
                for line in f:
                    v = line.strip()
                    if v and v not in exports_map:
                        exports_map[v] = ""
        except Exception:
            pass

    toml_vars = exports_map

    loopback = mios_toml.get("pgvector", "listen_loopback")
    if loopback is None:
        loopback = True
    toml_vars["MIOS_PG_BIND_ADDR"] = "127.0.0.1" if loopback else "0.0.0.0"

    ignore_vars = {
        "MIOS_VENDOR_TOML", "MIOS_HOST_TOML", "MIOS_USER_TOML",
        "MIOS_VENDOR_TOML_D", "MIOS_HOST_TOML_D", "MIOS_USER_TOML_D",
        "MIOS_DRIFT_ROOT", "MIOS_DRIFT_CHECK_ROOT", "MIOS_DRIFT_CHECK_SOFT",
        "MIOS_TOML_ROOT", "MIOS_ROOT_LIB", "MIOS_CONFIG_DIR", "MIOS_ROOT"
    }

    # userenv.sh resolves through the first tier it finds: mios-resolver, then
    # miosd, then mios_toml.py. Whatever this PATH offers is one run; each
    # native resolver built in this tree is forced first in a run of its own,
    # so CI (which has neither installed) still compares Rust with Python.
    exe = ".exe" if os.name == "nt" else ""
    tiers = [("default", env, None)]
    for label, rel, skip_tier1 in (("mios-resolver", "tools/native/target/debug/mios-resolver", False),
                                   ("miosd", "src/mios-rs/target/debug/miosd", True)):
        binary = os.path.join(root, rel + exe)
        if not os.path.isfile(binary):
            continue
        tier_env = dict(env)
        if skip_tier1:
            tier_env["MIOS_MIGRATION_USE_RUST_RESOLVER_SHELL"] = "false"
        tiers.append((label, tier_env, binary))

    import tempfile
    mismatches = []
    for label, tier_env, binary in tiers:
        with tempfile.TemporaryDirectory(prefix="mios-twin-") as d:
            if binary:
                try:
                    os.symlink(binary, os.path.join(d, os.path.basename(binary)))
                except OSError as e:
                    print(f"  [resolver-twin] {label}: cannot stage {binary} ({e}); tier not compared", file=sys.stderr)
                    continue
                tier_env = dict(tier_env, PATH=d + os.pathsep + tier_env.get("PATH", ""))
            bash_vars = bash_exports(tier_env)
        for k, expected in sorted(toml_vars.items()):
            if k in ignore_vars:
                continue
            actual = bash_vars.get(k)
            if actual != expected:
                if expected == "" and (actual is None or actual == ""):
                    continue
                mismatches.append(f"[{label}] Var {k}: Toml resolved {expected!r}, Bash resolved {actual!r}")
        for k, actual in sorted(bash_vars.items()):
            if k in ignore_vars:
                continue
            if k not in toml_vars:
                mismatches.append(f"[{label}] Unexpected Var {k}: Bash resolved {actual!r}, Toml has no entry")

    # mios_toml.py itself loads mios-resolver's merged tree when the binary is
    # on PATH; its exports must not change with where the tree came from.
    native = next((b for t, _, b in tiers if t == "mios-resolver"), None)
    if native:
        saved_path = os.environ.get("PATH", "")
        with tempfile.TemporaryDirectory(prefix="mios-twin-") as d:
            try:
                os.symlink(native, os.path.join(d, os.path.basename(native)))
                os.environ["PATH"] = d + os.pathsep + saved_path
                os.environ.pop("MIOS_RESOLVER_NATIVE", None)
                mios_toml.clear_cache()
                on_native = mios_toml.emit_exports()
            finally:
                os.environ["PATH"] = saved_path
                os.environ["MIOS_RESOLVER_NATIVE"] = "0"
                mios_toml.clear_cache()
        tiers.append(("mios_toml.py on mios-resolver's tree", None, native))
        for k in sorted(set(pure_exports) | set(on_native)):
            if k not in ignore_vars and pure_exports.get(k) != on_native.get(k):
                mismatches.append(f"[mios_toml.py on mios-resolver's tree] Var {k}: pure Python {pure_exports.get(k)!r}, on the native tree {on_native.get(k)!r}")

    if mismatches:
        for m in mismatches:
            print(f"  [resolver-twin] {m}", file=sys.stderr)
        sys.exit(1)

    print(f"SUCCESS: resolvers are equivalent ({', '.join(t[0] for t in tiers)})!")
    sys.exit(0)

_GATES = {"container-names": cn_main, "privileged-quadlets": pq_main, "service-urls": su_main, "daemon-governor": dg_main, "firstboot-degrade-open": fdo_main, "firstboot-provisioners": fp_main, "verify-images": vi_main, "resolver-twin": rt_main}


def main() -> int:
    # An unknown or missing subcommand must FAIL, never report a clean gate.
    if len(sys.argv) < 2 or sys.argv[1] not in _GATES:
        sys.stderr.write("usage: check-runtime.py {%s}\n" % "|".join(sorted(_GATES)))
        return 2
    return _GATES[sys.argv.pop(1)]()


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# AI-hint: SSOT-plane drift gates in one module: mios.toml integrity, consumer keys, unit projection, port fallbacks and binding, variant registry, deploy formats, role SSOT, node pool, blade coverage and fleet safety. The subcommand selects the gate.
# AI-doc: usr/share/doc/mios/manual/tools.md
"""SSOT-plane drift gates. One module, one subcommand per gate."""
import sys


"""Gate: mios.toml parses as valid TOML, maintains min line count, and preserves top-level tables."""

import os
import sys

try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

mti_MIOS_TOML_RELATIVE = "usr/share/mios/mios.toml"
mti_MIN_LINE_COUNT = 9000

# Required top-level tables that must always be present in mios.toml
mti_REQUIRED_TOP_LEVEL_TABLES = {
    "versions",
    "security",
    "units",
    "unit_projection",
    "docs",
    "legibility",
    "ports",
}

def mti_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT", os.environ.get("MIOS_TOML_ROOT", "."))
    path = os.path.join(root, mti_MIOS_TOML_RELATIVE)
    if not os.path.isfile(path):
        print(f"VIOLATION: {mti_MIOS_TOML_RELATIVE} not found under {root}")
        return 1

    with open(path, "r", encoding="utf-8", errors="replace") as f:
        content = f.read()

    lines = content.splitlines()
    line_count = len(lines)
    if line_count < mti_MIN_LINE_COUNT:
        print(
            f"VIOLATION: {mti_MIOS_TOML_RELATIVE} line count ({line_count}) is below minimum baseline ({mti_MIN_LINE_COUNT})"
        )
        return 1

    if tomllib is not None:
        try:
            parsed = tomllib.loads(content)
        except Exception as e:
            print(f"VIOLATION: {mti_MIOS_TOML_RELATIVE} failed TOML parsing: {e}")
            return 1

        missing_tables = [table for table in mti_REQUIRED_TOP_LEVEL_TABLES if table not in parsed]
        if missing_tables:
            print(
                f"VIOLATION: {mti_MIOS_TOML_RELATIVE} is missing required top-level tables: {missing_tables}"
            )
            return 1
    else:
        # Fallback basic header check if tomllib/tomli unavailable
        found_tables = set()
        for line in lines:
            line_str = line.strip()
            if line_str.startswith("[") and not line_str.startswith("[["):
                header = line_str.strip("[]").strip().split(".")[0]
                found_tables.add(header)
        missing_tables = [table for table in mti_REQUIRED_TOP_LEVEL_TABLES if table not in found_tables]
        if missing_tables:
            print(
                f"VIOLATION: {mti_MIOS_TOML_RELATIVE} is missing required top-level tables: {missing_tables}"
            )
            return 1

    print(f"mios.toml integrity check passed (lines={line_count})")
    return 0


"""Gate: every SSOT key a consumer reads is a key the SSOT declares."""

import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover -- py<3.11
    import tomli as tomllib  # type: ignore

sck_TOML = "usr/share/mios/mios.toml"
sck_SCAN_ROOTS = ("usr",)

# `_toml_section("x").get("y"` and `(_toml_section("x") or {}).get("y"`.
sck__READ = re.compile(
    r"""_toml_section\(\s*["']([a-z0-9_.]+)["']\s*\)(?:\s*or\s*\{\}\s*\))?"""
    r"""\s*\.get\(\s*["']([a-z0-9_]+)["']"""
)

def sck_consumer_reads(root: str) -> dict:
    """{(table, key): [file:line, ...]} over shipped Python.

    Tests are skipped: a test may legitimately read a key it stubs itself.
    """
    hits = {}
    for scan in sck_SCAN_ROOTS:
        base = os.path.join(root, scan)
        if not os.path.isdir(base):
            continue
        for dirpath, dirnames, filenames in os.walk(base):
            dirnames[:] = [d for d in dirnames
                           if d != "__pycache__" and not d.startswith(".venv")]
            for name in sorted(filenames):
                if not name.endswith(".py") or name.startswith("test_"):
                    continue
                path = os.path.join(dirpath, name)
                try:
                    with open(path, encoding="utf-8", errors="replace") as fh:
                        body = fh.read()
                except OSError:
                    continue
                rel = os.path.relpath(path, root).replace(os.sep, "/")
                for m in sck__READ.finditer(body):
                    site = "%s:%d" % (rel, body[:m.start()].count("\n") + 1)
                    hits.setdefault((m.group(1), m.group(2)), []).append(site)
    return {k: sorted(set(v)) for k, v in hits.items()}

def sck_resolve(data: dict, dotted: str):
    """The table at a dotted path, or None."""
    cur = data
    for part in dotted.split("."):
        if not isinstance(cur, dict) or part not in cur:
            return None
        cur = cur[part]
    return cur

def sck_declared_elsewhere(data: dict, key: str) -> list:
    """Every dotted path in the SSOT that declares this key name."""
    out = []

    def walk(table, path):
        for k, v in table.items():
            if k == key:
                out.append(".".join(path + [k]))
            if isinstance(v, dict):
                walk(v, path + [k])

    walk(data, [])
    return sorted(out)

def sck_register(data: dict) -> list:
    """[ssot_consumers].unresolved, in declaration order."""
    reg = (data.get("ssot_consumers") or {}).get("unresolved")
    if reg is None:
        return []
    return [str(x).strip() for x in reg if str(x).strip()]

def sck_max_unresolved(data: dict):
    val = (data.get("ssot_consumers") or {}).get("max_unresolved")
    return val if isinstance(val, int) else None

def sck_unresolved(data: dict, root: str) -> dict:
    """{'table.key': (sites, elsewhere)} for every read that resolves to nothing."""
    out = {}
    for (table, key), sites in sck_consumer_reads(root).items():
        target = sck_resolve(data, table)
        if isinstance(target, dict) and key in target:
            continue
        out["%s.%s" % (table, key)] = (sites, sck_declared_elsewhere(data, key))
    return out

def sck_violations(data: dict, root: str) -> list:
    viol = []
    reads = sck_consumer_reads(root)
    if not reads:
        return ["no _toml_section(...).get(...) reads found at all -- the gate "
                "would pass vacuously over an empty set"]

    table = data.get("ssot_consumers")
    if table is None:
        return ["[ssot_consumers] is absent -- nothing bounds how many config keys "
                "a consumer may read that the SSOT does not declare"]
    if "unresolved" not in table:
        viol.append("[ssot_consumers] declares no `unresolved` key -- an implied "
                    "empty register is indistinguishable from a forgotten one")

    reg = sck_register(data)
    if len(reg) != len(set(reg)):
        dupes = sorted({x for x in reg if reg.count(x) > 1})
        viol.append("[ssot_consumers].unresolved lists a pair twice: %s" % ", ".join(dupes))
    if reg != sorted(reg):
        viol.append("[ssot_consumers].unresolved is not sorted -- an unsorted "
                    "register hides an addition inside a reordering")

    found = sck_unresolved(data, root)
    for pair in sorted(set(found) - set(reg)):
        sites, elsewhere = found[pair]
        if elsewhere:
            viol.append("%s is read at %s but the SSOT declares that key at %s -- "
                        "the consumer takes its compiled default and nobody is told"
                        % (pair, sites[0], "/".join(elsewhere)))
        else:
            viol.append("%s is read at %s and is declared NOWHERE in the SSOT"
                        % (pair, sites[0]))

    for pair in sorted(set(reg) - set(found)):
        if pair.rsplit(".", 1)[0] not in {t for t, _ in reads}:
            viol.append("[ssot_consumers].unresolved names '%s', which no shipped "
                        "consumer reads -- drop it" % pair)
        else:
            viol.append("[ssot_consumers].unresolved names '%s', which resolves now "
                        "-- drop it from the register; the register only shrinks" % pair)

    ceiling = sck_max_unresolved(data)
    if ceiling is None:
        viol.append("[ssot_consumers].max_unresolved is unset -- without a ceiling "
                    "the register absorbs new breakage as fast as it appears")
    elif len(reg) > ceiling:
        viol.append("[ssot_consumers].unresolved holds %d entries, over the ratchet "
                    "ceiling max_unresolved = %d. The ceiling only comes DOWN"
                    % (len(reg), ceiling))
    elif len(reg) < ceiling:
        viol.append("[ssot_consumers].unresolved holds %d entries but max_unresolved "
                    "is still %d -- lower it to %d so the ground gained is held"
                    % (len(reg), ceiling, len(reg)))
    return viol

def sck_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or "."
    path = os.path.join(root, sck_TOML)
    try:
        with open(path, "rb") as fh:
            data = tomllib.load(fh)
    except OSError as exc:
        print("check-ssot-consumer-keys: cannot read %s: %s" % (path, exc),
              file=sys.stderr)
        return 1

    viol = sck_violations(data, root)
    if viol:
        for v in viol:
            print("check_ssot_consumer_keys: %s" % v, file=sys.stderr)
        return 1

    reads = sck_consumer_reads(root)
    reg = sck_register(data)
    print("[check-ssot-consumer-keys] %d consumer read(s) of %d distinct SSOT key(s); "
          "%d unresolved and registered (ceiling %s)."
          % (sum(len(v) for v in reads.values()), len(reads), len(reg),
             sck_max_unresolved(data)))
    return 0


"""Gate: the [units] projection's debt register is real, sorted and shrinking."""

import os
import shutil
import subprocess
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover -- py<3.11
    import tomli as tomllib  # type: ignore

up_TOML = "usr/share/mios/mios.toml"
up_UNIT_DIR = "usr/lib/systemd/system"

def up_declared_units(data: dict) -> set:
    """Unit filenames [units.*] projects. Table-valued keys only -- the
    string-valued half is name aliases, not units. See tasks.jsonl task_267."""
    return {k for k, v in (data.get("units") or {}).items() if isinstance(v, dict)}

def up_unit_aliases(data: dict) -> set:
    """The string-valued half of [units]: name -> unit-file aliases."""
    return {k for k, v in (data.get("units") or {}).items() if isinstance(v, str)}

def up_register(data: dict) -> list:
    """[unit_projection].drift, in declaration order."""
    reg = (data.get("unit_projection") or {}).get("drift")
    if reg is None:
        return []
    return [str(x).strip() for x in reg if str(x).strip()]

def up_max_drift(data: dict):
    """The ratchet ceiling, or None when the table declares none."""
    val = (data.get("unit_projection") or {}).get("max_drift")
    return val if isinstance(val, int) else None

def up_shipped(root: str) -> set:
    """Unit files actually on disk."""
    d = os.path.join(root, up_UNIT_DIR)
    if not os.path.isdir(d):
        return set()
    res = set()
    for dp, _, fns in os.walk(d):
        for f in fns:
            rel = os.path.relpath(os.path.join(dp, f), d).replace(os.sep, "/")
            res.add(rel)
    return res

def up_hygiene(data: dict, root: str) -> list:
    """Everything about the register that can be checked without rendering."""
    viol = []
    units = up_declared_units(data)
    if not units:
        return ["[units.*] declares no units at all -- the projection gate would "
                "pass vacuously over an empty set"]

    table = data.get("unit_projection")
    if table is None:
        return ["[unit_projection] is absent -- the [units] projection has no debt "
                "register, so nothing bounds how far the declarations may drift"]
    if "drift" not in table:
        viol.append("[unit_projection] declares no `drift` key -- an implied empty "
                    "register is indistinguishable from a forgotten one")

    reg = up_register(data)
    if len(reg) != len(set(reg)):
        dupes = sorted({x for x in reg if reg.count(x) > 1})
        viol.append("[unit_projection].drift lists a unit twice: %s" % ", ".join(dupes))
    if reg != sorted(reg):
        viol.append("[unit_projection].drift is not sorted -- an unsorted register "
                    "hides an addition inside a reordering")

    on_disk = up_shipped(root)
    for name in sorted(set(reg)):
        if name not in units:
            viol.append("[unit_projection].drift names '%s', which [units.*] does "
                        "not declare -- a unit outside the projection cannot drift "
                        "from it" % name)
        elif name not in on_disk:
            viol.append("[unit_projection].drift names '%s', which the tree does "
                        "not ship" % name)

    ceiling = up_max_drift(data)
    if ceiling is None:
        viol.append("[unit_projection].max_drift is unset -- without a ceiling the "
                    "register can absorb new drift as fast as it is created")
    elif len(reg) > ceiling:
        viol.append("[unit_projection].drift holds %d entries, over the ratchet "
                    "ceiling max_drift = %d. The ceiling only comes DOWN: fix the "
                    "declaration instead of raising it" % (len(reg), ceiling))
    elif len(reg) < ceiling:
        viol.append("[unit_projection].drift holds %d entries but max_drift is "
                    "still %d -- lower the ceiling to %d so the ground gained is "
                    "held" % (len(reg), ceiling, len(reg)))
    return viol

def up__built(root: str):
    catalog = os.environ.get("MIOS_NATIVE_BIN_DIR")
    if catalog:
        p = os.path.join(catalog, "mios-unit-gen" + (".exe" if sys.platform == "win32" else ""))
        if not os.path.isfile(p) or not os.access(p, os.X_OK):
            raise RuntimeError("configured unit generator is missing or not executable: %s" % p)
        return p
    rels = ("target/release/mios-unit-gen.exe", "target/debug/mios-unit-gen.exe", "target/release/mios-unit-gen", "target/debug/mios-unit-gen") if sys.platform == "win32" else ("target/release/mios-unit-gen", "target/debug/mios-unit-gen", "target/release/mios-unit-gen.exe", "target/debug/mios-unit-gen.exe")
    for rel in rels:
        p = os.path.join(root, "tools/native", rel)
        if os.path.isfile(p) and os.access(p, os.X_OK):
            if sys.platform != "win32" and rel.endswith(".exe"):
                continue
            return p
    return None

def up_binary_path(root: str, build: bool = True):
    """A built mios-unit-gen, building it once if cargo is available.

    Without this the gate SKIPS its rendering comparison wherever nobody has run
    cargo -- which is every CI checkout, the one place it matters. See task_267.
    """
    found = up__built(root)
    if found or not build:
        return found
    if not shutil.which("cargo"):
        return None
    try:
        subprocess.run(["cargo", "build", "--manifest-path",
                        os.path.join(root, "tools/native/Cargo.toml"),
                        "-p", "mios-unit-gen"],
                       capture_output=True, timeout=600)
    except (OSError, subprocess.SubprocessError):
        return None
    return up__built(root)

def up_run_binary(path: str, root: str):
    """(ok, output). The binary owns the rendering comparison; we only relay it."""
    env = dict(os.environ, MIOS_ROOT=os.path.abspath(root))
    try:
        proc = subprocess.run([path, "--check"], env=env, capture_output=True,
                              text=True, timeout=120)
    except (OSError, subprocess.SubprocessError) as exc:
        return False, "mios-unit-gen --check could not run: %s" % exc
    out = (proc.stdout + proc.stderr).strip()
    return proc.returncode == 0, out

def up_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or "."
    path = os.path.join(root, up_TOML)
    try:
        with open(path, "rb") as fh:
            data = tomllib.load(fh)
    except OSError as exc:
        print("check-unit-projection: cannot read %s: %s" % (path, exc), file=sys.stderr)
        return 1

    viol = up_hygiene(data, root)

    try:
        binary = up_binary_path(root)
    except RuntimeError as exc:
        print("check_unit_projection: %s" % exc, file=sys.stderr)
        return 1
    if binary:
        ok, out = up_run_binary(binary, root)
        if not ok:
            for line in out.splitlines():
                if line.strip():
                    viol.append(line.strip())
    elif os.environ.get("MIOS_DRIFT_REQUIRE_TOOLS", "0") == "1":
        viol.append("no built mios-unit-gen, so the rendering half did not run "
                    "and a drifting unit dropped from the register would pass "
                    "(MIOS_DRIFT_REQUIRE_TOOLS=1). Build it: "
                    "cd tools/native && cargo build -p mios-unit-gen")
    if viol:
        for v in viol:
            print("check_unit_projection: %s" % v, file=sys.stderr)
        return 1

    reg, units = up_register(data), up_declared_units(data)
    note = ("mios-unit-gen --check agrees" if binary else
            "NOT rendering-checked here: no mios-unit-gen and no cargo to build one. "
            "tools/native/mios-unit-gen/tests/projection.rs is the authority and CI runs it")
    print("[check-unit-projection] %d unit(s) declared in [units.*] (plus %d name "
          "aliases sharing the table), %d registered as drifted (ceiling %s). %s."
          % (len(units), len(up_unit_aliases(data)), len(reg), up_max_drift(data), note))
    return 0


"""Gate: a literal beside a MIOS_PORT_ name must be that port's value."""

import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover -- py<3.11
    import tomli as tomllib  # type: ignore

pf_TOML = "usr/share/mios/mios.toml"

# Roots that can BIND or DIAL a port at runtime.
pf_ROOTS = ("usr/lib/systemd/system", "usr/share/containers/systemd",
         "usr/libexec/mios", "usr/lib/mios", "usr/bin", "automation")

# Never scanned: generated projections restate every value by construction,
# docs are check_doc_port_scheme's job, and a .md/.json is not a binder.
pf_SKIP_SUBSTR = ("/reference/", "/doc/", "__pycache__", "/.git/", "manifest.json",
               "names.generated", "referenced_names", "globals.sh", "globals.ps1")
pf_SKIP_EXT = (".md", ".json", ".tsv", ".txt", ".rmeta", ".pyc")

pf_PATTERNS = (
    re.compile(r"MIOS_(?:PORTS?)_([A-Z0-9_]+)\s*:[-=]\s*(\d+)"),        # ${X:-N} / ${X:=N}
    re.compile(r'"MIOS_(?:PORTS?)_([A-Z0-9_]+)"\s*,\s*"(\d+)"'),        # get("X", "N")
    re.compile(r"'MIOS_(?:PORTS?)_([A-Z0-9_]+)'\s*,\s*'(\d+)'"),
    re.compile(r"'MIOS_(?:PORTS?)_([A-Z0-9_]+)'\s+(\d+)"),              # _MiosPort 'X' N
    re.compile(r"^\s*Environment=MIOS_(?:PORTS?)_([A-Z0-9_]+)=(\d+)\s*$"),
    # `get(K, "N") or M` / `get(K) or "M"` -- the SECOND literal is the one that
    # actually runs when the variable is unset or empty, and the first sweep
    # missed it entirely.
    re.compile(r"MIOS_(?:PORTS?)_([A-Z0-9_]+)[\"']?\s*[,)][^\n]{0,60}?\bor\s+[\"']?(\d+)"),
    # The MIOS_<KEY>_PORT spelling: a second emitted name for the same value, so
    # a stale literal beside it is the same defect one alias removed.
    re.compile(r"MIOS_([A-Z0-9_]+)_PORT[\"']?\s*,\s*[\"']?(\d+)"),
)

pf_COMMENT = re.compile(r"^\s*(#|//|--|;)")

def pf_ports_map(data: dict) -> dict:
    """{KEY: value} for every numeric [ports] entry."""
    return {str(k).upper(): v for k, v in (data.get("ports") or {}).items()
            if isinstance(v, int)}

def pf_scan_paths(root: str):
    """Every file under ROOTS that could bind or dial a port."""
    for rel in pf_ROOTS:
        base = os.path.join(root, rel)
        if not os.path.isdir(base):
            continue
        for dirpath, dirnames, filenames in os.walk(base):
            dirnames[:] = [d for d in dirnames
                           if d not in ("__pycache__", "target", "node_modules")]
            for name in sorted(filenames):
                p = os.path.join(dirpath, name)
                r = os.path.relpath(p, root).replace(os.sep, "/")
                if any(s in "/" + r for s in pf_SKIP_SUBSTR):
                    continue
                if r.endswith(pf_SKIP_EXT):
                    continue
                yield p, r

def pf_findings(data: dict, root: str) -> dict:
    """{'path:KEY': 'literal N, SSOT M'} for every disagreeing literal."""
    ports, out = pf_ports_map(data), {}
    for path, rel in pf_scan_paths(root):
        try:
            with open(path, encoding="utf-8", errors="replace") as fh:
                body = fh.read()
        except OSError:
            continue
        # NOT "MIOS_PORT_": the MIOS_<KEY>_PORT alias spelling would skip the
        # whole file, which is how mios-daemon and mios-pc-control stayed hidden.
        if "MIOS_" not in body:
            continue
        for line in body.splitlines():
            if pf_COMMENT.match(line):
                continue
            for pat in pf_PATTERNS:
                for m in pat.finditer(line):
                    key, lit = m.group(1), int(m.group(2))
                    want = ports.get(key)
                    if want is not None and lit != want:
                        out["%s:%s" % (rel, key)] = "%d, SSOT says %d" % (lit, want)
    return out

def pf_register(data: dict) -> list:
    """The shrink-only debt register, in declaration order."""
    reg = (data.get("ports") or {}).get("stale_fallbacks") or []
    return [str(x).strip() for x in reg if str(x).strip()]

def pf_classify(data: dict, root: str = ".") -> list:
    found, reg = pf_findings(data, root), pf_register(data)
    reg_set, viol = set(reg), []
    if len(reg) != len(reg_set):
        dupes = sorted({k for k in reg if reg.count(k) > 1})
        viol.append("[ports].stale_fallbacks lists an entry twice: %s" % ", ".join(dupes))
    for entry in sorted(set(found) - reg_set):
        viol.append("%s pairs MIOS_PORT_%s with %s -- a literal beside the name is "
                    "the hardcode the SSOT exists to replace"
                    % (entry.rsplit(":", 1)[0], entry.rsplit(":", 1)[1], found[entry]))
    for entry in sorted(reg_set - set(found)):
        viol.append("[ports].stale_fallbacks still lists '%s', which now agrees with "
                    "the SSOT or no longer exists -- the register only shrinks" % entry)
    return viol

def pf_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or "."
    path = os.path.join(root, pf_TOML)
    try:
        with open(path, "rb") as fh:
            data = tomllib.load(fh)
    except OSError as exc:
        print("check-port-fallbacks: cannot read %s: %s" % (path, exc), file=sys.stderr)
        return 1
    if not pf_ports_map(data):
        print("check-port-fallbacks: [ports] is empty -- the gate would pass "
              "vacuously", file=sys.stderr)
        return 1

    viol = pf_classify(data, root)
    if viol:
        for v in viol:
            print("check_port_fallbacks: %s" % v, file=sys.stderr)
        return 1
    reg = pf_register(data)
    scanned = sum(1 for _ in pf_scan_paths(root))
    print("[check-port-fallbacks] %d file(s) scanned; every MIOS_PORT_* literal "
          "matches [ports]%s" % (scanned,
          "" if not reg else " or is one of %d registered as shrink-only debt" % len(reg)))
    return 0


"""Gate: an allocated port is bound by something, or registered as not yet wired."""

import os
import re
import subprocess
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover -- py<3.11
    import tomli as tomllib  # type: ignore

pb_TOML = "usr/share/mios/mios.toml"

# Surfaces that only DESCRIBE ports never prove one is bound: the SSOT itself,
# documentation, generated projections and the task ledgers.
pb_SKIP_PREFIXES = (
    "usr/share/doc/",
    "usr/share/mios/reference/",
    "usr/share/mios/mios.toml",
    "usr/share/mios/names.generated.txt",
    "usr/share/mios/referenced_names.txt",
    "automation/lib/globals.sh",
    "automation/lib/globals.ps1",
    "automation/manifest.json",
    "tools/manifest.json",
    "docs/",
    "ROADMAP.md",
    "tasks.jsonl",
    "ADR.md",
)

def pb_port_keys(data: dict) -> set:
    """Numeric [ports] keys. stack_id is an offset, not a port."""
    ports = data.get("ports") or {}
    return {k for k, v in ports.items() if isinstance(v, int) and k != "stack_id"}

def pb_register(data: dict) -> list:
    """The shrink-only unbound register, in declaration order."""
    reg = (data.get("ports") or {}).get("unbound") or []
    return [str(x).strip() for x in reg if str(x).strip()]

def pb__tracked_files(root: str) -> list:
    out = subprocess.run(["git", "-C", root, "ls-files"],
                         capture_output=True, text=True, check=False).stdout
    return [f for f in out.split("\n") if f and not f.startswith(pb_SKIP_PREFIXES)]

def pb_referenced_ports(root: str, keys: set) -> set:
    """Port keys whose MIOS_PORT_<KEY> appears in a file that could bind or dial it."""
    wanted = {k.upper(): k for k in keys}
    pattern = re.compile(r"\bMIOS_(?:PORTS?)_([A-Z0-9_]+)\b")
    found = set()
    for rel in pb__tracked_files(root):
        path = os.path.join(root, rel)
        try:
            with open(path, encoding="utf-8", errors="replace") as fh:
                body = fh.read()
        except OSError:
            continue
        for m in pattern.finditer(body):
            key = wanted.get(m.group(1))
            if key:
                found.add(key)
    return found

def pb_classify(data: dict, referenced: set) -> list:
    """Return the violations; empty means every allocated port is accounted for."""
    viol = []
    keys = pb_port_keys(data)
    if not keys:
        return ["[ports] declares no numeric port -- the gate would pass "
                "vacuously over an empty set"]

    reg = pb_register(data)
    reg_set = set(reg)

    if len(reg) != len(reg_set):
        dupes = sorted({k for k in reg if reg.count(k) > 1})
        viol.append("[ports].unbound lists a key twice: %s" % ", ".join(dupes))

    for k in sorted(reg_set - keys):
        viol.append("[ports].unbound names '%s', which is not a [ports] key" % k)

    for k in sorted(reg_set & referenced):
        viol.append("port '%s' IS referenced now but still sits in [ports].unbound "
                    "-- the register only shrinks, so remove it" % k)

    for k in sorted(keys - referenced - reg_set):
        viol.append("port '%s' is allocated but no Quadlet, unit or program "
                    "references MIOS_PORT_%s -- the collision check guards a number "
                    "nothing binds" % (k, k.upper()))

    return viol

def pb_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or "."
    path = os.path.join(root, pb_TOML)
    try:
        with open(path, "rb") as fh:
            data = tomllib.load(fh)
    except OSError as exc:
        print("check-ports-bound: cannot read %s: %s" % (path, exc), file=sys.stderr)
        return 1

    keys = pb_port_keys(data)
    referenced = pb_referenced_ports(root, keys)
    viol = pb_classify(data, referenced)
    if viol:
        for v in viol:
            print("check_ports_bound: %s" % v, file=sys.stderr)
        return 1

    print("[check-ports-bound] %d port(s): %d referenced by a consumer, %d "
          "registered unbound" % (len(keys), len(referenced & keys),
                                  len(pb_register(data))))
    return 0


import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover
    import tomli as tomllib  # type: ignore

vr_STATUSES = ("shipping", "partial", "design")
vr_REQUIRED = ("title", "summary", "target", "config", "archetype", "artifacts",
            "doc", "status")

def vr_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or os.getcwd()
    with open(os.path.join(root, "usr/share/mios/mios.toml"), "rb") as fh:
        ssot = tomllib.load(fh)

    viol = []
    variants = ssot.get("variants") or {}
    entries = variants.get("entries") or {}
    naming = variants.get("naming") or {}
    if not entries:
        print("[variants.entries] is empty -- a registry with no entries passes"
              " every check it has and states nothing")
        return 1

    editions = ssot.get("editions") or {}
    archetypes = ((ssot.get("blade") or {}).get("archetypes") or {})
    # [deploy.formats] is the matrix; a format needs a build target, not
    # necessarily a recipe file, so the recipe directory is the wrong authority.
    recipes = {k for k, v in ((ssot.get("deploy") or {}).get("formats") or {}).items()
               if isinstance(v, dict)}

    key_re = re.compile(r"^[%s]+$" % naming.get("key_charset", "a-z0-9-"))
    prefix = naming.get("prefix", "MiOS")
    sep = naming.get("separator", "-")
    base = naming.get("base", "mios")

    claimed = set()
    for key, spec in sorted(entries.items()):
        where = "[variants.entries.%s]" % key
        for field in vr_REQUIRED:
            if field not in spec:
                viol.append("%s is missing %s" % (where, field))
        if not key_re.match(key):
            viol.append("%s key breaks %s" % (where, naming.get("key_pattern", "")))

        title = str(spec.get("title", ""))
        if key == base:
            if title != prefix:
                viol.append("%s the base variant is titled %r, expected %r"
                            % (where, title, prefix))
        elif not title.startswith(prefix + sep):
            viol.append("%s title %r does not follow %s"
                        % (where, title, naming.get("title_pattern", "")))
        elif title.lower() != key:
            viol.append("%s title %r and key %r are not the same name in two"
                        " registers" % (where, title, key))

        status = spec.get("status")
        if status not in vr_STATUSES:
            viol.append("%s status %r is not one of %s" % (where, status, list(vr_STATUSES)))

        for table in spec.get("config") or []:
            if table not in ssot:
                viol.append("%s config names [%s], which the SSOT does not define"
                            % (where, table))
        ed = spec.get("edition")
        if ed:
            claimed.add(ed)
            if ed not in editions:
                viol.append("%s edition %r is not in [editions]" % (where, ed))
        arch = spec.get("archetype")
        if arch and arch not in archetypes:
            viol.append("%s archetype %r is not in [blade.archetypes]" % (where, arch))
        for art in spec.get("artifacts") or []:
            if art not in recipes:
                viol.append("%s artifact %r is not a declared deployment format"
                            % (where, art))
        doc = spec.get("doc")
        if doc and not os.path.isfile(os.path.join(root, doc)):
            viol.append("%s doc %s does not exist" % (where, doc))

    for ed in sorted(editions):
        if ed not in claimed:
            viol.append("[editions.%s] is claimed by no variant -- an edition"
                        " nobody ships is configuration for nothing" % ed)

    ceiling = variants.get("max_design_variants")
    design = [k for k, v in entries.items() if v.get("status") == "design"]
    if ceiling is None:
        viol.append("[variants] has no max_design_variants -- an absent ceiling"
                    " lets a design doc stay the deliverable")
    elif len(design) > int(ceiling):
        viol.append("variants still in design %d > ceiling %d: %s"
                    % (len(design), ceiling, sorted(design)))

    print("\n".join(viol))
    if viol:
        return 1
    print("[check-variant-registry] %d variant(s); %d shipping, %d partial, %d design"
          % (len(entries),
             sum(1 for v in entries.values() if v.get("status") == "shipping"),
             sum(1 for v in entries.values() if v.get("status") == "partial"),
             len(design)), file=sys.stderr)
    return 0


import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover
    import tomli as tomllib  # type: ignore

df_STATUSES = ("shipping", "partial", "design")
# "artifacts" is the glob list the verifier requires a match for. A format
# without one is a format the publish gate cannot notice the absence of, which
# is how an empty build tree came to satisfy it; only the registry format,
# which writes no file, is allowed an empty list.
df_REQUIRED = ("title", "summary", "target", "recipe", "medium", "gui", "status",
            "artifacts")
# Targets in the Justfile that orchestrate or post-process rather than produce a
# deployable artifact. Listed so that a NEW artifact target cannot hide here.
df_NOT_A_FORMAT = frozenset({
    "build", "build-logged", "build-verbose", "all", "publish", "rechunk",
    "rechunk-conv", "artifact", "sbom", "verify-images", "cloud-build",
    "embed-log", "log-bootstrap", "build-and-log", "all-bootstrap",
})

def df_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or os.getcwd()
    with open(os.path.join(root, "usr/share/mios/mios.toml"), "rb") as fh:
        ssot = tomllib.load(fh)

    viol = []
    deploy = ssot.get("deploy") or {}
    formats = {k: v for k, v in (deploy.get("formats") or {}).items()
               if isinstance(v, dict)}
    if not formats:
        print("[deploy.formats] is empty -- a matrix with no entries supports"
              " nothing and passes every check it has")
        return 1

    just = ""
    jpath = os.path.join(root, "Justfile")
    if os.path.isfile(jpath):
        just = open(jpath, encoding="utf-8", errors="replace").read()
    else:
        viol.append("Justfile is missing -- no format can be built")
    targets = set(re.findall(r"^([a-z0-9][a-z0-9_-]*):", just, re.M))

    claimed_recipes = set()
    for name, spec in sorted(formats.items()):
        where = "[deploy.formats.%s]" % name
        for field in df_REQUIRED:
            if field not in spec:
                viol.append("%s is missing %s" % (where, field))
        if not spec.get("artifacts") and spec.get("medium") != "container registry":
            viol.append("%s declares no artifacts globs, so a build that produces"
                        " no %s file passes verify-images unnoticed"
                        % (where, name))
        if spec.get("status") not in df_STATUSES:
            viol.append("%s status %r is not one of %s"
                        % (where, spec.get("status"), list(df_STATUSES)))
        target = spec.get("target")
        if target and target not in targets:
            viol.append("%s names target %r, which the Justfile does not define"
                        % (where, target))
        recipe = spec.get("recipe")
        if recipe:
            claimed_recipes.add(os.path.basename(recipe))
            if not os.path.isfile(os.path.join(root, recipe)):
                viol.append("%s recipe %s does not exist" % (where, recipe))

    shared = (deploy.get("formats") or {}).get("shared_recipe")
    if shared:
        claimed_recipes.add(os.path.basename(shared))
        if not os.path.isfile(os.path.join(root, shared)):
            viol.append("[deploy.formats].shared_recipe %s does not exist" % shared)

    art_dir = os.path.join(root, "config/artifacts")
    if os.path.isdir(art_dir):
        for fn in sorted(os.listdir(art_dir)):
            if fn.endswith(".toml") and fn not in claimed_recipes:
                viol.append("config/artifacts/%s is claimed by no format -- a"
                            " recipe nothing builds from is configuration for"
                            " nothing" % fn)

    # A target that produces an artifact and is not declared is an unsupported
    # format shipping anyway, which is the half of the matrix nobody maintains.
    declared_targets = {s.get("target") for s in formats.values()}
    for t in sorted(targets):
        if t in df_NOT_A_FORMAT or t in declared_targets:
            continue
        body = re.search(r"^%s:.*?(?=^[a-z0-9][a-z0-9_-]*:|\Z)" % re.escape(t),
                         just, re.M | re.S)
        # Creating the output directory is what a producing target does; a
        # status target merely reads the same paths, and matching a mention
        # rather than a write reported flight-status as an undeclared format.
        if body and re.search(r"mkdir\s+-p\s+build/", body.group(0)):
            viol.append("Justfile target %r writes a deployable artifact and is"
                        " in no [deploy.formats] entry" % t)

    for vname, vspec in sorted((ssot.get("variants") or {}).get("entries", {}).items()):
        for art in vspec.get("artifacts") or []:
            if art not in formats:
                viol.append("[variants.entries.%s] ships %r, which [deploy.formats]"
                            " does not define" % (vname, art))

    print("\n".join(viol))
    if viol:
        return 1
    shipping = sum(1 for s in formats.values() if s.get("status") == "shipping")
    print("[check-deploy-formats] %d format(s), %d shipping; every target and"
          " recipe resolves" % (len(formats), shipping), file=sys.stderr)
    return 0


"""Gate: the blade role is stated once, legally, and in one place."""

import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover -- py<3.11
    import tomli as tomllib  # type: ignore

rs_TOML = "usr/share/mios/mios.toml"
rs_UNIT_DIR = "usr/lib/systemd/system"

# Both halves of the resolver twin. Neither may keep the retired names alive.
rs_KEEP_LISTS = ("usr/lib/mios/mios_toml.py",
              "tools/native/mios-ssot-walk/src/lib.rs")
rs_RETIRED_NAMES = ("MIOS_PROFILE_ROLE", "MIOS_PROFILE_FEATURES")

# Executable blade code: a re-introduced `case "$ROLE" in hybrid) ...` here is
# a second copy of [blade.archetypes].
rs_BLADE_CODE = ("usr/lib/mios/blade.sh",
              "usr/libexec/mios/role-apply",
              "usr/libexec/mios/mios-blade")

def rs_archetypes(data: dict) -> dict:
    """{name: [capability, ...]} from [blade.archetypes]."""
    out = {}
    for name, caps in ((data.get("blade") or {}).get("archetypes") or {}).items():
        if isinstance(caps, str):
            caps = [caps]
        out[str(name)] = [str(c).strip() for c in (caps or []) if str(c).strip()]
    return out

def rs_aliases(data: dict) -> dict:
    """{legacy-spelling: archetype} from [blade.role_aliases]."""
    return {str(k): str(v)
            for k, v in ((data.get("blade") or {}).get("role_aliases") or {}).items()}

def rs_role_targets(data: dict) -> list:
    """The unit each archetype's name derives, in [blade.archetypes] order."""
    return ["mios-%s.target" % name for name in sorted(rs_archetypes(data))]

def rs_unit_body(root: str, name: str) -> str:
    try:
        with open(os.path.join(root, rs_UNIT_DIR, name), encoding="utf-8",
                  errors="replace") as fh:
            return fh.read()
    except OSError:
        return ""

def rs_check_type(data: dict) -> list:
    arche = rs_archetypes(data)
    btype = str((data.get("blade") or {}).get("type") or "").strip()
    if not btype:
        return ["[blade].type is empty -- the image would have no archetype"]
    if not arche:
        return ["[blade.archetypes] is empty -- the gate would pass vacuously"]
    if btype not in arche:
        return ["[blade].type is '%s', which is not an archetype (declared: %s)"
                % (btype, ", ".join(sorted(arche)))]
    return []

def rs_check_targets(data: dict, root: str) -> list:
    viol = []
    for name in sorted(rs_archetypes(data)):
        if not re.fullmatch(r"[a-z0-9][a-z0-9-]*", name):
            viol.append("archetype '%s' is not a legal unit-name stem -- it derives "
                        "mios-%s.target" % (name, name))
        unit = "mios-%s.target" % name
        if not os.path.isfile(os.path.join(root, rs_UNIT_DIR, unit)):
            viol.append("archetype '%s' derives %s, which is not a shipped unit -- "
                        "role-apply would set-default a target that does not exist"
                        % (name, unit))
    return viol

def rs_check_capabilities_consumed(data: dict) -> list:
    """Every capability an archetype grants must be required by some unit --
    the reverse of check_blade_coverage, which proves the forward direction."""
    granted, viol = set(), []
    for caps in ((data.get("blade") or {}).get("archetypes") or {}).values():
        if isinstance(caps, str):
            caps = [caps]
        granted |= {str(c).strip() for c in (caps or []) if str(c).strip()}
    required = set()
    for caps in ((data.get("blade") or {}).get("requires") or {}).values():
        if isinstance(caps, str):
            caps = [caps]
        required |= {str(c).strip() for c in (caps or []) if str(c).strip()}
    for cap in sorted(granted - required):
        viol.append("capability '%s' is granted by an archetype but required by "
                    "NO unit -- an archetype that grants only it is a duplicate "
                    "of one that grants nothing" % cap)
    return viol

def rs_check_aliases(data: dict) -> list:
    viol, arche = [], rs_archetypes(data)
    for legacy, target in sorted(rs_aliases(data).items()):
        if target not in arche:
            viol.append("[blade.role_aliases].%s points at '%s', which is not an "
                        "archetype" % (legacy, target))
        if legacy in arche:
            viol.append("[blade.role_aliases].%s shadows an archetype of the same "
                        "name -- one spelling, one meaning (Law 9)" % legacy)
    return viol

def rs_check_conflicts(data: dict, root: str) -> list:
    """Role targets must conflict pairwise: they are reached by `systemctl
    start`, not by isolation, so a missing edge leaves the old role active."""
    viol, targets = [], rs_role_targets(data)
    if len(targets) < 2:
        return viol
    for unit in targets:
        body = rs_unit_body(root, unit)
        if not body:
            continue  # check_targets already reported the missing unit
        m = re.search(r"^Conflicts=(.*)$", body, re.M)
        have = set(m.group(1).split()) if m else set()
        want = set(targets) - {unit}
        missing = sorted(want - have)
        if missing:
            viol.append("%s does not conflict with %s -- switching away from it "
                        "would leave it active" % (unit, ", ".join(missing)))
        stray = sorted(have - want)
        if stray:
            viol.append("%s conflicts with %s, which is not a role target"
                        % (unit, ", ".join(stray)))
    return viol

def rs_check_aliases_in_units(root: str) -> list:
    """An Alias= must carry the same suffix as the unit itself; systemd cannot
    install one that does not, leaving the unit with no [Install] at all."""
    viol = []
    unit_dir = os.path.join(root, rs_UNIT_DIR)
    if not os.path.isdir(unit_dir):
        return viol
    for name in sorted(os.listdir(unit_dir)):
        path = os.path.join(unit_dir, name)
        if not os.path.isfile(path) or "." not in name:
            continue
        suffix = "." + name.rsplit(".", 1)[1]
        try:
            with open(path, encoding="utf-8", errors="replace") as fh:
                body = fh.read()
        except OSError:
            continue
        for m in re.finditer(r"^Alias=(.*)$", body, re.M):
            for alias in m.group(1).split():
                if not alias.endswith(suffix):
                    viol.append("%s declares Alias=%s -- an alias must carry the "
                                "same suffix (%s) as its unit, so systemd cannot "
                                "install it" % (name, alias, suffix))
    return viol

def rs_check_profile_retired(data: dict, root: str) -> list:
    """[profile].role was a second spelling of the archetype, read by nothing.
    It may come back only as a legal alias of [blade].type."""
    viol, arche = [], rs_archetypes(data)
    profile = data.get("profile")
    if isinstance(profile, dict):
        for key in profile:
            if key.lower() == "role":
                val = str(profile[key] or "").strip()
                if val not in arche:
                    viol.append("[profile].%s is '%s', which is not a legal "
                                "[blade].type (declared: %s)"
                                % (key, val, ", ".join(sorted(arche))))
            if key.lower() == "features":
                viol.append("[profile].%s is retired -- blade capabilities are a "
                            "closed set; grant one with `mios blade "
                            "add-capability`" % key)
    for rel in rs_KEEP_LISTS:
        path = os.path.join(root, rel)
        try:
            with open(path, encoding="utf-8", errors="replace") as fh:
                body = fh.read()
        except OSError:
            continue
        for name in rs_RETIRED_NAMES:
            if name in body:
                viol.append("%s still references %s -- the retired [profile] keys "
                            "must not be resurrected by a keep-list" % (rel, name))
    return viol

def rs_check_no_hardcoded_roles(data: dict, root: str) -> list:
    """The blade code must not restate [blade.archetypes]. No literal is
    permitted: the floor is the generated karg, the demotion target is
    [blade].fallback."""
    viol = []
    names = sorted(rs_archetypes(data))
    # A BLADE_CODE file that is absent yet TRACKED is a deleted deliverable and
    # must not shrink the subject list in silence. Absent and untracked is a
    # fixture root, where skipping is correct -- so the predicate is
    # "tracked here", not "absent".
    import subprocess
    tracked_here = set()
    try:
        _p = subprocess.run(["git", "-C", root, "ls-files", *rs_BLADE_CODE],
                            capture_output=True, text=True, check=False)
        if _p.returncode == 0:
            tracked_here = {l.strip().replace(os.sep, "/")
                            for l in _p.stdout.splitlines() if l.strip()}
    except OSError:
        pass
    for rel in rs_BLADE_CODE:
        path = os.path.join(root, rel)
        try:
            with open(path, encoding="utf-8", errors="replace") as fh:
                lines = fh.readlines()
        except OSError as exc:
            if rel in tracked_here:
                viol.append("%s: blade code listed in BLADE_CODE is TRACKED but "
                            "could not be read (%s), so it was never checked "
                            "for a restated archetype" % (rel, exc))
            continue
        in_heredoc = None
        for num, line in enumerate(lines, 1):
            # A heredoc body is not shell control flow. The embedded python that
            # READS [blade.archetypes] necessarily names TOML keys -- `endpoint`
            # is both an archetype and a very ordinary config key -- and flagging
            # that would punish the SSOT read this rule exists to require.
            if in_heredoc is not None:
                if line.strip() == in_heredoc:
                    in_heredoc = None
                continue
            opened = re.search(r"<<-?'?([A-Za-z_][A-Za-z0-9_]*)'?", line)
            if opened:
                in_heredoc = opened.group(1)
                continue
            code = line.split("#", 1)[0]
            for name in names:
                # A token after `.` is a member/key access, not a bare role:
                # `[ai].endpoint` names a TOML key that happens to share a name
                # with an archetype. `mios-endpoint.target` is still caught --
                # only `.` is excluded, never `-`.
                if re.search(r"(?<!\.)\b%s\b" % re.escape(name), code):
                    viol.append("%s:%d spells the archetype '%s' as a literal -- "
                                "the archetype table is [blade.archetypes], not "
                                "code (Law 7)" % (rel, num, name))
    return viol

def rs_collect(data: dict, root: str) -> list:
    return (rs_check_type(data)
            + rs_check_targets(data, root)
            + rs_check_capabilities_consumed(data)
            + rs_check_aliases(data)
            + rs_check_conflicts(data, root)
            + rs_check_aliases_in_units(root)
            + rs_check_profile_retired(data, root)
            + rs_check_no_hardcoded_roles(data, root))

def rs_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or "."
    path = os.path.join(root, rs_TOML)
    try:
        with open(path, "rb") as fh:
            data = tomllib.load(fh)
    except OSError as exc:
        print("check-role-ssot: cannot read %s: %s" % (path, exc), file=sys.stderr)
        return 1

    viol = rs_collect(data, root)
    if viol:
        for v in viol:
            print("check_role_ssot: %s" % v, file=sys.stderr)
        return 1

    arche = rs_archetypes(data)
    seats = sorted(n for n, caps in arche.items() if not caps)
    print("[check-role-ssot] %d archetype(s), each with a shipped target and a "
          "complete conflict graph; %d alias(es); seat(s): %s; [blade].type=%s"
          % (len(arche), len(rs_aliases(data)), ", ".join(seats) or "none",
             (data.get("blade") or {}).get("type")))
    return 0


"""Gate: every node in the fan-out pool is a distinct, reachable, honest lane."""

import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover -- py<3.11
    import tomli as tomllib  # type: ignore

np_TOML = "usr/share/mios/mios.toml"

def np_nodes(data: dict) -> dict:
    """{name: cfg} for every declared compute node."""
    return {str(k): v for k, v in (data.get("nodes") or {}).items()
            if isinstance(v, dict)}

def np_lane_vocabulary(data: dict) -> set:
    """Legal lane names, read from [dispatch].lane_priority -- the one place the
    scheduler's buckets are declared."""
    raw = str((data.get("dispatch") or {}).get("lane_priority") or "")
    out = set()
    for part in raw.split(","):
        name = part.split(":", 1)[0].strip()
        if name and not name.startswith("_"):
            out.add(name)
    return out

def np_blades(data: dict) -> set:
    return {str(k) for k in (data.get("blades") or {})}

def np__ep(cfg: dict) -> str:
    return str(cfg.get("endpoint") or "").rstrip("/")

def np_aliases(data: dict) -> list:
    """Two nodes with the same (endpoint, model, lane) are one backend twice."""
    seen, viol = {}, []
    for name, cfg in sorted(np_nodes(data).items()):
        ep = np__ep(cfg)
        if not ep:
            continue  # an empty endpoint is a declared-inert placeholder
        key = (ep, str(cfg.get("model") or ""), str(cfg.get("lane") or ""))
        if key in seen:
            viol.append("[nodes].%s duplicates [nodes].%s exactly (%s) -- the "
                        "fan-out counts one backend as two lanes"
                        % (name, seen[key], key[0]))
        else:
            seen[key] = name
    return viol

def np_lane_conflicts(data: dict) -> list:
    """One endpoint cannot be two lanes: the semaphore bucket would be split."""
    by_ep, viol = {}, []
    for name, cfg in sorted(np_nodes(data).items()):
        ep = np__ep(cfg)
        if ep:
            by_ep.setdefault(ep, []).append((name, str(cfg.get("lane") or "")))
    for ep, entries in sorted(by_ep.items()):
        lanes = {lane for _, lane in entries}
        if len(lanes) > 1:
            viol.append("endpoint %s is declared as %s by %s -- one endpoint, "
                        "one lane" % (ep, "/".join(sorted(lanes)),
                                      ", ".join(n for n, _ in entries)))
    return viol

def np_illegal_lanes(data: dict) -> list:
    vocab, viol = np_lane_vocabulary(data), []
    if not vocab:
        return ["[dispatch].lane_priority declares no lanes -- the gate would "
                "pass vacuously"]
    for name, cfg in sorted(np_nodes(data).items()):
        lane = str(cfg.get("lane") or "").strip()
        if lane and lane not in vocab:
            viol.append("[nodes].%s declares lane '%s', which [dispatch]."
                        "lane_priority does not budget (legal: %s)"
                        % (name, lane, ", ".join(sorted(vocab))))
    return viol

def np_orphan_blades(data: dict) -> list:
    """A node MAY omit `blade` -- it then belongs to the local blade, whose name
    comes from [identity].hostname. Naming one that does not exist is the error."""
    known, viol = np_blades(data), []
    for name, cfg in sorted(np_nodes(data).items()):
        blade = str(cfg.get("blade") or "").strip()
        if blade and blade not in known:
            viol.append("[nodes].%s names blade '%s', which [blades] does not "
                        "declare" % (name, blade))
    return viol

np__LOCAL = re.compile(r"://(?:localhost|127\.0\.0\.1):(\d+)")

def np_unmovable_endpoints(data: dict) -> list:
    """A local endpoint with a baked port cannot be repointed at a blade."""
    viol = []
    for name, cfg in sorted(np_nodes(data).items()):
        ep = np__ep(cfg)
        for m in np__LOCAL.finditer(ep):
            viol.append("[nodes].%s bakes port %s into its endpoint -- an "
                        "/etc/mios overlay cannot move it, so the node can never "
                        "be offloaded" % (name, m.group(1)))
    return viol

def np_classify(data: dict) -> list:
    if not np_nodes(data):
        return ["[nodes] declares no compute node -- the gate would pass "
                "vacuously over an empty pool"]
    return (np_aliases(data) + np_lane_conflicts(data) + np_illegal_lanes(data)
            + np_orphan_blades(data) + np_unmovable_endpoints(data))

def np_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or "."
    path = os.path.join(root, np_TOML)
    try:
        with open(path, "rb") as fh:
            data = tomllib.load(fh)
    except OSError as exc:
        print("check-node-pool: cannot read %s: %s" % (path, exc), file=sys.stderr)
        return 1

    viol = np_classify(data)
    if viol:
        for v in viol:
            print("check_node_pool: %s" % v, file=sys.stderr)
        return 1

    n = np_nodes(data)
    live = {np__ep(c) for c in n.values() if np__ep(c)}
    print("[check-node-pool] %d node(s) over %d distinct endpoint(s); lanes %s; "
          "%d declared inert" % (len(n), len(live),
                                 "/".join(sorted(np_lane_vocabulary(data))),
                                 sum(1 for c in n.values() if not np__ep(c))))
    return 0


"""Gate: every service is capability-gated, or registered as ungated core."""

import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover -- py<3.11
    import tomli as tomllib  # type: ignore

bc_TOML = "usr/share/mios/mios.toml"

def bc_containers(data: dict) -> set:
    """Every Quadlet container the SSOT declares."""
    return set(data.get("containers") or {})

def bc_long_running_units(root: str) -> set:
    """Shipped .service units that stay up. A oneshot needs no blade gate: it
    runs, exits, and costs a seat nothing to leave enabled."""
    out = set()
    unit_dir = os.path.join(root, "usr/lib/systemd/system")
    if not os.path.isdir(unit_dir):
        return out
    for name in sorted(os.listdir(unit_dir)):
        if not name.endswith(".service") or "@" in name:
            continue
        try:
            with open(os.path.join(unit_dir, name), encoding="utf-8",
                      errors="replace") as fh:
                body = fh.read()
        except OSError:
            continue
        stype = ""
        for line in body.splitlines():
            if line.startswith("Type="):
                stype = line.split("=", 1)[1].strip()
                break
        if stype != "oneshot":
            out.add(name[:-len(".service")])
    return out

def bc_all_units(data: dict, root: str) -> set:
    """Units that MUST carry a classification: containers and long-running
    services. Containers and native units share ONE namespace -- a Quadlet named
    `x` generates `x.service` -- so one classification covers both spellings."""
    return bc_containers(data) | bc_long_running_units(root)

def bc_known_units(data: dict, root: str) -> set:
    """Every shipped unit stem, any type. Wider than all_units on purpose: a
    oneshot or a target needs no classification of its own, but MAY legitimately
    be gated because it activates something that is."""
    out = set(bc_containers(data))
    unit_dir = os.path.join(root, "usr/lib/systemd/system")
    if os.path.isdir(unit_dir):
        for name in os.listdir(unit_dir):
            if os.path.isfile(os.path.join(unit_dir, name)) and "." in name:
                out.add(name.rsplit(".", 1)[0])
    return out

def bc_seat_side(data: dict) -> list:
    """Units a seat deliberately runs -- a positive claim, not debt."""
    reg = (data.get("blade") or {}).get("seat_side") or []
    return [str(x).strip() for x in reg if str(x).strip()]

# Ordering only. After= does not activate anything, so it never propagates a gate.
bc__PULL_KEYS = ("Requires=", "BindsTo=", "Requisite=", "Wants=")

def bc_unit_pulls(root: str) -> dict:
    """{unit-stem: {dependency-stem, ...}} over every shipped unit of any type.

    Only ACTIVATING dependencies count: a unit that merely orders itself After=
    a gated unit is unaffected when that unit is condition-skipped.
    """
    out = {}
    unit_dir = os.path.join(root, "usr/lib/systemd/system")
    if not os.path.isdir(unit_dir):
        return out
    for name in sorted(os.listdir(unit_dir)):
        path = os.path.join(unit_dir, name)
        if not os.path.isfile(path) or "." not in name:
            continue
        try:
            with open(path, encoding="utf-8", errors="replace") as fh:
                body = fh.read()
        except OSError:
            continue
        deps = set()
        for line in body.splitlines():
            for key in bc__PULL_KEYS:
                if line.startswith(key):
                    for tok in line[len(key):].split():
                        deps.add(tok[:-len(".service")]
                                 if tok.endswith(".service") else tok)
        if deps:
            out[name.rsplit(".", 1)[0]] = deps
    return out

def bc_soft_ok(data: dict) -> list:
    """Units whose pull on a gated unit is soft and that degrade without it."""
    reg = (data.get("blade") or {}).get("soft_ok") or []
    return [str(x).strip() for x in reg if str(x).strip()]

def bc_dependency_violations(data: dict, root: str) -> list:
    """A unit activating a gated unit must carry its capabilities (ADR-0016 D4)."""
    req = bc_requires(data)
    seat = set(bc_seat_side(data)) | set(bc_soft_ok(data))
    viol = []
    for stem, deps in sorted(bc_unit_pulls(root).items()):
        hit = deps & set(req)
        if not hit:
            continue
        need = set().union(*(set(req[h]) for h in hit))
        have = set(req.get(stem, []))
        if stem in seat or need <= have:
            continue
        viol.append("unit '%s' activates %s but is missing their capability %s -- "
                    "it would start where its dependency is condition-skipped"
                    % (stem, "/".join(sorted(hit)),
                       "/".join(sorted(need - have))))
    return viol

def bc_port_namers(data: dict, root: str) -> dict:
    """{port-key: {unit-stem, ...}} over every shipped unit that names a port,
    by MIOS_PORT_<KEY> or by its literal value."""
    ports = {k: v for k, v in (data.get("ports") or {}).items() if isinstance(v, int)}
    out = {k: set() for k in ports}
    for base in ("usr/lib/systemd/system", "usr/share/containers/systemd"):
        d = os.path.join(root, base)
        if not os.path.isdir(d):
            continue
        for name in sorted(os.listdir(d)):
            path = os.path.join(d, name)
            if not os.path.isfile(path) or "." not in name:
                continue
            try:
                with open(path, encoding="utf-8", errors="replace") as fh:
                    body = fh.read()
            except OSError:
                continue
            code = "\n".join(l for l in body.splitlines()
                              if not l.lstrip().startswith("#"))
            stem = name.rsplit(".", 1)[0]
            for key, num in ports.items():
                if any((prefix + key.upper()) in code for prefix in ("MIOS_PORTS_", "MIOS_PORT_")) or \
                        re.search(r"(?<![0-9])%d(?![0-9])" % num, code):
                    out[key].add(stem)
    return out

def bc_person_facing(data: dict) -> set:
    """Ports whose client is the human: anything with a browser-openable [urls]
    entry, plus the front door [ai].endpoint resolves. Derived, not declared."""
    out = set()
    for value in ((data.get("urls") or {}).values()):
        if isinstance(value, str):
            out |= {m.lower() for m in
                    re.findall(r"\$\{MIOS_(?:PORTS?)_([A-Z0-9_]+)\}", value)}
    endpoint = str((data.get("ai") or {}).get("endpoint") or "")
    out |= {m.lower() for m in
            re.findall(r"\$\{MIOS_(?:PORTS?)_([A-Z0-9_]+)\}", endpoint)}
    return out

def bc_seat_dead_weight(data: dict, root: str) -> list:
    """A seat-side unit whose port only a gated unit dials is dead weight. The
    coupling is an address, so the dependency walk cannot see it."""
    req, seat = bc_requires(data), set(bc_seat_side(data))
    soft = set(bc_soft_ok(data))
    viol = []
    for key, namers in sorted(bc_port_namers(data, root).items()):
        if key in bc_person_facing(data):
            continue          # the client is the human, not another unit
        binders = namers & seat
        others = namers - seat
        if not binders or not others:
            continue          # nobody else names it: the person is the client
        if others - set(req) - soft:
            continue          # at least one ungated client remains
        viol.append("seat-side %s binds '%s', but every other unit naming it "
                    "(%s) is capability-gated -- on a seat it serves nothing"
                    % ("/".join(sorted(binders)), key, ", ".join(sorted(others))))
    return viol

def bc_requires(data: dict) -> dict:
    """{service: [capability, ...]} from [blade.requires]."""
    out = {}
    for svc, caps in ((data.get("blade") or {}).get("requires") or {}).items():
        if isinstance(caps, str):
            caps = [caps]
        out[svc] = [str(c).strip() for c in (caps or []) if str(c).strip()]
    return out

def bc_archetype_caps(data: dict) -> set:
    """Every capability some archetype can grant."""
    out = set()
    for caps in ((data.get("blade") or {}).get("archetypes") or {}).values():
        if isinstance(caps, str):
            caps = [caps]
        for c in caps or []:
            out.add(str(c).strip())
    return {c for c in out if c}

def bc_register(data: dict) -> list:
    """The shrink-only ungated register, in declaration order."""
    reg = (data.get("blade") or {}).get("ungated") or []
    return [str(x).strip() for x in reg if str(x).strip()]

def bc_classify(data: dict, root: str = ".") -> list:
    """Return the violations; empty means every unit has exactly one answer."""
    viol = []
    units = bc_all_units(data, root)
    if not units:
        return ["no containers and no long-running units found -- the gate would "
                "pass vacuously over an empty set"]

    req = bc_requires(data)
    granted = bc_archetype_caps(data)
    reg, seat = bc_register(data), bc_seat_side(data)
    reg_set, seat_set = set(reg), set(seat)

    for name, lst in (("ungated", reg), ("seat_side", seat)):
        if len(lst) != len(set(lst)):
            dupes = sorted({k for k in lst if lst.count(k) > 1})
            viol.append("[blade].%s lists a unit twice: %s" % (name, ", ".join(dupes)))

    known = bc_known_units(data, root)
    for label, names in (("[blade.requires] gates", set(req)),
                         ("[blade].ungated names", reg_set),
                         ("[blade].seat_side names", seat_set)):
        for svc in sorted(names - known):
            viol.append("%s '%s', which is not a declared container or a shipped "
                        "unit" % (label, svc))

    for svc in sorted((set(req) & reg_set) | (set(req) & seat_set)
                      | (reg_set & seat_set)):
        viol.append("unit '%s' is classified more than once -- gated, seat-side "
                    "and ungated are mutually exclusive" % svc)

    fallbacks = (data.get("blade") or {}).get("cpu_fallbacks") or {}
    for svc, caps in sorted(req.items()):
        if not caps:
            viol.append("[blade.requires].%s lists no capability -- an empty list "
                        "gates nothing, so say so in [blade].seat_side instead" % svc)
        if "gpu-serving" in caps and (svc not in fallbacks or not fallbacks[svc]):
            viol.append("unit '%s' requires 'gpu-serving' but declares no fallback in [blade.cpu_fallbacks] (task_2237)" % svc)
        for cap in caps:
            if cap not in granted:
                viol.append("capability '%s' (required by %s) is granted by NO "
                            "archetype -- nothing could ever activate it" % (cap, svc))

    for svc in sorted(units - set(req) - reg_set - seat_set):
        viol.append("unit '%s' is classified nowhere -- gate it in [blade.requires], "
                    "declare it in [blade].seat_side, or register the debt in "
                    "[blade].ungated" % svc)

    viol.extend(bc_dependency_violations(data, root))
    viol.extend(bc_seat_dead_weight(data, root))
    return viol

def bc_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or "."
    path = os.path.join(root, bc_TOML)
    try:
        with open(path, "rb") as fh:
            data = tomllib.load(fh)
    except OSError as exc:
        print("check-blade-coverage: cannot read %s: %s" % (path, exc), file=sys.stderr)
        return 1

    viol = bc_classify(data, root)
    if viol:
        for v in viol:
            print("check_blade_coverage: %s" % v, file=sys.stderr)
        return 1

    must = bc_all_units(data, root)
    req = bc_requires(data)
    print("[check-blade-coverage] %d unit(s) require a classification: %d gated, "
          "%d seat-side, %d registered ungated. %d further unit(s) are gated "
          "because they activate one (oneshots, targets)."
          % (len(must), len(set(req) & must), len(bc_seat_side(data)),
             len(bc_register(data)), len(set(req) - must)))
    return 0


import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover -- py<3.11
    import tomli as tomllib  # type: ignore

fs_TOML = "usr/share/mios/mios.toml"

def fs_fleet_shape(data: dict) -> dict:
    """[blades] min/typical/max node counts."""
    b = data.get("blades") or {}
    return {k: b.get(k) for k in ("min_nodes", "typical_nodes", "max_nodes")}

def fs_archetypes_granting(data: dict, needed) -> list:
    """Archetypes granting EVERY capability in `needed`."""
    blade = data.get("blade") or {}
    out = []
    for name, caps in (blade.get("archetypes") or {}).items():
        if isinstance(caps, str):
            caps = [caps]
        have = {str(c).strip() for c in (caps or [])}
        if set(needed) <= have:
            out.append(name)
    return sorted(out)

def fs_k3s_multi_server(data: dict, root: str):
    """More than one archetype can stand up a k3s control plane, and the unit
    has no join path. Detail string, or None."""
    req = ((data.get("blade") or {}).get("requires") or {}).get("mios-k3s")
    if not req:
        return None
    if isinstance(req, str):
        req = [req]
    grantors = fs_archetypes_granting(data, [str(c).strip() for c in req])
    if len(grantors) < 2:
        return None
    path = os.path.join(root, "usr/share/containers/systemd/mios-k3s.container")
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            body = fh.read()
    except OSError:
        return None
    code = "\n".join(l for l in body.splitlines() if not l.lstrip().startswith("#"))
    if not re.search(r"\bk3s\s+server\b", code):
        return None
    if "K3S_URL" in code:
        return None          # a join path exists; the peers are not independent
    return ("%d archetypes grant what mios-k3s requires (%s) and the unit runs "
            "`k3s server` with no K3S_URL -- each would stand up its OWN control "
            "plane" % (len(grantors), ", ".join(grantors)))

fs__UNFENCED = re.compile(r"stonith-enabled\s*=\s*false")

def fs_pacemaker_unfenced(data: dict, root: str):
    """Pacemaker configured with fencing off. Detail string, or None."""
    hits = []
    for base in ("usr/lib/systemd/system", "usr/libexec/mios"):
        d = os.path.join(root, base)
        if not os.path.isdir(d):
            continue
        for name in sorted(os.listdir(d)):
            p = os.path.join(d, name)
            if not os.path.isfile(p):
                continue
            try:
                with open(p, encoding="utf-8", errors="replace") as fh:
                    body = fh.read()
            except OSError:
                continue
            for num, line in enumerate(body.splitlines(), 1):
                if line.lstrip().startswith("#"):
                    continue
                if fs__UNFENCED.search(line):
                    hits.append("%s/%s:%d" % (base, name, num))
    if not hits:
        return None
    return ("fencing is disabled (%s) -- safe on one node, and how split-brain "
            "corrupts data on more" % ", ".join(hits))

fs_DETECTORS = (
    ("k3s-multi-server", fs_k3s_multi_server),
    ("pacemaker-unfenced", fs_pacemaker_unfenced),
)

def fs_detect(data: dict, root: str) -> dict:
    """{hazard-id: detail} for every hazard that currently reproduces."""
    out = {}
    for key, fn in fs_DETECTORS:
        detail = fn(data, root)
        if detail:
            out[key] = detail
    return out

def fs_register(data: dict) -> list:
    reg = ((data.get("blades") or {}).get("hazards") or {}).get("accepted")
    if reg is None:
        return []
    return [str(x).strip() for x in reg if str(x).strip()]

def fs_max_accepted(data: dict):
    val = ((data.get("blades") or {}).get("hazards") or {}).get("max_accepted")
    return val if isinstance(val, int) else None

def fs_violations(data: dict, root: str) -> list:
    viol = []
    shape = fs_fleet_shape(data)
    if not isinstance(shape.get("max_nodes"), int):
        return ["[blades].max_nodes is unset -- the fleet has no declared size, "
                "so nothing can tell a standalone-only config from a broken one"]
    max_nodes = shape["max_nodes"]

    hazards = data.get("blades", {}).get("hazards")
    if hazards is None:
        return ["[blades.hazards] is absent -- nothing bounds how many "
                "above-one-node hazards the tree may carry"]
    if "accepted" not in hazards:
        viol.append("[blades.hazards] declares no `accepted` key -- an implied "
                    "empty register is indistinguishable from a forgotten one")

    reg = fs_register(data)
    if len(reg) != len(set(reg)):
        dupes = sorted({x for x in reg if reg.count(x) > 1})
        viol.append("[blades.hazards].accepted lists a hazard twice: %s"
                    % ", ".join(dupes))
    if reg != sorted(reg):
        viol.append("[blades.hazards].accepted is not sorted -- an unsorted "
                    "register hides an addition inside a reordering")

    known = {k for k, _ in fs_DETECTORS}
    for bad in sorted(set(reg) - known):
        viol.append("[blades.hazards].accepted names '%s', which no detector "
                    "produces -- it can never be retired" % bad)

    found = fs_detect(data, root)
    if max_nodes <= 1:
        # Standalone by declaration: these hazards do not bite. Say so rather
        # than pass silently, because raising max_nodes must re-arm them.
        return viol

    for key in sorted(set(found) - set(reg)):
        viol.append("%s: %s. Fix it, or accept it in [blades.hazards].accepted "
                    "with a justification -- [blades].max_nodes is %d"
                    % (key, found[key], max_nodes))
    for key in sorted(set(reg) & known - set(found)):
        viol.append("[blades.hazards].accepted carries '%s', which no longer "
                    "reproduces -- drop it; the register only shrinks" % key)

    ceiling = fs_max_accepted(data)
    if ceiling is None:
        viol.append("[blades.hazards].max_accepted is unset -- without a ceiling "
                    "the register absorbs new hazards as fast as they appear")
    elif len(reg) > ceiling:
        viol.append("[blades.hazards].accepted holds %d, over the ratchet ceiling "
                    "max_accepted = %d. The ceiling only comes DOWN"
                    % (len(reg), ceiling))
    elif len(reg) < ceiling:
        viol.append("[blades.hazards].accepted holds %d but max_accepted is %d -- "
                    "lower it to %d so the ground gained is held"
                    % (len(reg), ceiling, len(reg)))
    return viol

def fs_main() -> int:
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or "."
    path = os.path.join(root, fs_TOML)
    try:
        with open(path, "rb") as fh:
            data = tomllib.load(fh)
    except OSError as exc:
        print("check-fleet-safety: cannot read %s: %s" % (path, exc), file=sys.stderr)
        return 1

    viol = fs_violations(data, root)
    if viol:
        for v in viol:
            print("check_fleet_safety: %s" % v, file=sys.stderr)
        return 1

    shape = fs_fleet_shape(data)
    print("[check-fleet-safety] fleet is %s-%s nodes (typical %s); %d "
          "above-one-node hazard(s) accepted (ceiling %s)."
          % (shape.get("min_nodes"), shape.get("max_nodes"),
             shape.get("typical_nodes"), len(fs_register(data)), fs_max_accepted(data)))
    return 0

_GATES = {"toml-integrity": mti_main, "consumer-keys": sck_main, "unit-projection": up_main, "port-fallbacks": pf_main, "ports-bound": pb_main, "variant-registry": vr_main, "deploy-formats": df_main, "role-ssot": rs_main, "node-pool": np_main, "blade-coverage": bc_main, "fleet-safety": fs_main}


def main() -> int:
    # An unknown or missing subcommand must FAIL, never report a clean gate.
    if len(sys.argv) < 2 or sys.argv[1] not in _GATES:
        sys.stderr.write("usage: check-ssot.py {%s}\n" % "|".join(sorted(_GATES)))
        return 2
    return _GATES[sys.argv.pop(1)]()


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# AI-hint: Task-plane drift gates in one module: the retired TASKS.md table-vs-section parity, AGY task schema, and task id/dependency resolution, over the frozen lists tasks.jsonl keeps (ADR-0028).
# AI-doc: usr/share/doc/mios/manual/tools.md
# AI-functions: main, status_parity_main, schema_main, agy_main
"""Task-plane drift gates. One module, one subcommand per gate.

The frozen lists name every task by its typed id, task_<number> (ADR-0028: migrate-ids rewrote the old ids).
"""

import json
import os
import re
import sys


TASKS = "TASKS.md"
AGY_TASKS = "AGY-TASKS.md"
PLACEHOLDER = "?"
# A typed task id; the number is the task's creation-order number in tasks.jsonl.
TASK = r"task_([1-9][0-9]*)"


def store_path(root: str):
    try:
        with open(os.path.join(root, "usr/share/mios/mios.toml"), "rb") as fh:
            return os.path.join(root, tomllib.load(fh)["tasks"]["store"]["path"])
    except (FileNotFoundError, KeyError):
        return None


def list_text(root: str, name: str):
    """A retired task list rebuilt from its frozen slices in tasks.jsonl (ADR-0028), else the file itself."""
    parts = []
    store = store_path(root)
    if store and os.path.isfile(store):
        with open(store, encoding="utf-8") as fh:
            parts = sorted((s["offset"], s["text"]) for rec in map(json.loads, fh)
                           for s in (rec.get("provenance") or {}).get("sources") or [] if s["file"] == "MiOS:" + name)
    if parts:
        return "".join(t for _, t in parts)
    path = os.path.join(root, name)
    return open(path, encoding="utf-8", errors="replace").read() if os.path.isfile(path) else None


def task_numbers(root: str):
    """Every task number tasks.jsonl holds, or None for a fixture root without one."""
    store = store_path(root)
    if not store or not os.path.isfile(store):
        return None
    with open(store, encoding="utf-8") as fh:
        return {r["number"] for r in map(json.loads, fh) if isinstance(r.get("number"), int)}


KNOWN = {
    "done", "done-by-code", "completed", "retired",
    "planned", "planned/unverified", "in-progress", "pending",
    "partial", "open", "blocked", "built-gated-off",
}

_SECTION_RE = re.compile(r"^## (" + TASK + r")\s*(?:--|:)\s*(.*?)(?=^## |\Z)", re.M | re.S)
_STATUS_RE = re.compile(r"^\*\*Status:\*\*\s*(.+?)\s*(?:\||$)", re.M)
_ROW_RE = re.compile(r"^\|\s*(" + TASK + r")\s*\|\s*P\d\s*\|\s*([^|]+?)\s*\|")
# A heading of the frozen AGY-TASKS.md: '## task_12 -- title' (a range banner is one task too).
_HEAD_RE = re.compile(r"^#{2,3} " + TASK + r"(?=\s)", re.M)


def status_parity_head_token(status: str) -> str:
    """The comparable head of a free-prose status: everything before the first
    ` -- ` continuation or ` (` qualifier."""
    return re.split(r"\s+--\s+|\s*\(", status, maxsplit=1)[0].strip().rstrip(".,;:").lower()


def status_parity_detail_statuses(text: str) -> dict:
    out = {}
    for m in _SECTION_RE.finditer(text):
        sm = _STATUS_RE.search(m.group(0))
        if sm:
            out[m.group(1)] = sm.group(1).strip()
    return out


def status_parity_table_rows(text: str) -> dict:
    out = {}
    for line in text.splitlines():
        m = _ROW_RE.match(line)
        if m:
            out[m.group(1)] = m.group(3).strip()
    return out


def heading_numbers(text) -> set:
    return {int(m.group(1)) for m in _HEAD_RE.finditer(text or "")}


def status_parity_main() -> int:
    """Gate: TASKS.md summary table agrees with each section, and every task it names exists."""
    root = os.environ.get("MIOS_DRIFT_ROOT", os.environ.get("MIOS_TOML_ROOT", "."))
    text = list_text(root, TASKS)
    if text is None:
        print(f"{TASKS} not found under {root}, on disk or in tasks.jsonl")
        return 1
    detail = status_parity_detail_statuses(text)
    rows = status_parity_table_rows(text)
    if not rows:
        print(f"{TASKS} summary table has no parseable rows")
        return 1

    problems = []
    for tid in sorted(rows):
        cell = rows[tid]
        if tid not in detail:
            if cell == PLACEHOLDER:
                problems.append(f"{tid}: status is '?' and the task has no section to resolve it")
            elif cell not in KNOWN:
                problems.append(f"{tid}: unknown status '{cell}' in the summary table")
            continue
        want = status_parity_head_token(detail[tid])
        if cell == PLACEHOLDER:
            problems.append(
                f"{tid}: summary table says '?' while the task section says '{want}'")
        elif cell != want:
            problems.append(
                f"{tid}: summary table says '{cell}', the task section says '{want}'")
        if want not in KNOWN:
            problems.append(f"{tid}: unknown status '{want}' in the task section")

    for tid in sorted(set(detail) - set(rows)):
        problems.append(f"{tid}: has a task section but no row in the summary table")

    # Every task TASKS.md names exists: in tasks.jsonl, or (a fixture root) as a section, row or AGY heading.
    known = task_numbers(root)
    if known is None:
        known = {int(t[5:]) for t in set(rows) | set(detail)} | heading_numbers(list_text(root, AGY_TASKS))
    refs = [int(n) for n in re.findall(r"(?<![A-Za-z0-9_])" + TASK + r"(?![0-9])", text)]
    for ref in sorted(set(refs)):
        if ref not in known:
            problems.append(f"VIOLATION: TASKS.md references task_{ref}, which names no task")

    if problems:
        for p in problems:
            print(p)
        return 1

    closed = {"done", "done-by-code", "completed", "retired"}
    open_n = sum(1 for s in rows.values() if s not in closed)
    print(f"TASKS.md summary table matches every task section and every task it names exists "
          f"(tasks={len(rows)} sections={len(detail)} open={open_n} references={len(refs)})")
    return 0


try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover
    import tomli as tomllib  # type: ignore

DONE_MARKER = "[DONE]"

REQUIRED = ("Goal", "What+How", "Where", "Verify", "Do NOT", "Done When", "Why", "Dep")


def typed_number(value, key: str) -> int:
    m = re.fullmatch(TASK, str(value))
    if not m:
        raise ValueError(f"[tasks].{key} = {value!r} is not a typed task id (task_<number>)")
    return int(m.group(1))


def schema_main() -> int:
    """Gate: every AGY task from the schema floor on carries the full schema; a missing Verify is a task anyone can call done."""
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.getcwd()
    text = list_text(root, AGY_TASKS)
    if text is None:
        print(f"{AGY_TASKS} unreadable: not on disk and not in tasks.jsonl")
        return 1

    try:
        with open(os.path.join(root, "usr/share/mios/mios.toml"), "rb") as fh:
            tasks_tbl = (tomllib.load(fh).get("tasks") or {})
    except OSError:
        tasks_tbl = {}
    if tasks_tbl.get("schema_from") is None:
        print("mios.toml has no [tasks].schema_from -- without it the schema"
              " floor is a constant nobody can lower on purpose")
        return 1
    try:
        schema_from = typed_number(tasks_tbl["schema_from"], "schema_from")
        # Tasks created after the floor that the list files before it, so numbered below it.
        also = {typed_number(x, "schema_also") for x in tasks_tbl.get("schema_also") or []}
    except ValueError as e:
        print(e)
        return 1

    def demanded(tid: int, first_line: str) -> bool:
        return (tid >= schema_from or tid in also) and DONE_MARKER not in first_line

    blocks = re.split(r"(?=^#{2,3} task_[1-9][0-9]*\s)", text, flags=re.M)
    ids, viol = [], []
    for b in blocks:
        m = _HEAD_RE.match(b)
        if not m:
            continue
        tid = int(m.group(1))
        ids.append(tid)
        if not demanded(tid, b.split(chr(10))[0]):
            continue
        for field in REQUIRED:
            if f"**{field}:**" not in b:
                viol.append(f"task_{tid}: missing **{field}:**")

    known = task_numbers(root)
    if known is None:
        known = set(ids)
    for b in blocks:
        m = _HEAD_RE.match(b)
        if not m or not demanded(int(m.group(1)), b.split(chr(10))[0]):
            continue
        dep = re.search(r"^\*\*Dep:\*\*\s*(.+)$", b, re.M)
        if not dep:
            continue
        for ref in re.findall(TASK, dep.group(1)):
            if int(ref) not in known:
                viol.append(f"task_{m.group(1)}: **Dep:** names task_{ref}, which does not exist")

    dupes = sorted({i for i in ids if ids.count(i) > 1})
    ceil = tasks_tbl.get("max_duplicate_ids")
    if ceil is None:
        viol.append("mios.toml has no [tasks].max_duplicate_ids -- absent is a broken"
                    " ceiling, not an open one")
    elif len(dupes) > int(ceil):
        viol.append(f"duplicate task ids {len(dupes)} > ceiling {ceil}: "
                    f"{['task_%d' % d for d in dupes[:8]]}")

    print("\n".join(viol))
    if not viol:
        n = sum(1 for i in ids if i >= schema_from or i in also)
        print(f"[check-task-schema] {n} task(s) carry the full schema; "
              f"{len(dupes)}/{ceil} duplicate ids", file=sys.stderr)
    return 1 if viol else 0


def agy_extract_dep_ids(dep_str: str) -> list:
    """Every task a Dep line names; a span 'task_a..task_b' names its two ends."""
    return [int(n) for n in re.findall(TASK, dep_str)]


def agy_main() -> int:
    """Gate: AGY-TASKS.md headings are unique and every Dep names a task that exists."""
    root = os.environ.get("MIOS_DRIFT_ROOT", os.environ.get("MIOS_TOML_ROOT", "."))
    content = list_text(root, AGY_TASKS)
    if content is None:
        print(f"VIOLATION: {AGY_TASKS} not found under {root}, on disk or in tasks.jsonl")
        return 1

    header_pattern = re.compile(r"^#+\s*" + TASK + r"(?:\s+.*)?$")
    task_occurrences = {}
    for line_idx, line in enumerate(content.splitlines(), 1):
        m = header_pattern.match(line)
        if m:
            task_occurrences.setdefault(int(m.group(1)), []).append(line_idx)

    problems = []
    for tid, lines in task_occurrences.items():
        if len(lines) > 1:
            locs = ", ".join(f"line {n}" for n in lines)
            problems.append(f"VIOLATION: task_{tid} is defined multiple times ({locs})")

    known = task_numbers(root)
    if known is None:
        known = set(task_occurrences)
    dep_pattern = re.compile(r"\*\*Dep:\*\*\s*(.*)", re.IGNORECASE)
    refs = 0
    for line_idx, line in enumerate(content.splitlines(), 1):
        m = dep_pattern.search(line)
        if not m:
            continue
        dep_str = m.group(1).strip()
        if dep_str.lower() in ("none", "n/a", ""):
            continue
        for ref_id in agy_extract_dep_ids(dep_str):
            refs += 1
            if ref_id not in known:
                problems.append(
                    f"VIOLATION: line {line_idx} has dangling dependency reference task_{ref_id}"
                )

    if problems:
        for p in problems:
            print(p)
        return 1

    print(f"AGY task id parity check passed (headings={len(task_occurrences)}, dep_references={refs})")
    return 0


_GATES = {"status-parity": status_parity_main, "schema": schema_main, "agy": agy_main}


def main() -> int:
    # An unknown or missing subcommand must FAIL, never report a clean gate.
    if len(sys.argv) < 2 or sys.argv[1] not in _GATES:
        sys.stderr.write("usage: check-tasks.py {%s}\n" % "|".join(sorted(_GATES)))
        return 2
    return _GATES[sys.argv.pop(1)]()


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# AI-hint: Resolves the [ci] suite registry for the runners and fails when a tracked suite is neither registered in a tier nor exempted.
# AI-related: usr/share/mios/mios.toml, tests/run-suites.sh, automation/98-drift-checks.sh
import fnmatch
import os
import re
import sys
from pathlib import Path

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from mios_tracked import tracked, GitUnavailable  # noqa: E402

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover
    import tomli as tomllib  # type: ignore

# Scanned for coverage. Anything a runner could reasonably be expected to
# execute, so a dead suite has to be declared dead rather than merely ignored.
#
# The two fitness-function stages are named because leaving them out was not a
# gap, it was a hole: deleting "automation/98-drift-checks.sh" from
# [ci.tiers].gate raised no violation here, the gate tier stayed non-empty so
# run-suites.sh's zero-suite guard never fired either, and the entire drift gate
# stopped running while both reported green.
TRACKED = ("tests/test-*.sh", "tests/test-*.py", "tests/*.sh", "tests/**/*.sh",
           "automation/lint-*.sh", "automation/97-*.sh", "automation/98-*.sh")
# Known still outside TRACKED, so still able to fall out of CI unnoticed:
# automation/test_*.sh, automation/tests/*.sh, automation/lib/test_*.sh,
# usr/lib/mios/**, usr/libexec/mios/test_*.py and usr/share/mios/tests/*.sh --
# 19 tracked suites at last count. Widening to them is a registry change, not a
# reader change: each has to land in a tier or in [ci.exempt] first.

def _root() -> str:
    return os.environ.get("MIOS_DRIFT_ROOT") or os.environ.get("MIOS_ROOT") or os.getcwd()

def _load(root: str) -> dict:
    with open(os.path.join(root, "usr/share/mios/mios.toml"), "rb") as fh:
        return tomllib.load(fh).get("ci") or {}

def _load_packages(root: str) -> dict:
    with open(os.path.join(root, "usr/share/mios/mios.toml"), "rb") as fh:
        return tomllib.load(fh).get("packages") or {}

def _tokens(value, name: str) -> list:
    if not isinstance(value, list) or any(
            not isinstance(v, str) or not v or v.startswith("-")
            or any(c.isspace() for c in v) for v in value):
        raise ValueError(f"{name} must be a list of non-empty argument tokens")
    return value


def fedora_arguments(root: str, ci: dict, option: str) -> list:
    """Resolve CI provisioning from the vendor package dependency closure."""
    fed = ci.get("fedora")
    if not isinstance(fed, dict):
        raise ValueError("mios.toml has no [ci.fedora] table")
    if option == "--fedora-image":
        image = fed.get("image")
        return _tokens([image], "[ci.fedora].image")
    if option == "--dnf-repos":
        return list(dict.fromkeys(_tokens(fed.get("repos"), "[ci.fedora].repos")))
    packages = _load_packages(root)
    result, visited = [], set()

    def visit(name: str, trail: tuple = ()) -> None:
        if name in trail:
            raise ValueError("cyclic package section dependency: " + " -> ".join((*trail, name)))
        if name in visited:
            return
        section = packages.get(name)
        if not isinstance(section, dict):
            raise ValueError(f"[ci.fedora] names missing [packages.{name}]")
        if section.get("enable", True) is not True:
            raise ValueError(f"[ci.fedora] requires disabled [packages.{name}]")
        pkgs = _tokens(section.get("pkgs"), f"[packages.{name}].pkgs")
        if not pkgs:
            raise ValueError(f"[packages.{name}].pkgs is empty")
        for dep in _tokens(section.get("requires_sections", []),
                           f"[packages.{name}].requires_sections"):
            visit(dep, (*trail, name))
        result.extend(pkgs)
        visited.add(name)

    for name in _tokens(fed.get("package_sets"), "[ci.fedora].package_sets"):
        visit(name)
    result.extend(_tokens(fed.get("packages"), "[ci.fedora].packages"))
    if not result:
        raise ValueError("[ci.fedora] resolves no DNF packages")
    return list(dict.fromkeys(result))


def _tracked(root: str) -> list:
    """git-tracked, not os.walk: a runner executes what the repository ships.

    Raises GitUnavailable rather than returning an empty corpus.
    """
    return sorted(set(tracked(root, *TRACKED)))

def _glob_members(root: str, spec: dict) -> list:
    d = spec.get("dir", "")
    pat = spec.get("glob", "*")
    skip = set(spec.get("skip") or ())
    full = os.path.join(root, d)
    if not os.path.isdir(full):
        return []
    # fnmatchcase, never fnmatch: the case-insensitive form resolves the
    # registry differently on Windows than it does on the runner.
    return [f"{d}/{fn}" for fn in sorted(os.listdir(full))
            if fnmatch.fnmatchcase(fn, pat) and fn not in skip]

def _registered(root: str, ci: dict) -> dict:
    """path -> tier, for every listed suite and every glob member."""
    reg = {}
    for tier, paths in (ci.get("tiers") or {}).items():
        for p in paths:
            reg[p] = tier
    for spec in (ci.get("globs") or {}).values():
        for p in _glob_members(root, spec):
            reg[p] = spec.get("tier", "unit")
    return reg

# `if:` values that switch a step off outright. An arbitrary expression is left
# alone -- guessing at one would be a worse lie than reading none.
_DISABLED = {"false", "'false'", '"false"', "${{ false }}", "${{false}}"}
_INVOKE = re.compile(r"run-suites\.sh\s+(\S+)")

def _live_run_commands(body: str) -> list:
    """The shell commands a workflow actually executes.

    Parity used to be `f"run-suites.sh {tier}" in body`: a raw substring over the
    whole file, comments and disabled steps included. A step commented out, or
    guarded `if: false`, kept satisfying the one check whose entire job is to
    notice that a publisher has quietly stopped running a tier. Only the value of
    a live `run:` key counts now.
    """
    steps, cur = [], None
    for raw in body.splitlines():
        if not raw.strip():
            continue
        ind = len(raw) - len(raw.lstrip())
        if raw.lstrip().startswith("-"):
            if cur:
                steps.append(cur)
            cur = [ind, [raw]]
        elif cur and ind > cur[0]:
            cur[1].append(raw)
        elif cur:
            steps.append(cur)
            cur = None
    if cur:
        steps.append(cur)

    cmds = []
    for _, chunk in steps:
        keys = [ln.strip()[2:].lstrip() if ln.strip().startswith("- ")
                else ln.strip() for ln in chunk]
        if any(k.startswith("if:") and k[3:].strip() in _DISABLED for k in keys):
            continue
        block = 0
        for raw, key in zip(chunk, keys):
            ind = len(raw) - len(raw.lstrip())
            if block:
                if ind >= block:
                    line = raw.strip()
                    if not line.startswith("#"):
                        cmds.append(line.split(" #", 1)[0].strip())
                    continue
                block = 0
            if key.startswith("#"):
                continue
            if key.startswith("run:"):
                val = key[4:].strip()
                if val.startswith(("|", ">")):
                    block = ind + 1
                else:
                    cmds.append(val.split(" #", 1)[0].strip())
    return cmds

def cmd_list(root: str, ci: dict, tier: str) -> int:
    reg = _registered(root, ci)
    if tier not in (ci.get("tiers") or {}) and tier not in {
            s.get("tier") for s in (ci.get("globs") or {}).values()}:
        print(f"unknown tier: {tier}", file=sys.stderr)
        return 2
    for path in sorted(p for p, t in reg.items() if t == tier):
        runner = "python3" if path.endswith(".py") else "bash"
        print(f"{runner}\t{path}")
    return 0

def cmd_check(root: str, ci: dict) -> int:
    viol = []
    reg = _registered(root, ci)
    exempt = ci.get("exempt") or {}

    for path, tier in sorted(reg.items()):
        if not os.path.isfile(os.path.join(root, path)):
            viol.append(f"[ci.tiers].{tier} lists {path}, which does not exist")

    listed = {}
    for tier, paths in (ci.get("tiers") or {}).items():
        for p in paths:
            if p in listed:
                viol.append(f"{p} is registered in both {listed[p]} and {tier}")
            listed[p] = tier

    for name, spec in sorted((ci.get("globs") or {}).items()):
        d, pat = spec.get("dir", ""), spec.get("glob", "*")
        if not os.path.isdir(os.path.join(root, d)):
            viol.append(f"[ci.globs.{name}] dir '{d}' is not a directory -- a"
                        " renamed dir registers zero suites and says nothing")
        elif not _glob_members(root, spec):
            viol.append(f"[ci.globs.{name}] '{d}/{pat}' matches no file -- an"
                        " empty glob removes every suite it used to supply"
                        " without moving a count anything watches")
        if spec.get("skip") and not str(spec.get("skip_reason") or "").strip():
            viol.append(f"[ci.globs.{name}] skips {len(spec['skip'])} suite(s)"
                        " with no skip_reason -- a skip is an exemption")
        for fn in spec.get("skip") or ():
            if not (fnmatch.fnmatchcase(fn, pat)
                    and os.path.isfile(os.path.join(root, d, fn))):
                viol.append(f"[ci.globs.{name}] skip '{fn}' names no {d}/{pat}"
                            " file -- a stale skip would silently exempt the"
                            " next suite given that name")

    # A runner is exempt from the tiers because it EXECUTES them. One that never
    # reads the registry is not a harness, it is a suite parked out of reach of
    # both the tiers and the exemption ratchet.
    runners = set(ci.get("runners") or ())
    for path in sorted(runners):
        full = os.path.join(root, path)
        if not os.path.isfile(full):
            viol.append(f"[ci].runners lists {path}, which does not exist")
        elif "ci-suites.py" not in Path(full).read_text(encoding="utf-8", errors="replace"):
            viol.append(f"[ci].runners {path} never reads the suite registry, so"
                        " it is not a harness -- a suite listed here runs nowhere"
                        " and never touches [ci].max_exempt_suites")

    try:
        suites = _tracked(root)
    except GitUnavailable as exc:
        suites = []
        viol.append(f"cannot enumerate tracked suites: {exc}")
    for path in suites:
        if path in reg or path in exempt or path in runners:
            continue
        viol.append(f"{path} is tracked but runs in no tier and is not exempt")

    for path, reason in sorted(exempt.items()):
        if not str(reason).strip():
            viol.append(f"[ci.exempt] {path} carries no reason")
        if path in reg:
            viol.append(f"{path} is both exempt and registered in {reg[path]}")

    tiers = sorted(ci.get("tiers") or {})
    for wf in (".github/workflows/mios-ci.yml", ".forgejo/workflows/build-mios.yml"):
        full = os.path.join(root, wf)
        if not os.path.isfile(full):
            viol.append(f"{wf} is missing -- both publishers must run the tiers")
            continue
        body = Path(full).read_text(encoding="utf-8", errors="replace")
        cmds = _live_run_commands(body)
        if not cmds:
            viol.append(f"{wf} has no live 'run:' step at all -- parity is read"
                        " off executed commands, not off the file's text")
        ran = {m.group(1).strip("'\"") for c in cmds for m in _INVOKE.finditer(c)}
        for tier in tiers:
            if tier not in ran:
                viol.append(f"{wf} never runs the '{tier}' tier")

    skips = ci.get("tool_skips") or {}
    for path, reason in sorted(skips.items()):
        if path not in reg:
            viol.append(f"[ci.tool_skips] {path} runs in no tier -- only a registered suite may skip")
        if not str(reason).strip():
            viol.append(f"[ci.tool_skips] {path} names no missing tool")
    if len(skips) > int(ci.get("max_tool_skips") or 0):
        viol.append(f"tool-skipping suites {len(skips)} > ceiling {ci.get('max_tool_skips') or 0}")

    # Restore the provisioning and image contracts alongside suite coverage.
    # A registered tier cannot run when the runner's dependency exporter broke.
    for option in ("--dnf-repos", "--dnf-packages", "--fedora-image"):
        try:
            fedora_arguments(root, ci, option)
        except (OSError, ValueError, TypeError) as exc:
            viol.append(f"{option}: {exc}")
    fedora = ci.get("fedora")
    want = fedora.get("image") if isinstance(fedora, dict) else None
    if want:
        wf = os.path.join(root, ".github/workflows/mios-ci.yml")
        body = Path(wf).read_text(encoding="utf-8") if os.path.isfile(wf) else ""
        job = re.search(r"^  drift-gate:\n(.*?)(?=^  \S|\Z)", body, re.M | re.S)
        got = re.search(r"^    container:\s*\n\s+image:\s*(\S+)",
                        job.group(1), re.M) if job else None
        if not got or got.group(1).strip("'\"") != want:
            viol.append("drift-gate container differs from [ci.fedora].image")
    # main() reads [ci] from this same file, so on the real gate path it exists;
    # only a unit fixture handing cmd_check a bare [ci] dict lacks it.
    if os.path.isfile(os.path.join(root, "usr/share/mios/mios.toml")):
        viol.extend(devcontainer_check(root))

    if suite_timeout(ci) is None:
        viol.append("[ci].suite_timeout_s must be a positive integer -- without it"
                    " one hung suite wedges the whole tier")

    ceiling = ci.get("max_exempt_suites")
    if ceiling is None:
        viol.append("[ci] has no max_exempt_suites -- an absent ceiling is a broken"
                    " ratchet, not an open one")
    elif len(exempt) > int(ceiling):
        viol.append(f"exempt suites {len(exempt)} > ceiling {ceiling}")

    print("\n".join(viol))
    if not viol:
        print(f"[ci-suites] {len(reg)} suite(s) registered across "
              f"{len(set(reg.values()))} tier(s); {len(exempt)}/{ceiling} exempt",
              file=sys.stderr)
    return 1 if viol else 0

# The dev container IS the MiOS image plus container wiring, so anything that
# would make it a different image is refused: a second stage, a FROM other than
# the ARG, an ARG default other than [image].ref, a file brought in from the
# build context, or a RUN that installs a package, toolchain or payload. A
# component the devcontainer lacks belongs in the OS pipeline instead.
DEV_CONTAINERFILE = ".devcontainer/Containerfile"
_DEV_INSTALL = re.compile(
    r"\b(?:dnf5?|microdnf|yum|apt-get|apt|apk|zypper|rpm-ostree|flatpak)\s+(?:-\S+\s+)*"
    r"(?:install|in|reinstall|upgrade|update|groupinstall|add)\b"
    r"|\brpm\s+-[A-Za-z]*[iUF]"
    r"|\bpip[0-9.]*\s+install\b|-m\s+pip\s+install\b|\b(?:pipx|uv\s+tool|uv\s+pip)\s+install\b"
    r"|\b(?:npm|pnpm|yarn|bun)\s+(?:install|i|ci|add)\b"
    r"|\brustup(?:-init)?\b|\bcargo\s+(?:install|build)\b"
    r"|\b(?:curl|wget)\b|\bgit\s+clone\b"
    r"|\bmios-mcp-server\b|\b[0-9]{2}-[a-z0-9-]+\.sh\b")


def devcontainer_violations(text: str, image_ref: str) -> list:
    """Every way `text` (a dev Containerfile) stops being [image].ref plus wiring."""
    logical, buf = [], ""
    for raw in text.splitlines():
        line = raw.strip()
        if not buf and (not line or line.startswith("#")):
            continue
        if buf and line.startswith("#"):
            continue  # a comment inside a continued instruction
        if line.endswith("\\"):
            buf += line[:-1] + " "
            continue
        logical.append(buf + line)
        buf = ""
    if buf:
        logical.append(buf)
    viol = []
    froms = [i for i, ln in enumerate(logical) if ln.split(None, 1)[0].upper() == "FROM"]
    if len(froms) != 1:
        viol.append(f"devcontainer Containerfile has {len(froms)} FROM lines; it must be one stage, FROM ${{MIOS_IMAGE_REF}}")
    elif logical[froms[0]].split()[1:] != ["${MIOS_IMAGE_REF}"]:
        viol.append(f"devcontainer {logical[froms[0]]!r} is not FROM ${{MIOS_IMAGE_REF}}")
    first = froms[0] if froms else len(logical)
    args = [ln for ln in logical[:first] if re.match(r"ARG\s+MIOS_IMAGE_REF(?:=|\s|$)", ln, re.I)]
    default = args[0].split("=", 1)[1].strip().strip("'\"") if args and "=" in args[0] else None
    if default != image_ref:
        viol.append(f"devcontainer ARG MIOS_IMAGE_REF default {default!r} differs from [image].ref {image_ref!r}")
    for ln in logical:
        op = ln.split(None, 1)[0].upper()
        if op in ("COPY", "ADD"):
            viol.append(f"devcontainer brings files into the image ({ln[:60]!r}); it adds only wiring")
        elif op == "RUN":
            hit = _DEV_INSTALL.search(ln)
            if hit:
                viol.append(f"devcontainer RUN installs {hit.group(0)!r}; install it in the OS image pipeline")
    return viol


def devcontainer_check(root: str) -> list:
    """The repo's dev Containerfile against the SSOT, and the local build's layering."""
    with open(os.path.join(root, "usr/share/mios/mios.toml"), "rb") as fh:
        data = tomllib.load(fh)
    ref = (data.get("image") or {}).get("ref")
    if not ref:
        return ["[image].ref is empty -- the dev container has no image to be"]
    path = os.path.join(root, DEV_CONTAINERFILE)
    if not os.path.isfile(path):
        return [f"{DEV_CONTAINERFILE} is missing"]
    viol = devcontainer_violations(Path(path).read_text(encoding="utf-8"), ref)
    images = (data.get("build") or {}).get("images") or {}
    dev_arg = ((images.get("devcontainer") or {}).get("build_args") or {}).get("MIOS_IMAGE_REF")
    if dev_arg != "build.images.os" or not (images.get("os") or {}).get("tag_key"):
        viol.append(f"[build.images.devcontainer].build_args.MIOS_IMAGE_REF {dev_arg!r} does not name the"
                    f" os target (build.images.os, which carries its tag): a local dev build would not"
                    f" layer on the image it built")
    return viol


def suite_timeout(ci: dict):
    """[ci].suite_timeout_s as a positive int, else None (bool is not a count)."""
    v = ci.get("suite_timeout_s")
    return v if isinstance(v, int) and not isinstance(v, bool) and v > 0 else None

def main(argv: list) -> int:
    root = _root()
    try:
        ci = _load(root)
    except (OSError, ValueError) as exc:
        print(f"mios.toml unreadable: {exc}", file=sys.stderr)
        return 1
    if not ci:
        print("mios.toml has no [ci] table -- the suite registry is the only"
              " thing that keeps the publishers running the same set")
        return 1
    if "--check" in argv:
        return cmd_check(root, ci)
    if "--python-packages" in argv:
        py = ci.get("python") or {}
        args = []
        for req in (py.get("requirements") or ()):
            args += ["-r", req]
        args += list(py.get("packages") or ())
        print(" ".join(args))
        return 0
    for option in ("--dnf-repos", "--dnf-packages", "--fedora-image"):
        if option in argv:
            try:
                args = fedora_arguments(root, ci, option)
            except (OSError, ValueError, TypeError) as exc:
                print(f"{option}: {exc}", file=sys.stderr)
                return 1
            print(" ".join(args))
            return 0
    if "--suite-timeout" in argv:
        t = suite_timeout(ci)
        if t is None:
            print("[ci].suite_timeout_s is absent or not a positive integer", file=sys.stderr)
            return 1
        print(t)
        return 0
    if "--tool-skips" in argv:
        print("\n".join(sorted(ci.get("tool_skips") or {})))
        return 0
    for i, a in enumerate(argv):
        if a == "--tier" and i + 1 < len(argv):
            return cmd_list(root, ci, argv[i + 1])
        if a.startswith("--tier="):
            return cmd_list(root, ci, a.split("=", 1)[1])
    print("usage: ci-suites.py --tier <name> | --check | --python-packages | --dnf-repos | --dnf-packages | --fedora-image | --tool-skips | --suite-timeout",
          file=sys.stderr)
    return 2

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/bin/bash
# AI-hint: Shared OVMF firmware library + discovery UI: finds OVMF CODE/VARS pairs under /usr/share, proves Secure Boot capability and enrollment from content (qemu descriptors, bounded EDK2 varstore parser) and rejects incompatible pairs.
# AI-functions: find_vars_for_code, ovmf_share_root, ovmf_fwdesc_dir, ovmf_file_format, ovmf_descriptor_pairs, ovmf_vars_enrollment, ovmf_sb_capability, ovmf_pair_status, ovmf_enroll_with_virt_fw_vars, ovmf_install_verified_vars, ovmf_repair_menu
#
# Incompatible = a cross-build, size or format mismatch. Sourced by tools/get-secureboot-ovmf.sh,
# tools/check-ovmf-enrollment.sh and tools/fix-ovmf-enrollment.sh; run directly for the discovery report.
# Upstream contracts: QEMU docs/interop/firmware.json and EDK2
# MdeModulePkg/Include/Guid/VariableFormat.h, MdePkg/Include/Guid/ImageAuthentication.h.
#   - Fedora ships /usr/share/edk2/ovmf/{OVMF_CODE[.secboot].fd, OVMF_VARS[.secboot].fd, *_4M.qcow2}
#     Enrollment varies by package and template; every candidate is content-checked. /usr/share/OVMF/* are compat symlinks. Gerd Hoffmann's RPMs
#     use /usr/share/edk2/x64 with .4m. names and ship NO enrolled VARS.
#   - /usr/share/qemu/firmware/*.json descriptors are the authoritative capability+pairing
#     source: each descriptor pairs exactly one CODE with one VARS template and lists
#     features ("secure-boot", "enrolled-keys"). libvirt firmware autoselection reads these.
#   - libvirt NEVER enrolls keys itself; the enrolled-keys feature selects a pre-enrolled
#     template. Enrollment is created by virt-firmware: virt-fw-vars --enroll-redhat --secure-boot.
#   - A descriptor identifies compatible CODE/VARS and each image format. Both image
#     structures are validated; filenames and directories do not prove compatible builds.
#
# Testability (scoped test seams, not MiOS settings): OVMF_SHARE_ROOT overrides the /usr/share root (default /usr/share) and
# OVMF_FWDESC_DIR overrides the descriptor directory. No script in this family ever
# writes to /var/lib/libvirt/qemu/nvram or overwrites an existing firmware file.

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
BOLD='\033[1m'
NC='\033[0m'

# ---------------------------------------------------------------------------
# Library (sourced by get-secureboot-ovmf.sh / check-ovmf-enrollment.sh /
# fix-ovmf-enrollment.sh). Everything below is pure until ovmf_main runs.
# ---------------------------------------------------------------------------

ovmf_share_root() {
    echo "${OVMF_SHARE_ROOT:-/usr/share}"
}

ovmf_fwdesc_dir() {
    echo "${OVMF_FWDESC_DIR:-$(ovmf_share_root)/qemu/firmware}"
}

ovmf_human_size() {
    local bytes=$1
    if command -v numfmt &>/dev/null; then
        numfmt --to=iec-i --suffix=B "$bytes"
    else
        echo "${bytes}B"
    fi
}

ovmf_file_size() {
    stat -c%s "$1" 2>/dev/null || stat -f%z "$1" 2>/dev/null || echo 0
}

# Print "raw", "qcow2" or "unknown" for a firmware file (magic sniff, no names).
ovmf_file_format() {
    local f=$1 magic
    [ -f "$f" ] || { echo unknown; return; }
    magic=$(head -c 4 -- "$f" 2>/dev/null | od -An -tx1 | tr -d ' \n')
    case "$magic" in
        514649fb) echo qcow2 ;;   # QFI\xfb
        *)        echo raw ;;
    esac
}

# Enumerate split-flash firmware descriptors (qemu/libvirt firmware autoselection DB).
# Output TSV per descriptor: json_path \t code \t vars \t features \t format \t desc
ovmf_descriptor_pairs() {
    local desc_dir
    desc_dir=$(ovmf_fwdesc_dir)
    [ -d "$desc_dir" ] || return 0
    python3 - "$desc_dir" <<'PYEOF' 2>/dev/null || true
import glob, json, sys
for p in sorted(glob.glob(sys.argv[1] + '/*.json')):
    try:
        d = json.load(open(p, encoding='utf-8'))
    except Exception:
        continue
    if not isinstance(d, dict):
        continue
    m = d.get('mapping', {})
    if not isinstance(m, dict):
        continue
    if m.get('device') != 'flash' or m.get('mode', 'split') != 'split':
        continue
    exe = m.get('executable', {}) or {}
    nv = m.get('nvram-template', {}) or {}
    if not isinstance(exe, dict) or not isinstance(nv, dict):
        continue
    code = exe.get('filename', '')
    vars_ = nv.get('filename', '')
    if not code or not vars_:
        continue
    formats = (exe.get('format'), nv.get('format'))
    features = d.get('features', [])
    if not all(fmt in ('raw', 'qcow2') for fmt in formats) or not isinstance(features, list) or not all(isinstance(item, str) and item and all(c.isalnum() or c in '-_' for c in item) for item in features):
        continue
    fields = [p, code, vars_, d.get('description', '')]
    if not all(isinstance(item, str) and not any(c in item for c in '\t\r\n') for item in fields):
        continue
    feats = ','.join(sorted(features)) or '-'
    print('\t'.join([p, code, vars_, feats, ':'.join(formats), d.get('description', '') or '-']))
PYEOF
}

# Determine the enrollment state of a VARS file from its CONTENT.
# Prints one line: "ENROLLED <vars...>" | "BLANK" | "UNKNOWN <reason>"
# Uses the bounded EDK2 parser to validate live state, namespace, payload,
# and Secure Boot enable intent. NEVER infers enrollment from the filename.
ovmf_vars_enrollment() {
    local f=$1 tmp="" parsed
    if [ ! -f "$f" ]; then
        echo "UNKNOWN not a file: $f"
        return 1
    fi
    # qcow2 varstores must be validated and converted read-only before parsing.
    if [ "$(ovmf_file_format "$f")" = "qcow2" ]; then
        ovmf_validate_image "$f" qcow2 >/dev/null || { echo "UNKNOWN qcow2 image is unverified"; return 1; }
        if command -v qemu-img &>/dev/null; then
            tmp=$(mktemp /tmp/ovmf-vars-XXXXXX.raw) || { echo "UNKNOWN mktemp failed"; return 1; }
            if ! qemu-img convert -f qcow2 -O raw "$f" "$tmp" 2>/dev/null; then
                rm -f "$tmp"; echo "UNKNOWN qcow2 convert failed: $f"; return 1
            fi
            parsed=$(ovmf_vars_enrollment_raw "$tmp")
            rm -f "$tmp"
            echo "$parsed"
            case "$parsed" in ENROLLED*|BLANK*) return 0 ;; *) return 1 ;; esac
        else
            echo "UNKNOWN qcow2 varstore and qemu-img not installed: $f"
            return 1
        fi
    fi
    parsed=$(ovmf_vars_enrollment_raw "$f")
    echo "$parsed"
    case "$parsed" in ENROLLED*|BLANK*) return 0 ;; *) return 1 ;; esac
}

ovmf_vars_enrollment_raw() {
    # Human-readable virt-fw-vars output lists names and cannot prove that a
    # variable is live, correctly namespaced, nonempty, and structurally valid.
    # One parser owns this decision; a tool's successful print is no fallback.
    ovmf_parse_varstore_python "$1"
}

# Bounded EDK2 parser for authenticated and standard GUID variable stores.
# Enrollment and enable intent are offline evidence; runtime enforcement is not measured.
ovmf_parse_varstore_python() {
    if ! command -v python3 &>/dev/null; then
        echo "UNKNOWN python3 not available for varstore parsing"
        return 1
    fi
    python3 - "$1" <<'PYEOF'
import struct, sys, uuid

def report(state, detail):
    print(f"{state} {detail}")
    sys.exit(0 if state in ("ENROLLED", "BLANK") else 1)

def guid(value):
    return uuid.UUID(value).bytes_le

try:
    with open(sys.argv[1], 'rb') as stream:
        d = stream.read(64 * 1024 * 1024 + 1)
except OSError as error:
    report('UNKNOWN', f'unreadable: {error}')
if len(d) < 72 or len(d) > 64 * 1024 * 1024 or d[40:44] != b'_FVH':
    report('UNKNOWN', 'invalid or unsupported firmware-volume image')
fvlen, = struct.unpack_from('<Q', d, 32)
hlen, = struct.unpack_from('<H', d, 48)
if hlen < 72 or hlen % 2 or not hlen + 28 <= fvlen <= len(d):
    report('UNKNOWN', 'truncated firmware volume or invalid header length')
if d[54:56] != b'\x00\x02' or sum(struct.unpack_from('<' + 'H' * (hlen // 2), d)) & 0xffff:
    report('UNKNOWN', 'invalid firmware-volume revision/checksum')
total = 0
for block_at in range(56, hlen-7, 8):
    count, block_size = struct.unpack_from('<II', d, block_at)
    if count == block_size == 0:
        break
    if not count or not block_size:
        report('UNKNOWN', 'invalid firmware block map')
    total += count * block_size
else:
    report('UNKNOWN', 'unterminated firmware block map')
if total != fvlen:
    report('UNKNOWN', 'firmware block map disagrees with volume length')
size, = struct.unpack_from('<I', d, hlen + 16)
end = hlen + size
if size < 28 or end > fvlen or d[hlen+20:hlen+22] != b'\x5a\xfe':
    report('UNKNOWN', 'truncated, unformatted, or unhealthy variable store')
store_guid = d[hlen:hlen+16]
if store_guid == guid('aaf32c78-947b-439a-a180-2e144ec37792'):
    hdr, sizes_at, vendor_at = 60, 36, 44
elif store_guid == guid('ddcf3616-3275-4164-98b6-fe85707ffe7d'):
    hdr, sizes_at, vendor_at = 32, 8, 16
else:
    report('UNKNOWN', 'unsupported variable-store signature')
p = (hlen + 28 + 3) & ~3
active = {}
while p < end:
    if all(byte == 0xff for byte in d[p:end]):
        break
    if p + hdr > end or struct.unpack_from('<H', d, p)[0] != 0x55aa:
        report('UNKNOWN', f'truncated or invalid variable header at {p:#x}')
    state = d[p+2]
    ns, ds = struct.unpack_from('<II', d, p + sizes_at)
    data_at = p + hdr + ns
    next_p = (data_at + ds + 3) & ~3
    if ns < 2 or ns % 2 or ns > 4096 or ds > 262144 or data_at + ds > end:
        report('UNKNOWN', f'invalid or truncated variable sizes at {p:#x}')
    name_bytes = d[p+hdr:data_at]
    try:
        if name_bytes[-2:] != b'\x00\x00':
            raise ValueError('missing terminator')
        name = name_bytes[:-2].decode('utf-16-le')
        if '\x00' in name:
            raise ValueError('embedded terminator')
    except (UnicodeDecodeError, ValueError):
        report('UNKNOWN', f'invalid variable name at {p:#x}')
    if state == 0x3f:  # VAR_ADDED; obsolete/header-only records are not keys.
        key = (name, d[p+vendor_at:p+vendor_at+16])
        if key in active:
            report('UNKNOWN', f'ambiguous duplicate live variable {name}')
        active[key] = (d[data_at:data_at+ds], struct.unpack_from('<I', d, p+4)[0])
    elif state not in (0x3c, 0x3d, 0x3e, 0x7f):
        report('UNKNOWN', f'unsupported variable state {state:#x}')
    p = next_p

global_guid = guid('8be4df61-93ca-11d2-aa0d-00e098032b8c')
db_guid = guid('d719b2cb-3d3a-4596-a3bc-dad00e67656f')
enable_guid = guid('f0a30bc7-af08-4556-99c4-001009c93a44')
required = [('PK', global_guid), ('KEK', global_guid), ('db', db_guid)]
seen = [name for name, vendor in required if (name, vendor) in active]
if not seen:
    report('BLANK', 'no live PK/KEK/db in their UEFI namespaces')
if len(seen) != len(required):
    report('UNKNOWN', 'incomplete live PK/KEK/db enrollment: ' + ','.join(seen))

# EFI_SIGNATURE_LIST: strict bounds, complete nonempty entries, supported
# signature types. Certificate parsing proves DER content, not trust policy.
def validate_signatures(name, data):
    offset, entries = 0, 0
    rsa = guid('3c5766e8-269c-4e34-aa14-ed776e85b3b6')
    x509 = guid('a5c059a1-94e4-4aa7-87b5-ab155c2bf072')
    sha256 = guid('c1c41626-504c-4092-aca9-41f936934328')
    while offset < len(data):
        if offset + 28 > len(data):
            report('UNKNOWN', f'{name} signature list header truncated')
        kind = data[offset:offset+16]
        size, header, signature = struct.unpack_from('<III', data, offset+16)
        count_bytes = size - 28 - header
        if size < 28 or header != 0 or signature <= 16 or count_bytes <= 0 or count_bytes % signature or offset + size > len(data):
            report('UNKNOWN', f'{name} signature list size invalid')
        if kind not in (rsa, x509, sha256) or (name == 'PK' and kind not in (rsa, x509)):
            report('UNKNOWN', f'{name} unsupported signature type')
        for entry in range(offset+28, offset+size, signature):
            payload = data[entry+16:entry+signature]
            if kind == rsa and (len(payload) != 256 or not any(payload) or not payload[-1] & 1):
                report('UNKNOWN', f'{name} invalid RSA2048 entry')
            if kind == sha256 and len(payload) != 32:
                report('UNKNOWN', f'{name} invalid SHA256 entry')
            if kind == x509:
                try:
                    from cryptography.x509 import load_der_x509_certificate
                    load_der_x509_certificate(payload)
                except (ImportError, ValueError):
                    report('UNKNOWN', f'{name} certificate invalid or cryptography unavailable')
            entries += 1
        offset += size
    if not entries or (name == 'PK' and entries != 1):
        report('UNKNOWN', f'{name} must contain valid signature entries')

for name, vendor in required:
    data, attrs = active[(name, vendor)]
    if not data or attrs & 0x27 != 0x27:
        report('UNKNOWN', f'{name} empty or missing authenticated NV/BS/RT attributes')
    validate_signatures(name, data)
if ('dbx', db_guid) in active:
    data, attrs = active[('dbx', db_guid)]
    if data:
        validate_signatures('dbx', data)
if active.get(('SetupMode', global_guid), (b'\x00', 0))[0] != b'\x00':
    report('UNKNOWN', 'SetupMode contradicts enrollment')
enabled = active.get(('SecureBootEnable', enable_guid), active.get(('SecureBoot', global_guid), (None, 0)))[0]
if enabled != b'\x01':
    report('UNKNOWN', 'Secure Boot enable intent absent or disabled')
report('ENROLLED', 'live authenticated PK+KEK+db signature lists and enable intent verified; runtime enforcement is not measured')
PYEOF
}

# Secure Boot CAPABILITY of a CODE image (distinct from enrollment!).
# Prints: "yes <evidence>" | "no <evidence>" | "unknown <reason>"
# Capability requires a package descriptor plus a validated firmware image.
# A name or firmware-volume signature alone cannot identify compiled features.
ovmf_validate_image() {
    local image=$1 expected=$2 raw=$1 work="" info
    command -v python3 &>/dev/null || { echo "REJECT PYTHON_MISSING"; return 1; }
    [ -f "$image" ] || { echo "REJECT IMAGE_MISSING"; return 1; }
    [ "$(ovmf_file_format "$image")" = "$expected" ] || { echo "REJECT FORMAT_MISMATCH"; return 1; }
    if [ "$expected" = qcow2 ]; then
        command -v qemu-img &>/dev/null || { echo "REJECT QCOW2_UNVERIFIED qemu-img missing"; return 1; }
        info=$(qemu-img info --output=json "$image" 2>/dev/null) || { echo "REJECT QCOW2_INVALID"; return 1; }
        if ! python3 -c 'import json,sys; d=json.load(sys.stdin); sys.exit(0 if d.get("format")=="qcow2" and 0<d.get("virtual-size",0)<=64*1024*1024 and not d.get("backing-filename") else 1)' <<< "$info"; then
            echo "REJECT QCOW2_BACKING_OR_FORMAT"; return 1
        fi
        qemu-img check -f qcow2 "$image" >/dev/null 2>&1 || { echo "REJECT QCOW2_METADATA"; return 1; }
        work=$(mktemp /tmp/ovmf-image-XXXXXX.raw) || return 1
        qemu-img convert -f qcow2 -O raw "$image" "$work" >/dev/null 2>&1 || { rm -f -- "$work"; echo "REJECT QCOW2_CONVERT"; return 1; }
        raw=$work
    fi
    local result rc
    result=$(python3 - "$raw" <<'PYEOF'
import struct, sys
try:
    with open(sys.argv[1], 'rb') as stream:
        d=stream.read(64 * 1024 * 1024 + 1)
    if not 72 <= len(d) <= 64 * 1024 * 1024 or d[40:44] != b'_FVH':
        raise ValueError('invalid firmware-volume signature/size')
    length,=struct.unpack_from('<Q',d,32)
    header,=struct.unpack_from('<H',d,48)
    if not 72 <= header <= length <= len(d) or header % 2 or d[54:56] != b'\x00\x02':
        raise ValueError('invalid firmware-volume bounds/revision')
    if sum(struct.unpack_from('<'+'H'*(header//2),d)) & 0xffff:
        raise ValueError('invalid firmware-volume checksum')
    total=0
    for p in range(56,header-7,8):
        count,size=struct.unpack_from('<II',d,p)
        if count==size==0:
            break
        if not count or not size:
            raise ValueError('invalid block map')
        total += count * size
    else:
        raise ValueError('unterminated block map')
    if total != length:
        raise ValueError('block map disagrees with volume length')
    print('OK verified firmware-volume header and block map')
except (OSError, ValueError, struct.error) as error:
    print(f'REJECT INVALID_FIRMWARE {error}')
    sys.exit(1)
PYEOF
)
    rc=$?
    [ -z "$work" ] || rm -f -- "$work"
    echo "${result:-REJECT IMAGE_UNVERIFIABLE}"
    return "$rc"
}

ovmf_sb_capability() {
    local code=$1 json c vars feats fmt desc proof
    [ -f "$code" ] || { echo "unknown file missing: $code"; return 1; }
    while IFS=$'\t' read -r json c vars feats fmt desc; do
        [ "$c" = "$code" ] || continue
        proof=$(ovmf_validate_image "$code" "${fmt%%:*}") || { echo "unknown $proof"; return 1; }
        case ",$feats," in
            *,secure-boot,*) echo "yes validated image and descriptor $(basename "$json") lists secure-boot"; return 0 ;;
            *) echo "no validated descriptor $(basename "$json") lists no secure-boot feature"; return 0 ;;
        esac
    done < <(ovmf_descriptor_pairs)
    echo "unknown no validated firmware descriptor proves Secure Boot capability"
    return 1
}

# Compatibility of a CODE/VARS pair. Prints "OK <evidence>" or "REJECT <named reason>".
# A validated descriptor identifies the exact compatible pair and the format
# of each pflash image; CODE and VARS may legitimately use different formats.
# Both image headers and the VARS content must pass verification. A directory
# or a size/name class does not prove a common build.
ovmf_pair_status() {
    local code=$1 vars=$2 json c v feats fmt desc proof state
    [ -f "$code" ] || { echo "REJECT CODE_MISSING $code"; return 1; }
    [ -f "$vars" ] || { echo "REJECT VARS_MISSING $vars"; return 1; }
    while IFS=$'\t' read -r json c v feats fmt desc; do
        [ "$c" = "$code" ] && [ "$v" = "$vars" ] || continue
        proof=$(ovmf_validate_image "$code" "${fmt%%:*}") || { echo "$proof CODE"; return 1; }
        proof=$(ovmf_validate_image "$vars" "${fmt##*:}") || { echo "$proof VARS"; return 1; }
        state=$(ovmf_vars_enrollment "$vars") || { echo "REJECT VARSTORE_UNVERIFIED $state"; return 1; }
        case ",$feats," in
            *,enrolled-keys,*) case "$state" in ENROLLED*) ;; *) echo "REJECT DESCRIPTOR_ENROLLMENT_MISMATCH $state"; return 1 ;; esac ;;
        esac
        echo "OK validated descriptor $(basename "$json") pairs content-verified $fmt CODE+VARS"
        return 0
    done < <(ovmf_descriptor_pairs)
    echo "REJECT UNPROVEN_PAIR no validated descriptor pairs this CODE+VARS; directory and filename do not prove one build"
    return 1
}

# Display-only size class of a firmware filename: "4m" or "2m" (kraxel ".4m." lowercase,
# Fedora "_4M." uppercase). This hint is never accepted as pairing proof.
ovmf_size_class() {
    local b
    b=$(basename "$1")
    case "$b" in
        *4[mM].fd|*4[mM].qcow2|*[._]4[mM][._]*) echo 4m ;;
        *)                                     echo 2m ;;
    esac
}

# Public pairing helper (kept for callers/metadata): print the best compatible
# VARS for a CODE file, or nothing. Never falls back to an arbitrary VARS file:
# only name-family candidates that PASS ovmf_pair_status qualify.
find_vars_for_code() {
    local code_path=$1 dir filename candidate vars_path status
    [ -f "$code_path" ] || return 1
    dir=$(dirname "$code_path")
    filename=$(basename "$code_path")
    local json c vars feats fmt desc
    while IFS=$'\t' read -r json c vars feats fmt desc; do
        [ "$c" = "$code_path" ] || continue
        ovmf_pair_status "$code_path" "$vars" >/dev/null || continue
        echo "$vars"; return 0
    done < <(ovmf_descriptor_pairs)
    # Name-family candidates, most-specific first: direct CODE->VARS rename
    # (keeps .secboot/_4M/.4m/.qcow2 markers), then the blank-VARS family of
    # the same build (secboot CODE boots fine on the blank same-build VARS;
    # enrollment is a separate, content-verified question).
    local -a candidates=(
        "${filename/OVMF_CODE/OVMF_VARS}"
    )
    case "$filename" in
        *secboot*) candidates+=("${filename//.secboot/}") ;;
    esac
    for candidate in "${candidates[@]}"; do
        [ -n "$candidate" ] || continue
        [ "$candidate" = "$filename" ] && continue
        vars_path="$dir/$candidate"
        [ -f "$vars_path" ] || continue
        status=$(ovmf_pair_status "$code_path" "$vars_path")
        case "$status" in
            OK*) echo "$vars_path"; return 0 ;;
        esac
    done
    return 1
}

# Find the best verified-enrolled VARS on the system (descriptor-backed first).
# Prints: "<path>\t<evidence>" or nothing.
ovmf_find_enrolled_vars() {
    local json code vars feats state
    while IFS=$'\t' read -r json code vars feats _fmt _desc; do
        case ",$feats," in
            *,enrolled-keys,*)
                ovmf_pair_status "$code" "$vars" >/dev/null || continue
                state=$(ovmf_vars_enrollment "$vars")
                case "$state" in
                    ENROLLED*)
                        echo -e "$vars\tdescriptor $(basename "$json") (enrolled-keys feature) and content verified"
                        return 0
                        ;;
                esac
                ;;
        esac
    done < <(ovmf_descriptor_pairs)
    local f state
    while IFS= read -r f; do
        state=$(ovmf_vars_enrollment "$f")
        case "$state" in
            ENROLLED*) echo -e "$f\t$state"; return 0 ;;
        esac
    done < <(find "$(ovmf_share_root)/edk2" "$(ovmf_share_root)/OVMF" -type f \( -name 'OVMF_VARS*.fd' -o -name 'OVMF_VARS*.qcow2' \) 2>/dev/null | sort)
    return 1
}

# Enroll a COPY of a blank VARS template with virt-firmware (vendor/MS keys).
# Never modifies the template in place; output goes to a new file.
ovmf_enroll_with_virt_fw_vars() {
    local template=$1 out=$2 work state
    command -v virt-fw-vars &>/dev/null || { echo "virt-fw-vars not installed" >&2; return 1; }
    [ -f "$template" ] || { echo "template missing: $template" >&2; return 1; }
    [ ! -e "$out" ] && [ ! -L "$out" ] || { echo "refusing to overwrite $out" >&2; return 1; }
    case "$(ovmf_vars_enrollment "$template")" in BLANK*) ;; *) echo "template must be verified blank" >&2; return 1 ;; esac
    work=$(mktemp "$(dirname "$out")/.ovmf-enroll-XXXXXX") || return 1
    if ! virt-fw-vars --input "$template" --output "$work" --enroll-redhat --secure-boot; then
        rm -f -- "$work"; echo "virt-fw-vars enrollment failed" >&2; return 1
    fi
    state=$(ovmf_vars_enrollment "$work")
    case "$state" in
        ENROLLED*) ;;
        *) rm -f -- "$work"; echo "post-enrollment verification failed: $state" >&2; return 1 ;;
    esac
    # Hard-link publication refuses an output created by a concurrent caller.
    if ! ln -- "$work" "$out"; then rm -f -- "$work"; return 1; fi
    rm -f -- "$work"
}

# Install a VARS file into a target directory after verification, atomically.
# Refuses to overwrite anything, refuses unverified (non-ENROLLED) sources,
# requires validated descriptor pairing when a target CODE is supplied.
ovmf_install_verified_vars() {
    local src=$1 dest_dir=$2 dest_name=$3 code_hint=$4 tmp state
    [ -f "$src" ] || { echo "source missing: $src"; return 1; }
    state=$(ovmf_vars_enrollment "$src")
    case "$state" in
        ENROLLED*) ;;
        *) echo "refusing to install: source varstore is not verified ENROLLED ($state)"; return 1 ;;
    esac
    if [ -n "$code_hint" ]; then
        local pair
        pair=$(ovmf_pair_status "$code_hint" "$src")
        case "$pair" in
            OK*) ;;
            *) echo "refusing to install: $pair"; return 1 ;;
        esac
    fi
    mkdir -p -- "$dest_dir" || return 1
    if [ -e "$dest_dir/$dest_name" ]; then
        echo "refusing to overwrite existing $dest_dir/$dest_name (never replace firmware or NVRAM in place)"
        return 1
    fi
    tmp=$(mktemp "$dest_dir/.ovmf-vars-XXXXXX") || return 1
    if ! cp -- "$src" "$tmp"; then rm -f "$tmp"; return 1; fi
    chmod 644 "$tmp" || { rm -f -- "$tmp"; return 1; }
    # Validate the actual copy before publication; copying is not proof that
    # its source remained unchanged. Never publish a failed candidate.
    case "$(ovmf_vars_enrollment "$tmp")" in
        ENROLLED*) ;;
        *) rm -f -- "$tmp"; echo "copied candidate failed verification"; return 1 ;;
    esac
    if ! ln -- "$tmp" "$dest_dir/$dest_name"; then rm -f -- "$tmp"; return 1; fi
    rm -f -- "$tmp"
    echo "installed verified enrolled varstore: $dest_dir/$dest_name"
    return 0
}

# Derive the conventional enrolled-VARS filename from a blank template name:
# OVMF_VARS.4m.fd -> OVMF_VARS.secboot.4m.fd, OVMF_VARS_4M.qcow2 ->
# OVMF_VARS_4M.secboot.qcow2, OVMF_VARS.fd -> OVMF_VARS.secboot.fd.
ovmf_derive_enrolled_name() {
    local b
    b=$(basename "$1")
    case "$b" in
        *secboot*) echo "$b" ;;
        OVMF_VARS.fd) echo "OVMF_VARS.secboot.fd" ;;
        *VARS*.fd) echo "${b/VARS./VARS.secboot.}" ;;
        *VARS*.qcow2) echo "${b/VARS_4M./VARS_4M.secboot.}" ;;
        *) echo "OVMF_VARS.secboot.mios.fd" ;;
    esac
}

# Interactive repair menu shared by get-secureboot-ovmf.sh and
# fix-ovmf-enrollment.sh (root install). No hardcoded download URLs: the only
# network path is the distro package manager (dnf download), and every
# artifact passes content + pair verification before anything is written.
# Never overwrites an existing file; never touches /var/lib/libvirt/qemu/nvram.
ovmf_repair_menu() {
    local target_dir=${1:-$(ovmf_share_root)/edk2/x64}
    local blank_template choice f code_hint

    # If the target directory already has a CODE image, every candidate VARS
    # must pair with it (named rejection otherwise).
    code_hint=""
    for f in "$target_dir"/*CODE*; do
        [ -f "$f" ] && { code_hint="$f"; break; }
    done

    echo -e "${BOLD}Repair options (nothing is modified without your choice):${NC}\n"
    echo -e "  ${CYAN}1)${NC} Copy a content-verified enrolled VARS already on this system (dnf install edk2-ovmf provides one)"
    echo -e "  ${CYAN}2)${NC} Enroll a fresh copy of the local same-build blank VARS with virt-fw-vars (offline, verified)"
    echo -e "  ${CYAN}3)${NC} Fetch current edk2-ovmf via 'dnf download', extract, verify, install (repo-tracked, no stale URLs)"
    echo -e "  ${CYAN}4)${NC} Print guidance only (libvirt autoselection facts + manual steps)"
    echo
    read -r -p "Choose option (1-4): " choice
    echo
    case "$choice" in
        1)
            local picked="" ev
            # Prefer an enrolled source that PASSES the pair check with the
            # target CODE; otherwise report the named rejection.
            while IFS= read -r f; do
                [ -f "$f" ] || continue
                if [ -n "$code_hint" ]; then
                    ev=$(ovmf_pair_status "$code_hint" "$f")
                    case "$ev" in OK*) ;; *) continue ;; esac
                fi
                case "$(ovmf_vars_enrollment "$f")" in
                    ENROLLED*) picked="$f"; break ;;
                esac
            done < <(find "$(ovmf_share_root)/edk2" "$(ovmf_share_root)/OVMF" -type f \( -name '*VARS*.fd' -o -name '*VARS*.qcow2' \) 2>/dev/null | sort)
            if [ -n "$picked" ]; then
                echo -e "${GREEN}[ok]${NC} Verified+pair-compatible source: $picked"
                ovmf_install_verified_vars "$picked" "$target_dir" "$(ovmf_derive_enrolled_name "$picked")" "$code_hint"
                return $?
            fi
            echo -e "${RED}[x] No content-verified enrolled VARS that is pair-compatible with this layout.${NC}"
            echo -e "${YELLOW}Try option 2 (enrolls from the local same-build template) or: sudo dnf install edk2-ovmf${NC}"
            return 1
            ;;
        2)
            blank_template=""
            for f in "$target_dir"/OVMF_VARS*.fd "$target_dir"/OVMF_VARS*.qcow2; do
                [ -f "$f" ] || continue
                case "$(basename "$f")" in *secboot*) continue ;; esac
                blank_template="$f"; break
            done
            if [ -z "$blank_template" ]; then
                echo -e "${RED}[x] No blank VARS template in $target_dir to enroll from (install edk2-ovmf first).${NC}"
                return 1
            fi
            case "$(ovmf_vars_enrollment "$blank_template")" in BLANK*) ;; *) echo "Template not verified blank"; return 1 ;; esac
            if [ -n "$code_hint" ]; then
                ovmf_pair_status "$code_hint" "$blank_template" >/dev/null || { echo "Template is not paired with target CODE"; return 1; }
            fi
            local out_name
            out_name=$(ovmf_derive_enrolled_name "$blank_template")
            if [ -e "$target_dir/$out_name" ]; then
                case "$out_name" in
                    *.fd) out_name="${out_name%.fd}.mios.fd" ;;
                    *.qcow2) out_name="${out_name%.qcow2}.mios.qcow2" ;;
                esac
            fi
            if [ "$(ovmf_file_format "$blank_template")" = "qcow2" ]; then
                # Enroll in raw space, then convert back so the format matches.
                if ! command -v qemu-img &>/dev/null; then
                    echo -e "${RED}[x] qcow2 template needs qemu-img for enrollment${NC}"
                    return 1
                fi
                local workraw
                workraw=$(mktemp /tmp/ovmf-enroll-XXXXXX.fd) || return 1
                qemu-img convert -f qcow2 -O raw "$blank_template" "$workraw" || { rm -f "$workraw"; return 1; }
                if ovmf_enroll_with_virt_fw_vars "$workraw" "$workraw.enrolled"; then
                    local qcow_copy="${workraw}.qcow2" rc
                    if ! qemu-img convert -f raw -O qcow2 "$workraw.enrolled" "$qcow_copy"; then
                        rm -f -- "$workraw" "$workraw.enrolled" "$qcow_copy"; return 1
                    fi
                    # Pair proof came from the untouched blank template above;
                    # the new store is verified after the format round-trip.
                    ovmf_install_verified_vars "$qcow_copy" "$target_dir" "$out_name" ""
                    rc=$?
                    rm -f -- "$workraw" "$workraw.enrolled" "$qcow_copy"
                    return "$rc"
                fi
                rm -f "$workraw" "$workraw.enrolled"
                return 1
            fi
            ovmf_enroll_with_virt_fw_vars "$blank_template" "$target_dir/$out_name" \
                && echo -e "${GREEN}[ok]${NC} Enrolled copy written (content-verified): $target_dir/$out_name" \
                || return 1
            ;;
        3)
            local work found=""
            work=$(mktemp -d /tmp/ovmf-dnf-XXXXXX) || return 1
            if ! command -v dnf &>/dev/null; then
                echo -e "${RED}[x] dnf not available; use option 1 or 2${NC}"
                rm -rf "$work"; return 1
            fi
            if ! ( cd "$work" && dnf download edk2-ovmf ); then
                echo -e "${RED}[x] dnf download edk2-ovmf failed${NC}"
                rm -rf "$work"; return 1
            fi
            if ! ( cd "$work" && rpm2cpio edk2-ovmf-*.rpm | cpio -idm --quiet ); then
                echo -e "${RED}[x] RPM extraction failed (need rpm2cpio + cpio)${NC}"
                rm -rf "$work"; return 1
            fi
            while IFS= read -r f; do
                case "$(ovmf_vars_enrollment "$f")" in ENROLLED*) found="$f"; break ;; esac
            done < <(find "$work" -type f -name 'OVMF_VARS*' 2>/dev/null)
            if [ -z "$found" ]; then
                echo -e "${RED}[x] Downloaded package contains no ENROLLED varstore. Nothing installed.${NC}"
                echo -e "${YELLOW}(Current Fedora ships OVMF_VARS.secboot.fd enrolled; if your release does not, use option 2.)${NC}"
                rm -rf "$work"; return 1
            fi
            ovmf_install_verified_vars "$found" "$target_dir" "$(ovmf_derive_enrolled_name "$found")" "$code_hint"
            local rc=$?
            rm -rf "$work"
            return $rc
            ;;
        4)
            ovmf_print_guidance
            ;;
        *)
            echo -e "${RED}Invalid choice${NC}"
            return 1
            ;;
    esac
}

ovmf_print_guidance() {
    cat <<GUIDE
Facts (upstream-verified):
  * libvirt firmware autoselection NEVER enrolls keys. <feature name='enrolled-keys'/>
    only SELECTS firmware whose varstore template already has keys enrolled.
  * A distribution may provide an enrolled template, for example:
      /usr/share/edk2/ovmf/OVMF_VARS.secboot.fd  (raw, MS keys enrolled)
      plus descriptors /usr/share/qemu/firmware/31-edk2-ovmf-2m-raw-x64-sb-enrolled.json
  * To create an enrolled varstore offline (MiOS ships virt-firmware):
      cp /usr/share/edk2/ovmf/OVMF_VARS.fd /tmp/enrolled_VARS.fd
      virt-fw-vars --input /tmp/enrolled_VARS.fd --output /tmp/enrolled_VARS.fd \\
                   --enroll-redhat --secure-boot
  * Select a descriptor-backed CODE/VARS pair and verify both artifacts.
    A common directory or filename family does not establish compatibility.
  * Never edit /var/lib/libvirt/qemu/nvram/* while the VM is running.
GUIDE
}

# ---------------------------------------------------------------------------
# Discovery UI (direct execution only)
# ---------------------------------------------------------------------------

ovmf_main() {
    local share dir dirs code_file vars_file capability state
    share=$(ovmf_share_root)

    echo -e "${BOLD}${GREEN}════════════════════════════════════════════════════${NC}"
    echo -e "${BOLD}${GREEN}     OVMF Firmware Discovery Tool${NC}"
    echo -e "${BOLD}${GREEN}════════════════════════════════════════════════════${NC}\n"
    echo -e "${BLUE}Scanning $(ovmf_share_root) for OVMF firmware files...${NC}\n"

    local code_files
    code_files=$(find "$share/edk2" "$share/OVMF" -type f \( -name 'OVMF*.fd' -o -name 'OVMF*.qcow2' \) 2>/dev/null | sort)
    if [ -z "$code_files" ]; then
        echo -e "${RED}[x] No OVMF files found under $share!${NC}\n"
        echo -e "${YELLOW}Ensure it is in PACKAGES.md: ${NC}${CYAN}edk2-ovmf${NC}"
        exit 1
    fi

    echo -e "${YELLOW}Found OVMF files:${NC}"
    echo "$code_files" | nl -w2 -s'. '
    echo

    echo -e "\n${CYAN}════════════════════════════════════════════════════${NC}"
    echo -e "${CYAN}Firmware Files by Directory:${NC}"
    echo -e "${CYAN}════════════════════════════════════════════════════${NC}\n"

    dirs=$(echo "$code_files" | xargs -r dirname | sort -u)
    for dir in $dirs; do
        echo -e "${BOLD}$dir${NC}"
        ls -lh "$dir" 2>/dev/null | awk '/OVMF/ {printf "  %s  %s\n", $9, $5}'
        echo
    done

    echo -e "${CYAN}════════════════════════════════════════════════════${NC}"
    echo -e "${CYAN}Firmware descriptor pairs ($(ovmf_fwdesc_dir)):${NC}"
    echo -e "${CYAN}════════════════════════════════════════════════════${NC}\n"
    local desc_count=0
    while IFS=$'\t' read -r json code vars feats fmt desc; do
        desc_count=$((desc_count + 1))
        echo -e "  ${BOLD}$(basename "$json")${NC}"
        echo -e "    CODE: $code ($fmt)"
        echo -e "    VARS: $vars"
        echo -e "    features: ${feats}, $desc"
    done < <(ovmf_descriptor_pairs)
    [ $desc_count -eq 0 ] && echo -e "  ${YELLOW}(no split-flash descriptors found - libvirt autoselection unavailable)${NC}"
    echo

    echo -e "${CYAN}════════════════════════════════════════════════════${NC}"
    echo -e "${CYAN}Verified CODE/VARS Pairs (capability + enrollment from content):${NC}"
    echo -e "${CYAN}════════════════════════════════════════════════════${NC}\n"

    local pair_count=0 rejected=0
    while IFS= read -r code_file; do
        case "$(basename "$code_file")" in *CODE*) ;; *) continue ;; esac
        vars_file=$(find_vars_for_code "$code_file")
        if [ -z "$vars_file" ]; then
            rejected=$((rejected + 1))
            echo -e "${YELLOW}[!]${NC} $(basename "$code_file"): no compatible VARS in $(dirname "$code_file") (no name-family sibling with matching layout)"
            continue
        fi
        pair_count=$((pair_count + 1))
        capability=$(ovmf_sb_capability "$code_file")
        state=$(ovmf_vars_enrollment "$vars_file")
        echo -e "${BOLD}Pair #$pair_count:${NC} $(basename "$code_file") + $(basename "$vars_file")"
        echo -e "  ${YELLOW}CODE:${NC} $code_file ($(ovmf_human_size "$(ovmf_file_size "$code_file")"), $(ovmf_file_format "$code_file"))"
        echo -e "  ${YELLOW}VARS:${NC} $vars_file ($(ovmf_human_size "$(ovmf_file_size "$vars_file")"))"
        case "$capability" in
            yes*) echo -e "  ${GREEN}[ok] Secure Boot capable: $capability${NC}" ;;
            no*)  echo -e "  ${YELLOW}[i] Not Secure Boot: $capability${NC}" ;;
            *)    echo -e "  ${RED}[?] Capability UNVERIFIED: $capability${NC}" ;;
        esac
        case "$state" in
            ENROLLED*) echo -e "  ${GREEN}[ok] Keys ENROLLED (content-verified): $state${NC}" ;;
            BLANK*)    echo -e "  ${YELLOW}[i] Varstore blank (no keys): pair is SB-capable but NOT enrolled${NC}" ;;
            *)         echo -e "  ${RED}[?] Enrollment UNVERIFIED: $state${NC}" ;;
        esac
        echo
    done <<< "$code_files"

    if [ $pair_count -eq 0 ]; then
        echo -e "${RED}[x] No compatible CODE/VARS pair could be verified!${NC}"
        echo -e "${YELLOW}This might indicate:${NC}"
        echo -e "  1. edk2-ovmf package not installed or incomplete"
        echo -e "  2. VARS/CODE images from different builds mixed in one directory"
        echo -e "  3. Package is corrupted"
        echo
        echo -e "${YELLOW}Ensure it is in PACKAGES.md: ${NC}${CYAN}edk2-ovmf${NC}"
        exit 1
    fi

    echo -e "${CYAN}════════════════════════════════════════════════════${NC}"
    echo -e "${CYAN}Recommendation:${NC}"
    echo -e "${CYAN}════════════════════════════════════════════════════${NC}\n"

    local best_code="" best_vars="" best_ev=""
    # Prefer: descriptor-backed secure-boot + enrolled-keys, then secboot-capable
    # with a blank varstore, then anything verified-compatible.
    while IFS=$'\t' read -r json code vars feats fmt _desc; do
        case ",$feats," in
            *,secure-boot,*)
                [ -f "$code" ] && [ -f "$vars" ] || continue
                ovmf_pair_status "$code" "$vars" >/dev/null || continue
                case "$(ovmf_vars_enrollment "$vars")" in
                    ENROLLED*)
                        best_code=$code; best_vars=$vars
                        best_ev="descriptor-backed secure-boot with enrolled keys ($(basename "$json")) - BEST"
                        break
                        ;;
                esac
                ;;
        esac
    done < <(ovmf_descriptor_pairs)
    if [ -z "$best_code" ]; then
        while IFS= read -r code_file; do
            case "$(basename "$code_file")" in *CODE*secboot*) ;; *) continue ;; esac
            case "$(ovmf_sb_capability "$code_file")" in yes*) ;; *) continue ;; esac
            vars_file=$(find_vars_for_code "$code_file")
            [ -n "$vars_file" ] || continue
            best_code=$code_file; best_vars=$vars_file
            best_ev="Secure Boot capable CODE; varstore may need enrollment (see check-ovmf-enrollment.sh)"
            break
        done <<< "$code_files"
    fi
    if [ -n "$best_code" ]; then
        echo -e "  ${BOLD}$best_ev${NC}"
        echo -e "  ${CYAN}CODE:${NC} $best_code ($(ovmf_human_size "$(ovmf_file_size "$best_code")"))"
        echo -e "  ${CYAN}VARS:${NC} $best_vars ($(ovmf_human_size "$(ovmf_file_size "$best_vars")"))"
        local secure_attr=no
        case "$(ovmf_sb_capability "$best_code")" in yes*) secure_attr=yes ;; esac
        echo
        echo -e "${BOLD}XML Configuration Snippet:${NC}"
        echo -e "${CYAN}────────────────────────────────────────────────────${NC}"
        cat << XMLSNIPPET
  <os>
    <type arch="x86_64" machine="pc-q35-10.1">hvm</type>
    <loader readonly="yes" secure="$secure_attr" type="pflash">$best_code</loader>
    <nvram template="$best_vars">/var/lib/libvirt/qemu/nvram/Xbox_VARS.fd</nvram>
    <bootmenu enable="yes"/>
  </os>
XMLSNIPPET
        echo -e "${CYAN}────────────────────────────────────────────────────${NC}"

        cat > /tmp/ovmf-paths.txt << EOF

CODE_PATH=$best_code
VARS_PATH=$best_vars
SECURE_BOOT=$secure_attr
TYPE=$best_ev

EOF
        echo
        echo -e "${GREEN}[ok] Paths saved to: ${NC}${CYAN}/tmp/ovmf-paths.txt${NC}"
    else
        echo -e "${RED}[x] Could not find a verified usable CODE/VARS pair!${NC}"
        echo -e "${YELLOW}Ensure it is in PACKAGES.md: ${NC}${CYAN}edk2-ovmf${NC}"
        exit 1
    fi

    echo -e "\n${BOLD}${GREEN}════════════════════════════════════════════════════${NC}\n"
}

# Library guard: run the UI only when executed directly.
if [ "${BASH_SOURCE[0]}" = "$0" ]; then
    ovmf_main "$@"
fi

# AI-hint: A migration script that replaces a broken manual ReadKey loop with Read-Host -MaskInput in mios-build-local.ps1 to ensure pasted tokens are correctly captured in PowerShell 7.x.
# AI-related: mios-build-local
<#
.SYNOPSIS  Fix token paste bug in mios-build-local.ps1
.DESCRIPTION
    The [Console]::ReadKey loop doesn't detect Enter after paste in PS 7.6.
    Replace with Read-Host -MaskInput (PS 7.1+, handles paste natively).

    Run from repo root:
      cd $env:USERPROFILE\OneDrive\Documents\GitHub\MiOS   # or wherever the repo is
      .\fix-token-input.ps1
#>
$ErrorActionPreference = "Stop"

if (-not (Test-Path "mios-build-local.ps1")) {
    Write-Host "  ERROR: Run from \MiOS repo root" -ForegroundColor Red; exit 1
}

$file = "mios-build-local.ps1"
$content = [System.IO.File]::ReadAllText((Resolve-Path $file).Path)

# Old: custom ReadKey loop that breaks on paste
$old = @'
        if ($Secret) {
            $secBuf = ""
            while ($true) {
                $key = [Console]::ReadKey($true)
                if ($key.Key -eq 'Enter') { Write-Host ""; break }
                if ($key.Key -eq 'Backspace') {
                    if ($secBuf.Length -gt 0) { $secBuf = $secBuf.Substring(0, $secBuf.Length - 1); Write-Host "`b `b" -NoNewline }
                } else {
                    $secBuf += $key.KeyChar; Write-Host "*" -NoNewline
                }
            }
            $buf = $secBuf
'@

# New: Read-Host -MaskInput (PS 7.1+, handles paste correctly)
$new = @'
        if ($Secret) {
            $buf = Read-Host -MaskInput
'@

if ($content.Contains($old)) {
    $content = $content.Replace($old, $new)
    [System.IO.File]::WriteAllText(
        (Resolve-Path $file).Path, $content,
        [System.Text.UTF8Encoding]::new($true)  # BOM for PS file
    )
    Write-Host "  [ok] Token input fixed: Read-Host -MaskInput (handles paste)" -ForegroundColor Green
} else {
    # Try with normalized line endings
    $content = $content -replace "`r`n", "`n"
    $old = $old -replace "`r`n", "`n"
    $new = $new -replace "`r`n", "`n"
    if ($content.Contains($old)) {
        $content = $content.Replace($old, $new)
        [System.IO.File]::WriteAllText(
            (Resolve-Path $file).Path, $content,
            [System.Text.UTF8Encoding]::new($true)
        )
        Write-Host "  [ok] Token input fixed (LF normalized)" -ForegroundColor Green
