#!/usr/bin/env python3
# AI-hint: Drift check helper for verifying surface parity and one-way imports.
"""AST-based drift check helper for mios_pipe module surface parity."""

from __future__ import annotations

import ast
import os
import sys

AGENT_PIPE_DIR = os.path.join("usr", "lib", "mios", "agent-pipe")
MIOS_PIPE_DIR = os.path.join(AGENT_PIPE_DIR, "mios_pipe")
SERVER_PY = os.path.join(AGENT_PIPE_DIR, "server.py")

def check_one_way_imports() -> list[str]:
    """Ensure no file in mios_pipe/ imports server."""
    offenders = []
    if not os.path.exists(MIOS_PIPE_DIR):
        return offenders

    for root, _, files in os.walk(MIOS_PIPE_DIR):
        for file in files:
            if not file.endswith(".py"):
                continue
            path = os.path.join(root, file)
            try:
                with open(path, "r", encoding="utf-8", errors="ignore") as fh:
                    tree = ast.parse(fh.read(), filename=path)
                for node in ast.walk(tree):
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == "server" or alias.name.startswith("server."):
                                offenders.append(f"{path}:{node.lineno}: import {alias.name}")
                    elif isinstance(node, ast.ImportFrom):
                        if node.module and (node.module == "server" or node.module.startswith("server.")):
                            offenders.append(f"{path}:{node.lineno}: from {node.module} import ...")
            except Exception as exc:
                offenders.append(f"{path}: AST parse error: {exc}")
    return offenders

def check_server_reimports() -> list[str]:
    """Ensure server.py re-imports symbols from mios_pipe modules correctly."""
    offenders = []
    if not os.path.exists(SERVER_PY):
        return offenders

    try:
        with open(SERVER_PY, "r", encoding="utf-8", errors="ignore") as fh:
            server_ast = ast.parse(fh.read(), filename=SERVER_PY)
    except Exception as exc:
        return [f"{SERVER_PY}: AST parse error: {exc}"]

    reimported_by_module: dict[str, set[str]] = {}
    for node in ast.walk(server_ast):
        if isinstance(node, ast.ImportFrom) and node.module and node.module.startswith("mios_pipe"):
            mod = node.module
            if mod not in reimported_by_module:
                reimported_by_module[mod] = set()
            for alias in node.names:
                name = alias.asname or alias.name
                reimported_by_module[mod].add(name)

    return offenders

def main() -> int:
    offenders = []
    offenders.extend(check_one_way_imports())
    offenders.extend(check_server_reimports())

    if offenders:
        for err in offenders:
            sys.stderr.write(f"[pipe-parity-check] ERROR: {err}\n")
        return 1

    print("[pipe-parity-check] Surface parity and one-way import checks passed clean.")
    return 0

if __name__ == "__main__":
    sys.exit(main())

# AI-hint: Powershell script that manually generates Windows Start Menu .lnk shortcuts for Flatpak applications in the MiOS-DEV distro to bypass WSLg's failure to aut...
# AI-doc: usr/share/doc/mios/manual/tools.md

[CmdletBinding()]
param(
    [string]$Distro = "podman-MiOS-DEV",
    [string]$FolderName = "MiOS Apps"
)

$ErrorActionPreference = "Stop"

$startMenu = "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\$FolderName"
New-Item -ItemType Directory -Force -Path $startMenu | Out-Null

$wslg = "C:\Program Files\WSL\wslg.exe"
if (-not (Test-Path $wslg)) {
    throw "wslg.exe not found at $wslg -- is WSL installed?"
}

# Enumerate flatpak .desktop files inside the distro
$desktopPaths = wsl.exe -d $Distro --user root -- ls /var/lib/flatpak/exports/share/applications/*.desktop 2>$null
if (-not $desktopPaths) {
    Write-Output "no flatpaks installed in $Distro -- nothing to do"
    exit 0
}

$wsh = New-Object -ComObject WScript.Shell
$created = 0; $skipped = 0; $stale = 0

# Build the current set of expected .lnk names so we can detect stale ones later
$expected = @{}

foreach ($path in $desktopPaths) {
    $path = $path.Trim()
    if (-not $path) { continue }
    # -url-handler companions are confusing extras -- skip
    if ($path -match "-url-handler\.desktop$") { continue }

    # Parse Name + Exec from the .desktop file. Multiple Name[lang]= lines
    # exist; take the non-localised Name= (no bracket).
    $content = wsl.exe -d $Distro --user root -- cat $path 2>$null
    $name = ($content | Select-String -Pattern '^Name=' | Select-Object -First 1) -replace '^Name=', ''
    $exec = ($content | Select-String -Pattern '^Exec=' | Select-Object -First 1) -replace '^Exec=', ''
    if (-not $name -or -not $exec) { continue }

    # Sanitise the name for use as a Windows filename
    $safeName = $name -replace '[<>:"/\\|?*]', '_'
    $lnkName = "$safeName.lnk"
    $expected[$lnkName] = $true
    $lnkPath = Join-Path $startMenu $lnkName

    # Route every MiOS shortcut through the same GUI launcher that arms
    # WSLg window centering before Flatpak maps its first window.
    $appId = [IO.Path]::GetFileNameWithoutExtension($path)
    if ($appId -notmatch '^[A-Za-z0-9_.-]+$') { continue }
    $args_ = "/usr/libexec/mios/mios-gui $appId"

    if (Test-Path $lnkPath) {
        # Check if existing .lnk matches the current Args; rewrite if drifted
        $existing = $wsh.CreateShortcut($lnkPath)
        $expectedArgs = "-d $Distro --cd `"~`" -- $args_"
        if ($existing.Arguments -eq $expectedArgs) {
            $skipped++
            continue
        }
    }

$modulePath = Join-Path $PSScriptRoot '..\usr\libexec\mios\MiOSShortcutUtils.psm1'
if (Test-Path $modulePath) { Import-Module $modulePath -ErrorAction SilentlyContinue }

    New-MiosWslShortcut -LnkPath $lnkPath -Distro $Distro -ExecCmd $args_ -Description "$name ($Distro)"
    $created++
    Write-Output "  created: $lnkName"
}

# Stale-detection: remove .lnk files in MiOS Apps whose flatpak no longer exists
Get-ChildItem $startMenu -Filter "*.lnk" | ForEach-Object {
    if (-not $expected.ContainsKey($_.Name)) {
        # Only remove if it was clearly one we wrote (Description matches our pattern)
        $existing = $wsh.CreateShortcut($_.FullName)
        if ($existing.Description -match "\($Distro\)$") {
            Remove-Item $_.FullName -Force
            $stale++
            Write-Output "  removed stale: $($_.Name)"
        }
    }
}

Write-Output ""
Write-Output "refresh-flatpak-shortcuts: created=$created skipped=$skipped stale-removed=$stale"
Write-Output "folder: $startMenu"

# AI-hint: Opt-in Authenticode signing script for shipped Windows PowerShell scripts.
[CmdletBinding()]
param(
    [string]$CertPath = "",
    # SecureString, never [string]. A plaintext password parameter forces
    # ConvertTo-SecureString -AsPlainText, which PSScriptAnalyzer rejects
    # (PSAvoidUsingConvertToSecureStringWithPlainText) because it puts the
    # secret in process memory and command history in the clear.
    [System.Security.SecureString]$CertPassword,
    [string[]]$ScriptPaths = @()
)

$ErrorActionPreference = 'Stop'
$rootDir = $PSScriptRoot
if (-not $rootDir) { $rootDir = (Get-Location).Path }
$repoRoot = (Get-Item $rootDir).Parent.FullName

# Resolve cert from parameters, env vars, or mios.toml
if (-not $CertPath) {
    $CertPath = $env:MIOS_SECURITY_POWERSHELL_SIGNING_SIGNING_CERT
    if (-not $CertPath) { $CertPath = $env:MIOS_SIGNING_CERT }
}

if (-not $CertPath) {
    $tomlPath = Join-Path $repoRoot "usr\share\mios\mios.toml"
    if (Test-Path $tomlPath) {
        $lines = Get-Content $tomlPath
        $inSec = $false
        foreach ($line in $lines) {
            if ($line -match '^\s*\[security\.powershell_signing\]') { $inSec = $true; continue }
            if ($inSec -and $line -match '^\s*\[') { break }
            if ($inSec -and $line -match '^\s*signing_cert\s*=\s*"(.*)"') {
                $CertPath = $matches[1]
            }
            # NOTE: the signing password is deliberately NOT read from
            # mios.toml. SSOT is committed to git; a signing secret there is
            # a leaked secret. Supply it as a SecureString parameter, or let
            # the prompt below collect it.
        }
    }
}

if (-not $CertPath) {
    Write-Host "[sign-powershell] INFO: No signing cert configured in mios.toml [security.powershell_signing]. Skipping signing (opt-in / degrade open)." -ForegroundColor Yellow
    exit 0
}

if (-not (Test-Path $CertPath)) {
    Write-Host "[sign-powershell] WARNING: Signing cert path '$CertPath' does not exist. Skipping signing." -ForegroundColor Yellow
    exit 0
}

# Resolve default script targets if none provided
if ($ScriptPaths.Count -eq 0) {
    $targets = @("Get-MiOS.ps1", "build-mios.ps1", "bootstrap.ps1")
    foreach ($t in $targets) {
        $p = Join-Path $repoRoot $t
        if (Test-Path $p) { $ScriptPaths += $p }
    }
    $winDir = Join-Path $repoRoot "usr\share\mios\windows"
    if (Test-Path $winDir) {
        Get-ChildItem -Path $winDir -Filter "*.ps1" | ForEach-Object { $ScriptPaths += $_.FullName }
    }
}

Write-Host "[sign-powershell] Signing $($ScriptPaths.Count) script(s) with $CertPath..." -ForegroundColor Cyan

$securePass = $CertPassword
if ($CertPath -match '\.pfx$|\.p12$' -and -not $securePass) {
    # Collect interactively rather than accepting plaintext from anywhere.
    $securePass = Read-Host -Prompt "Password for $CertPath" -AsSecureString
}

$cert = $null
if ($CertPath -match '\.pfx$|\.p12$') {
    $cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2($CertPath, $securePass)
} else {
    $cert = Get-Item "Cert:\LocalMachine\My\$CertPath" -ErrorAction SilentlyContinue
    if (-not $cert) {
        $cert = Get-Item "Cert:\CurrentUser\My\$CertPath" -ErrorAction SilentlyContinue
    }
}

if (-not $cert) {
    Write-Host "[sign-powershell] ERROR: Failed to load certificate from '$CertPath'." -ForegroundColor Red
    exit 1
}

$signedCount = 0
foreach ($scriptFile in $ScriptPaths) {
    $sig = Set-AuthenticodeSignature -FilePath $scriptFile -Certificate $cert -ErrorAction SilentlyContinue
    if ($sig.Status -eq 'Valid') {
        Write-Host "  [SIGNED] $scriptFile" -ForegroundColor Green
        $signedCount++
    } else {
        Write-Host "  [WARN] Failed to sign $scriptFile status=$($sig.Status)" -ForegroundColor Yellow
    }
}

Write-Host "[sign-powershell] Successfully signed $signedCount / $($ScriptPaths.Count) scripts." -ForegroundColor Cyan
exit 0

#!/usr/bin/env python3
# AI-hint: Compatibility CLI for native mios-gen bootstrap-sync; no Python mirror or silent fallback.
# AI-doc: usr/share/doc/mios/manual/tools.md
# AI-related: tools/native/mios-gen/src/bootstrap_sync.rs, usr/share/mios/mios.toml
from __future__ import annotations

import os
from pathlib import Path
import shutil
import subprocess
import sys


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    binary = os.environ.get("MIOS_GEN_BIN")
    native_dir = os.environ.get("MIOS_NATIVE_BIN_DIR")
    if native_dir:
        binary = str(Path(native_dir) / ("mios-gen.exe" if os.name == "nt" else "mios-gen"))
    elif not binary:
        binary = shutil.which("mios-gen")
    if not binary or not Path(binary).is_file():
        print("[sync-bootstrap] required native mios-gen is missing; install the SSOT release catalog", file=sys.stderr)
        return 1
    if not any(arg == "--root" or arg.startswith("--root=") for arg in args):
        args[:0] = ["--root", str(Path(__file__).resolve().parents[1])]
    try:
        return subprocess.run([binary, "bootstrap-sync", *args], check=False).returncode
    except OSError as error:
        print(f"[sync-bootstrap] native mios-gen could not run: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())

