#!/usr/bin/env python3
# AI-hint: Sibling test for tools/generate-gate-index.py; proves a row never carries a description belonging to another check.
# AI-related: tools/native/mios-gen/src/indexes.rs, automation/98-drift-checks.sh
"""Each case is a row the index must NOT emit.

An index row is the only published description of a gate, so a row describing
the wrong check is worse than a terse one: it is read as the check's contract.
"""
import os
import shutil
import subprocess
import tempfile
import unittest

_HERE = os.path.dirname(os.path.abspath(__file__))
_ROOT = os.path.dirname(_HERE)

GATE = """\
# --- described neighbour ---
check_described() {
    echo "[98-drift-checks] described neighbour"
}

check_one_liner() { _run_py_check check_one_liner tools/fake-tool.py; }

check_sub_command() { _run_py_check check_sub_command "tools/fake-multi.py a-subcommand"; }

check_flagged() { _run_py_check check_flagged "tools/fake-tool.py --check"; }

check_elided() { _run_py_check check_elided tools/fake-elided.py; }

# --- a later multi-line check with its own echo ---
check_later() {
    echo "[98-drift-checks] a later multi-line check with its own echo"
}
main() {
    check_described
    check_one_liner
    check_sub_command
    check_flagged
    check_elided
    check_later
}
"""

class TestDescription(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.TemporaryDirectory()
        cls.addClassCleanup(cls.tmp.cleanup)
        cls.root = cls.tmp.name
        os.makedirs(os.path.join(cls.root, "tools"))
        for name, hint in (
                ("fake-tool.py", "Drift gate for a fake thing. And more prose"),
                ("fake-multi.py", "Module that runs many unrelated checks"),
                ("fake-elided.py", "A hint the tagger cut off mid-sent...")):
            with open(os.path.join(cls.root, "tools", name), "w") as fh:
                fh.write("#!/usr/bin/env python3\n# AI-hint: %s\n" % hint)
        os.makedirs(os.path.join(cls.root, "automation"))
        with open(os.path.join(cls.root, "automation", "98-drift-checks.sh"), "w", encoding="utf-8", newline="\n") as fh:
            fh.write(GATE)
        binary = os.environ.get("MIOS_GEN_BIN") or shutil.which("mios-gen")
        if not binary:
            raise AssertionError("mios-gen is required to verify the production gate index")
        subprocess.run([binary, "gate-index", "--root", cls.root], check=True, capture_output=True, text=True)
        with open(os.path.join(cls.root, "usr/share/mios/reference/drift-gate-index.tsv"), encoding="utf-8") as fh:
            cls.descriptions = {row[1]: row[2] for line in fh if not line.startswith("#")
                                for row in [line.rstrip("\n").split("\t")]}

    @classmethod
    def tearDownClass(cls):
        cls.tmp.cleanup()

    def _desc(self, name):
        return self.descriptions[name]

    def test_a_comment_above_the_definition_wins(self):
        self.assertEqual("described neighbour", self._desc("check_described"))

    def test_a_one_liner_does_not_inherit_the_next_functions_echo(self):
        """The defect: `(.*?)\\n\\}` ran past a one-liner into check_later."""
        got = self._desc("check_one_liner")
        self.assertNotIn("later multi-line", got)
        self.assertNotIn("described neighbour", got)
        self.assertEqual("Drift gate for a fake thing", got)

    def test_a_sub_command_does_not_borrow_the_modules_hint(self):
        self.assertEqual("sub command", self._desc("check_sub_command"))

    def test_a_flag_still_describes_the_tool(self):
        self.assertEqual("Drift gate for a fake thing", self._desc("check_flagged"))

    def test_an_elided_hint_is_not_republished(self):
        self.assertEqual("elided", self._desc("check_elided"))

    def test_the_shipped_index_has_no_two_checks_sharing_a_description(self):
        seen = {}
        path = os.path.join(_ROOT, "usr/share/mios/reference/drift-gate-index.tsv")
        with open(path, encoding="utf-8") as fh:
            rows = [l.rstrip("\n").split("\t") for l in fh
                    if l.strip() and not l.startswith("#")]
        self.assertGreater(len(rows), 100, "the index did not load")
        for row in rows:
            self.assertEqual(3, len(row), row)
            seen.setdefault(row[2], []).append(row[1])
        shared = {d: n for d, n in seen.items() if len(n) > 1}
        self.assertEqual({}, shared, "checks sharing one description")

if __name__ == "__main__":
    unittest.main(verbosity=1)

#!/usr/bin/env python3
# AI-hint: Verify actual monitor lifecycle restores caller signal handlers before launching another terminal client, including real Linux Textual stale-handler failure.
# AI-related: usr/libexec/mios/mios-mon.py
import ast
import subprocess
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

def load_runner(env):
    source = ROOT / 'usr/libexec/mios/mios-mon.py'
    function = next(n for n in ast.parse(source.read_text(encoding='utf-8')).body
                    if isinstance(n, ast.FunctionDef) and n.name == '_run_monitor_app')
    exec(compile(ast.Module(body=[function], type_ignores=[]), str(source), 'exec'), env)
    return env['_run_monitor_app']

class Signals:
    SIGINT, SIGTERM, SIGCONT = 2, 15, 18
    def __init__(self):
        self.handlers = {2: object(), 15: object(), 18: object()}
    def getsignal(self, number):
        return self.handlers[number]
    def signal(self, number, handler):
        self.handlers[number] = handler

class TestMonitorLifecycle(unittest.TestCase):
    def test_restores_handlers_after_selection_and_failed_constructor(self):
        for fail in (None, "constructor", "run"):
            signals = Signals()
            previous = dict(signals.handlers)
            class App:
                def __init__(self, **kwargs):
                    signals.signal(signals.SIGCONT, object())
                    if fail == "constructor":
                        raise RuntimeError('constructor failed')
                def run(self):
                    signals.signal(signals.SIGINT, object())
                    if fail == 'run':
                        raise RuntimeError('run failed')
                    return 'opencode'
            run = load_runner(dict(signal=signals, MiosMonitorApp=App))
            if fail:
                with self.assertRaisesRegex(RuntimeError, fail + ' failed'):
                    run(ui_mode='clients')
            else:
                self.assertEqual(run(ui_mode='clients'), 'opencode')
            self.assertEqual(signals.handlers, previous)

    @unittest.skipUnless(sys.platform.startswith('linux'), 'Linux Textual signal regression')
    def test_real_textual_resume_callback_is_removed_before_child_execution(self):
        probe = r"""
import os, signal
from textual.drivers.linux_driver import LinuxDriver
from test_monitor_runtime import load_runner
calls=[]
original=signal.getsignal(signal.SIGCONT)
def prior(*args): calls.append(True)
signal.signal(signal.SIGCONT,prior)
class App:
 def __init__(self,**kwargs):
  self.driver=LinuxDriver.__new__(LinuxDriver)
  self.driver._auto_restart=True
  self.driver.fileno=0
 def run(self):
  signal.signal(signal.SIGCONT,self.driver._sigcont_application)
  return 'opencode'
try:
 run=load_runner(dict(signal=signal,MiosMonitorApp=App))
 assert run()=='opencode'
 os.kill(os.getpid(),signal.SIGCONT)
 assert calls==[True]
 # Negative control: the real stale driver callback reproduces the report.
 App().run()
 try: os.kill(os.getpid(),signal.SIGCONT)
 except RuntimeError as error: assert 'no running event loop' in str(error)
 else: raise AssertionError('stale Textual handler did not reproduce')
finally: signal.signal(signal.SIGCONT,original)
"""
        subprocess.run([sys.executable, '-c', probe], cwd=ROOT / 'tools',
                       check=True, timeout=15, capture_output=True, text=True)

if __name__ == '__main__':
    unittest.main()

#!/usr/bin/env python3
# AI-hint: Validates verb command templates against declared verb arguments and synonyms at build time.
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "usr", "lib", "mios", "agent-pipe"))

try:
    import tomllib
except ImportError:
    import tomli as tomllib

from mios_template import compile_template, _TEMPLATE_PH_RE

def main():
    root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
    toml_path = os.path.join(root, "usr", "share", "mios", "mios.toml")
    if not os.path.isfile(toml_path):
        print(f"ERROR: SSOT toml file not found at {toml_path}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(toml_path, "rb") as f:
            data = tomllib.load(f)
    except Exception as e:
        print(f"ERROR: Failed to parse {toml_path}: {e}", file=sys.stderr)
        sys.exit(1)

    verbs = data.get("verbs", {})
    if not verbs:
        print("ERROR: No [verbs] section in mios.toml", file=sys.stderr)
        sys.exit(1)

    errors = []

    for vname, vspec in verbs.items():
        if not isinstance(vspec, dict):
            continue

        cmd_keys = [k for k in ("cmd", "cmd_args", "cmd_positioned", "cmd_pixel", "cmd_resize") if k in vspec]
        for k in cmd_keys:
            tmpl_str = vspec[k]
            if not isinstance(tmpl_str, str):
                continue

            if tmpl_str.count("{") != tmpl_str.count("}"):
                errors.append(f"Verb '{vname}' field '{k}' template has unclosed or mismatched braces: '{tmpl_str}'")
                continue

            try:
                ct = compile_template(tmpl_str)
            except Exception as e:
                errors.append(f"Verb '{vname}' field '{k}' template unparseable: {e}")
                continue

    if errors:
        for err in errors:
            print(f"::error::{err}", file=sys.stderr)
        sys.exit(1)

    print("[verb-template-check] PASS: All verb templates compiled and validated clean.")
    sys.exit(0)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# AI-hint: Verifies the built deployment artifacts against the SSOT format matrix; an empty or partial build tree is a failure that names the formats that produced nothing.
# AI-related: usr/share/mios/mios.toml, Justfile, tools/check-runtime.py
"""Verify every deployment format the SSOT declares actually produced a file.

The gate this replaces walked a glob list and ended on the failure counter, so
a tree with no artifacts in it counted zero failures and returned success --
and `publish` depends on it to prove the artifacts are real before the push.
The required set is now derived from `[deploy.formats]`: every format that
declares output globs must match at least one file, that file must clear the
size floor, and its leading bytes must be the ones its format is defined by.
"""
import glob
import os
import sys

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover - Python < 3.11
    import tomli as tomllib  # type: ignore

# What each format is, in bytes. The check it replaces read a header, printed
# it and compared it against nothing, so two megabytes of zeroes named
# disk.qcow2 passed. Each entry is (offset, expected); a negative offset is
# measured back from the end of the file, and a tuple of entries passes when
# any one of them matches.
MAGIC = {
    ".iso":    ((32769, b"CD001"),),
    ".qcow2":  ((0, b"QFI\xfb"),),
    ".vhdx":   ((0, b"vhdxfile"),),
    ".vhd":    ((-512, b"conectix"), (0, b"conectix")),
    ".gz":     ((0, b"\x1f\x8b"),),
    ".tar":    ((257, b"ustar"),),
    ".wsl2":   ((0, b"\x1f\x8b"), (257, b"ustar")),
    # A whole-disk image has no format magic of its own; what it must have is a
    # partition table, either a GPT header or an MBR boot signature.
    ".raw":    ((512, b"EFI PART"), (510, b"\x55\xaa")),
}

def _read_at(path, offset, length):
    with open(path, "rb") as fh:
        if offset < 0:
            fh.seek(offset, os.SEEK_END)
        else:
            fh.seek(offset)
        return fh.read(length)

def _suffix(path):
    base = os.path.basename(path)
    if base.endswith(".tar.gz"):
        return ".gz"
    return os.path.splitext(base)[1].lower()

def _magic_ok(path):
    """(passed, description). An unknown suffix is not a pass."""
    suf = _suffix(path)
    want = MAGIC.get(suf)
    if want is None:
        return False, "no magic is defined for %s" % (suf or "a suffix-less file")
    for offset, expected in want:
        try:
            got = _read_at(path, offset, len(expected))
        except OSError as exc:
            return False, "unreadable (%s)" % exc
        if got == expected:
            return True, "%s at %d" % (expected.hex(), offset)
    return False, "none of the %s signatures are present" % suf

def load_ssot(root):
    with open(os.path.join(root, "usr/share/mios/mios.toml"), "rb") as fh:
        return tomllib.load(fh)

def required_formats(ssot):
    """{format name: [globs]} for every format that writes a file."""
    formats = (ssot.get("deploy") or {}).get("formats") or {}
    out = {}
    for name, spec in sorted(formats.items()):
        if not isinstance(spec, dict):
            continue
        globs = spec.get("artifacts")
        if globs:
            out[name] = list(globs)
    return out

def verify(root, outdir):
    ssot = load_ssot(root)
    required = required_formats(ssot)
    floor = int(((ssot.get("deploy") or {}).get("verify") or {}).get("min_bytes", 0))

    print("[verify] Walking %s against the %d file format(s) [deploy.formats] declares"
          % (outdir, len(required)))
    if not required:
        print("  [FAIL] [deploy.formats] declares no file-producing format, so this"
              " gate would pass over anything at all")
        return 1

    missing, bad, ok = [], [], 0
    for name, globs in sorted(required.items()):
        found = []
        for pattern in globs:
            found.extend(glob.glob(os.path.join(outdir, *pattern.split("/"))))
        found = sorted({f for f in found if os.path.isfile(f)})
        if not found:
            missing.append((name, globs))
            print("  [MISSING] %-14s nothing matched %s"
                  % (name, ", ".join(globs)))
            continue
        for path in found:
            rel = os.path.relpath(path, outdir).replace(os.sep, "/")
            size = os.path.getsize(path)
            if size < floor:
                bad.append((name, rel, "%d bytes is under the %d-byte floor" % (size, floor)))
                print("  [FAIL] %-14s %s: %d bytes, under the %d-byte floor"
                      % (name, rel, size, floor))
                continue
            good, why = _magic_ok(path)
            if not good:
                bad.append((name, rel, why))
                print("  [FAIL] %-14s %s: %s" % (name, rel, why))
                continue
            print("  [OK]   %-14s %-44s %15d bytes  magic=%s" % (name, rel, size, why))
            ok += 1

    print("")
    print("[verify] %d artifact(s) passed, %d failed, %d declared format(s) produced nothing"
          % (ok, len(bad), len(missing)))
    if missing:
        print("[verify] FAIL: no artifact for %s" % ", ".join(n for n, _ in missing))
    if not ok and not bad:
        print("[verify] FAIL: nothing was verified. An empty build tree is not a"
              " pass -- run 'just all' before publishing.")
    if missing or bad:
        return 1
    print("[verify] PASS: every declared format produced a real artifact")
    return 0

def main(argv):
    # The checkout this script belongs to, not MIOS_ROOT: on an installed
    # system that points at the running image, whose build tree is not the one
    # being published.
    root = (os.environ.get("MIOS_DRIFT_ROOT")
            or os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
    outdir = None
    args = list(argv)
    while args:
        arg = args.pop(0)
        if arg == "--root":
            root = args.pop(0)
        elif arg == "--output-dir":
            outdir = args.pop(0)
        else:
            print("usage: verify-images.py [--root DIR] [--output-dir DIR]",
                  file=sys.stderr)
            return 2
    if outdir is None:
        ssot = load_ssot(root)
        sub = ((ssot.get("build") or {}).get("artifacts") or {}).get("output_dir", "build")
        outdir = os.path.join(root, sub)
    return verify(root, outdir)

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/usr/bin/env python3
# AI-hint: A utility script that uses regex to wrap the "MiOS" proper noun in single quotes in documentation and config files to ensure legal-attribution co...
# AI-doc: usr/share/doc/mios/manual/lib.md

import re, sys
from pathlib import Path

_LIT = "M" + "iOS"
PATTERN = re.compile(rf"(?<!['\w\"/\\]){_LIT}(?![-./\\\w'\"])")
REPLACE = f"'{_LIT}'"

ALLOW_EXT = {
    ".md", ".sh", ".ps1", ".py", ".toml", ".conf", ".service",
    ".target", ".container", ".preset", ".txt", ".rules", ".cfg",
}
ALLOW_NAMES = {"Containerfile", "Justfile"}

def is_allowed(path: Path) -> bool:
    if path.name in ALLOW_NAMES:
        return True
    if path.suffix in ALLOW_EXT:
        return True
    return False

def process(path: Path) -> int:
    """Return number of replacements made."""
    try:
        text = path.read_text(encoding="utf-8")
    except (UnicodeDecodeError, IsADirectoryError, PermissionError):
        return 0
    new, n = PATTERN.subn(REPLACE, text)
    if n:
        path.write_text(new, encoding="utf-8")
    return n

if __name__ == "__main__":
    total_files = 0
    total_subs = 0
    for arg in sys.argv[1:]:
        p = Path(arg)
        if not p.is_file():
            continue
        if not is_allowed(p):
            continue
        n = process(p)
        if n:
            print(f"{n:4d}  {arg}")
            total_files += 1
            total_subs += n
    print(f"\n{total_subs} replacements across {total_files} files", file=sys.stderr)

